  function kitlabBuildBasicModularTemplate() {
    const base = JSON.parse(JSON.stringify(BASIC_ZERO_TEMPLATE || {}));
    const inferPart = (meta = {}) => {
      const section = String(meta.section || "").toLowerCase();
      const text = `${meta.modularPart || ""} ${section} ${meta.originalPath || ""} ${meta.path || ""} ${meta.rawName || ""} ${meta.name || ""}`
        .toLowerCase()
        .replace(/[_\-]+/g, " ");
      if (section === "socks" || /\b(socks?|ankle|calcetin|medias?)\b/.test(text)) return "socks";
      if (section === "short" || /\b(shorts?|pantalon|pantalón)\b/.test(text)) {
        if (/\b(sleeve|manga|camiseta|shirt|jersey|collar|cuello)\b/.test(text)) return "shirt";
        return "short";
      }
      if (section === "collar" || /\b(collar|cuello|shirt|jersey|camiseta|sleeve|manga|shoulder|hombro|cuff|puño|puno|hem|final)\b/.test(text)) return "shirt";
      return "shirt";
    };
    const cloneWithPart = (meta = {}, fallbackPart = null) => {
      const part = fallbackPart || inferPart(meta);
      const clone = { ...meta, modularPart: part };
      if (!clone.sourceName) clone.sourceName = meta.originalPath || meta.rawName || meta.name || meta.path || "";
      if (!clone.directiveSource) clone.directiveSource = clone.sourceName;
      return clone;
    };
    const modular = {
      ...base,
      name: "Basic",
      brand: "basic",
      path: "assets/templates/basic/basic",
      thumb: base.thumb || "assets/templates/basic/basic/thumbnails.png",
      isModularTemplate: true,
      modularTemplate: true,
      templateGalleryModes: ["players", "goalkeepers"],
      basePieces: {},
      details: [],
      seams: [],
      transparency: [],
      guides: [],
      patterns: [],
      modularParts: {
        shirt: { name: "Basic", part: "shirt", thumb: base.basePieces?.shirt?.path || base.thumb || "assets/templates/basic/basic/thumbnails.png" },
        short: { name: "Basic", part: "short", thumb: base.basePieces?.short?.path || base.thumb || "assets/templates/basic/basic/thumbnails.png" },
        socks: { name: "Basic", part: "socks", thumb: base.basePieces?.socks?.path || base.thumb || "assets/templates/basic/basic/thumbnails.png" },
      },
    };
    const basePartMap = {
      sleeve_short: "shirt",
      shirt: "shirt",
      sleeve_long: "shirt",
      short: "short",
      socks: "socks",
      ankle: "socks",
    };
    Object.entries(base.basePieces || {}).forEach(([pieceId, piece]) => {
      modular.basePieces[pieceId] = cloneWithPart(piece, basePartMap[pieceId] || inferPart(piece));
    });
    modular.details = (base.details || []).map((layer) => cloneWithPart(layer));
    modular.seams = (base.seams || []).map((layer) => cloneWithPart(layer));
    // Basic has one global transparency mask. Duplicate it per modular zone so a Basic
    // Shirt/Short/Socks part can be saved and restored independently in combinations.
    (base.transparency || []).forEach((layer) => {
      modular.transparency.push(cloneWithPart(layer, "shirt"));
      modular.transparency.push(cloneWithPart(layer, "short"));
      modular.transparency.push(cloneWithPart(layer, "socks"));
    });
    modular.guides = (base.guides || []).map((layer) => cloneWithPart(layer, "shirt"));
    modular.patterns = (base.patterns || []).map((layer) => cloneWithPart(layer, "shirt"));
    modular.collars = Array.isArray(base.collars) ? base.collars.map((collar) => JSON.parse(JSON.stringify(collar))) : [];
    return modular;
  }
  const BASIC_MODULAR_TEMPLATE = kitlabBuildBasicModularTemplate();

