  // v1.3.164: Joma GK 26/27 V2 inserted as a separate non-modular goalkeeper template.
  const JOMA_GK_26_27_V2_TEMPLATE = JSON.parse(JSON.stringify(JOMA_GK_26_27_TEMPLATE));
  (function kitlabInitJomaGk2627V2Template(template) {
    const oldBase = "assets/templates/joma/joma%20gk%2026-27";
    const newBase = "assets/templates/joma/joma%20gk%2026-27%20v2";
    function replaceBase(value) {
      return typeof value === "string" ? value.replaceAll(oldBase, newBase) : value;
    }
    function walk(value) {
      if (Array.isArray(value)) {
        value.forEach(walk);
        return;
      }
      if (!value || typeof value !== "object") return;
      Object.keys(value).forEach((key) => {
        if (typeof value[key] === "string") value[key] = replaceBase(value[key]);
        else walk(value[key]);
      });
    }
    // v1.3.170: replace the cloned Joma GK 26/27 paths before assigning the V2 root fields.
    // Assigning template.path/thumb first and then walking doubled the path to ...V2%20V2,
    // which broke used_by.txt and other root-level assets even when the files existed.
    walk(template);
    template.name = "Joma GK 26-27 V2";
    template.galleryName = "Joma GK 26/27 V2";
    template.path = newBase;
    template.thumb = `${newBase}/thumbnail.png`;
    // v1.3.167: Joma GK 26/27 V2 gallery thumbnail fallback chain.
    // Some local copies can keep the template files but miss or cache the exact root thumbnail path.
    // Try common thumbnail spellings first, then fall back to the shirt base so the card never shows broken.
    template.thumbFallbacks = [
      `${newBase}/thumbnail.PNG`,
      `${newBase}/thumbnails.png`,
      `${newBase}/thumbnails.PNG`,
      `${newBase}/thumb.png`,
      `${newBase}/preview.png`,
      `${newBase}/base/02.%20shirt.png`,
    ];
    // v1.3.169: used_by must come only from the physical used_by.txt file.
    // No inline/default fallback: if the TXT is missing, the popover stays disabled.
    delete template.usedByLines;
    delete template.usedByText;
    template.templateGalleryModes = ["goalkeepers"];
  })(JOMA_GK_26_27_V2_TEMPLATE);


  function layerNameCandidates(layer = null) {
    if (!layer) return [];
    return [
      layer.name,
      layer.rawName,
      layer.originalPath,
      layer.sourceName,
      layer.directiveSource,
      layer.path,
    ];
  }

  function isSleeveShortShadowLayerName(value = "") {
    const clean = String(value || "").replace(/[_-]+/g, " ");
    return /\bsleeve\s*short\s*shadow\b/i.test(clean);
  }

  function isSleeveLongShadowLayerName(value = "") {
    const clean = String(value || "").replace(/[_-]+/g, " ");
    return /\bsleeves?\s*long\s*sleeve\s*shadow\b/i.test(clean);
  }

  function enforceSleeveShortShadowColorLayer(layer = null) {
    if (!layer) return layer;
    if (!layerNameCandidates(layer).some(isSleeveShortShadowLayerName)) return layer;
    layer.blend = false;
    layer.opacityCtl = false;
    layer.opacity = 1;
    layer.noColor = false;
    delete layer.blendMode;
    return layer;
  }

  function enforceSleeveLongShadowFusionOpacityLayer(layer = null) {
    if (!layer) return layer;
    if (!layerNameCandidates(layer).some(isSleeveLongShadowLayerName)) return layer;
    // v1.3.162: shirt Shadow is a normal colorable detail.
    // It must enter exactly like the original PNG: no Fusion, no Opacity control,
    // visible color chip, and Normal/source-over rendering.
    layer.blend = false;
    layer.opacityCtl = false;
    layer.opacity = 1;
    layer.noColor = false;
    delete layer.blendMode;
    return layer;
  }


  function isButtonShineLayerName(value = "") {
    const clean = String(value || "")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
    return /\bbutton\b/.test(clean) && /\b(brillinest|brillo|shine|highlight|glow)\b/.test(clean);
  }

  function normalizeButtonShineAssetPath(value = "") {
    let out = String(value || "");
    if (!out) return out;
    out = out.replace(/button(?:%20|\s+)brillinest\.png/gi, "button%20shine.png");
    out = out.replace(/button(?:%20|\s+)shine\.png/gi, "button%20shine.png");
    if (/assets\/templates\/Puma\/Puma(?:%20|\s+)26-27/i.test(out) && /\/collar\/3_NO\/button\//i.test(out)) {
      out = "assets/templates/puma/puma%202026/collar/03_no/button/button%20shine.png";
    }
    return out;
  }

  function normalizeButtonShineOriginalPath(value = "") {
    let out = String(value || "");
    if (!out) return out;
    out = out.replace(/button\s+brillinest\.png/gi, "button shine.png");
    out = out.replace(/button%20brillinest\.png/gi, "button shine.png");
    return out;
  }

  function templateLayerIsButtonShine(meta = {}) {
    return layerNameCandidates(meta).some(isButtonShineLayerName) || isButtonShineLayerName(templateLayerDirectiveText(meta));
  }

  function enforceButtonShineWhiteLayer(layer = null) {
    if (!layer) return layer;
    if (!layerNameCandidates(layer).some(isButtonShineLayerName)) return layer;
    layer.name = "Button Shine";
    // Button Shine is a technical white PNG: keep original white pixels,
    // but still expose Fusion + Opacity controls in the web UI.
    layer.blend = true;
    layer.opacityCtl = true;
    layer.opacity = Number(layer.opacity ?? 1);
    layer.noColor = true;
    if (!layer.blendMode) layer.blendMode = "source-over";
    layer.palette = [];
    layer.colorMap = {};
    layer._templateChipColor = "#ffffff";
    ["path", "src"].forEach((key) => {
      if (layer[key]) layer[key] = normalizeButtonShineAssetPath(layer[key]);
    });
    ["rawName", "originalPath", "sourceName", "directiveSource"].forEach((key) => {
      if (layer[key]) layer[key] = normalizeButtonShineOriginalPath(layer[key]);
    });
    if (layer.rawName && /button\s+shine\.png/i.test(layer.rawName)) layer.rawName = "button shine.png";
    return layer;
  }

  function enforceShadowLayerRulesInTemplate(template = null) {
    if (!template) return template;
    const groups = [
      template.details,
      template.layers,
      template.patterns,
      template.mesh,
      template.brand,
    ];
    groups.forEach((group) => {
      if (!Array.isArray(group)) return;
      group.forEach((layer) => {
        enforceSleeveShortShadowColorLayer(layer);
        enforceSleeveLongShadowFusionOpacityLayer(layer);
        enforceButtonShineWhiteLayer(layer);
      });
    });
    if (Array.isArray(template.collars)) {
      template.collars.forEach((collar) => {
        if (!Array.isArray(collar.details)) return;
        collar.details.forEach((layer) => {
          enforceSleeveShortShadowColorLayer(layer);
          enforceSleeveLongShadowFusionOpacityLayer(layer);
          enforceButtonShineWhiteLayer(layer);
        });
      });
    }
    return template;
  }

  // Backward-compatible aliases for older patch lines.
  const isAlwaysColorShadowLayerName = isSleeveShortShadowLayerName;
  const enforceAlwaysColorShadowLayer = enforceSleeveShortShadowColorLayer;
  const enforceAlwaysColorShadowLayersInTemplate = enforceShadowLayerRulesInTemplate;
  const enforceSleeveShortShadowColorLayersInTemplate = enforceShadowLayerRulesInTemplate;



