  function kitlabTemplateUsesPuma2026SharedCollars(item = null) {
    if (!item) return false;
    const brand = String(item.brand || "").toLowerCase();
    const text = decodeURIComponent(String(`${item.name || ""} ${item.galleryName || ""} ${item.path || ""}`)).toLowerCase().replace(/[_\-]+/g, " ");
    return brand === "puma" && /\b26\s*27\b/.test(text) && /\bultraweave(?:r)?\b/.test(text) && !/\bdry\s*cell\b|\bdrycell\b/.test(text);
  }

  function kitlabCloneCollarList(collars = []) {
    try {
      return JSON.parse(JSON.stringify(Array.isArray(collars) ? collars : []));
    } catch (error) {
      return (Array.isArray(collars) ? collars : []).map((collar) => ({ ...collar }));
    }
  }

  function kitlabApplyPuma2026SharedCollarsToTemplate(item = null) {
    if (!kitlabTemplateUsesPuma2026SharedCollars(item)) return false;
    const sharedSource = PUMA_2026_TEMPLATE || null;
    const alreadyShared = item.__kitlabSharedCollarSource === "Puma 2026" && Array.isArray(item.collars) && item.collars.length && item.collars.every((collar) => {
      const text = String(`${collar?.thumb || ""} ${(collar?.details || []).map((meta) => meta?.path || "").join(" ")}`).toLowerCase();
      return text.includes("puma%202026") || text.includes("puma 2026");
    });
    if (!alreadyShared) {
      const sharedCollars = kitlabCloneCollarList(sharedSource?.collars || []);
      if (!sharedCollars.length) return false;
      item.collars = sharedCollars;
    }
    item.collarCategories = Array.isArray(sharedSource?.collarCategories) ? sharedSource.collarCategories.slice() : [];
    item.sharedCollarSettingsBaseId = "assets/templates/puma/puma%202026";
    item.initialCollarSettingsBaseId = "assets/templates/puma/puma%202026";
    item.__kitlabSharedCollarSource = "Puma 2026";
    return true;
  }

  function kitlabApplyPuma2026SharedCollars() {
    const targets = [
      PUMA_26_27_ULTRAWEAVE_TEMPLATE,
      ...(Array.isArray(INTERNAL_TEMPLATES) ? INTERNAL_TEMPLATES : []),
      ...(Array.isArray(TEMPLATE_STYLE_MANIFESTS) ? TEMPLATE_STYLE_MANIFESTS : []),
    ];
    targets.forEach((item) => kitlabApplyPuma2026SharedCollarsToTemplate(item));
  }


  function kitlabTemplateUsesPuma2627DryCellSharedCollars(item = null) {
    if (!item) return false;
    const brand = String(item.brand || "").toLowerCase();
    const text = decodeURIComponent(String(`${item.name || ""} ${item.galleryName || ""} ${item.path || ""}`)).toLowerCase().replace(/[_\-]+/g, " ");
    return brand === "puma" && /\b26\s*27\b/.test(text) && /\bv2\b/.test(text) && (/\bdry\s*cell\b|\bdrycell\b|\bdricell\b/.test(text));
  }

  function kitlabApplyPuma2627DryCellSharedCollarsToTemplate(item = null) {
    if (!kitlabTemplateUsesPuma2627DryCellSharedCollars(item)) return false;
    const sharedSource = PUMA_26_27_DRYCELL_TEMPLATE || null;
    if (!sharedSource || !Array.isArray(sharedSource.collars) || !sharedSource.collars.length) return false;
    item.collars = kitlabCloneCollarList(sharedSource.collars || []);
    item.collarCategories = Array.isArray(sharedSource.collarCategories) ? sharedSource.collarCategories.slice() : [];
    item.sharedCollarSettingsBaseId = "assets/templates/puma/puma%2026-27%20drycell";
    item.initialCollarSettingsBaseId = "assets/templates/puma/puma%2026-27%20drycell";
    item.__kitlabSharedCollarSource = "Puma 26-27 DryCELL";
    return true;
  }

  function kitlabApplyPuma2627DryCellSharedCollars() {
    const targets = [
      PUMA_26_27_V2_DRYCELL_TEMPLATE,
      ...(Array.isArray(INTERNAL_TEMPLATES) ? INTERNAL_TEMPLATES : []),
      ...(Array.isArray(TEMPLATE_STYLE_MANIFESTS) ? TEMPLATE_STYLE_MANIFESTS : []),
    ];
    targets.forEach((item) => kitlabApplyPuma2627DryCellSharedCollarsToTemplate(item));
  }

  kitlabApplyPuma2026SharedCollars();
  kitlabApplyPuma2627DryCellSharedCollars();

