  DEFAULT_INTERNAL_TEAMS = TEAM_COUNTRIES.flatMap((country) => country.teams.map((team) => teamItemFromCountryFile(country.country, team.file, team.name)));
  let INTERNAL_TEAMS = DEFAULT_INTERNAL_TEAMS.slice();
  // v1.3.274: keep an immutable copy of the original Team catalog for Pattern
  // folder thumbnails. The live asset manifest is authoritative for the Team
  // gallery and may replace INTERNAL_TEAMS, but legacy PNGs that are still on
  // the server must remain available as thumbnail fallbacks.
  const PATTERN_TEAM_EMBEDDED_FALLBACKS = DEFAULT_INTERNAL_TEAMS.slice();
  const TEAM_COUNTRY_METADATA_FALLBACK = new Map(TEAM_COUNTRIES.map((country) => [normalizeAssetMatchKey(country.country || country.display || ""), { ...country }]));
