  const TEAM_FLAG_ALIAS_BY_NAME_KEY = {"turkey":["TR","TUR","Turkey","Türkiye","Turkiye","Turquia","Turquía"],"cotedivoyre":["CI","CIV","Cote d Ivoire","Côte d’Ivoire","Ivory Coast","Costa de Marfil"],"england":["GB-ENG","ENG","England","Inglaterra"],"scotland":["GB-SCT","SCO","Scotland","Escocia"],"wales":["GB-WLS","WAL","Wales","Gales"],"northernireland":["GB-NIR","NIR","Northern Ireland","Irlanda del Norte"]};
  const TEAM_FLAG_FILES = [];

  function normalizeAssetMatchKey(value) {
    return decodeHashUnicode(String(value || ""))
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, "");
  }

  function isTeamMonochromaticAsset(...values) {
    return values.some((value) => {
      const key = normalizeAssetMatchKey(value);
      return key.includes("monocromatico") || key.includes("monochromatic");
    });
  }

  function prepareTeamImageColorMode(image, fileName, src) {
    if (!image) return;
    // v1.3.275: Team now follows the same automatic pixel analysis as Brand and Sponsor.
    // Do not trust file names such as "monochromatic": the real PNG decides whether it is
    // Original, 1 Color or 2 Colors. Cache the analysis on the Image because Team is used
    // independently in Shirt and Short.
    delete image.kitlab6NoPalette;
    delete image.kitlab6TeamMonochromatic;
    image.kitlab6LogoColorAnalysis = safeAnalyzeLogoColorMode(image);
  }

  function encodePathParts(partsOrPath = "") {
    const parts = Array.isArray(partsOrPath)
      ? partsOrPath
      : String(partsOrPath || "").split("/");
    return parts
      .filter((part) => part !== undefined && part !== null && String(part).length)
      .map((part) => encodeURIComponent(String(part)))
      .join("/");
  }

  function teamItemFromCountryFile(country, fileName, displayName) {
    const clean = displayName || cleanBrandFileName(decodeHashUnicode(fileName));
    const paletteKey = `${country}|${fileName}`;
    return {
      name: clean,
      file: fileName,
      country,
      palette: (typeof TEAM_PALETTES !== "undefined" && TEAM_PALETTES[paletteKey]) ? TEAM_PALETTES[paletteKey] : [],
      src: kitlabDynamicAssetUrl(encodePathParts(["assets", "team", country, fileName])),
    };
  }

  function teamItemFromFileName(fileName) {
    return teamItemFromCountryFile("", fileName, cleanBrandFileName(decodeHashUnicode(fileName)));
  }

  async function refreshInternalBrandsFromFolder() {
    try {
      // The generated static manifest is authoritative on the public web: additions,
      // renames and deletions all become visible without touching app.js.
      const staticListed = await listKitlabStaticAssetDirectory(["assets", "brand"]);
      const listed = staticListed || await listKitlabAssetDirectory(["assets", "brand"]);
      if (listed && Array.isArray(listed.files)) {
        const files = listed.files.filter((f) => /\.(png|webp|jpg|jpeg|svg)$/i.test(f));
        const unique = [...new Set(files)].sort((a, b) => compareBrandSponsorItems(brandItemFromFileName(a), brandItemFromFileName(b)));
        INTERNAL_BRANDS = unique.map(brandItemFromFileName).sort(compareBrandSponsorItems);
      }
    } catch (error) {
      // Keep embedded fallback list only when the manifest/list cannot be read.
    }
    return [...INTERNAL_BRANDS].sort(compareBrandSponsorItems);
  }

  async function refreshInternalSponsorsFromFolder() {
    try {
      const staticListed = await listKitlabStaticAssetDirectory(["assets", "sponsor"]);
      const listed = staticListed || await listKitlabAssetDirectory(["assets", "sponsor"]);
      if (listed && Array.isArray(listed.files)) {
        const files = listed.files.filter((f) => /\.(png|webp|jpg|jpeg|svg)$/i.test(f));
        const unique = [...new Set(files)].sort((a, b) => compareBrandSponsorItems(sponsorItemFromFileName(a), sponsorItemFromFileName(b)));
        INTERNAL_SPONSORS = unique.map(sponsorItemFromFileName).sort(compareBrandSponsorItems);
      }
    } catch (error) {
      // Keep embedded fallback only when the manifest/list cannot be read.
    }
    return [...INTERNAL_SPONSORS].sort(compareBrandSponsorItems);
  }

  function armbandFileItem(categoryName, fileName) {
    return {
      category: categoryName,
      name: cleanDisplayName(cleanBrandFileName(fileName)),
      file: fileName,
      src: encodePathParts(["assets", "armband", categoryName, fileName]),
    };
  }

  function parseDirectoryFolders(html) {
    const folders = [];
    const hrefRegex = /href=["']([^"']+\/)["']/gi;
    let match;
    while ((match = hrefRegex.exec(String(html || "")))) {
      const folder = decodeURIComponent(String(match[1] || "").replace(/\/$/, "").split("/").pop() || "").trim();
      if (!folder || folder === "." || folder === "..") continue;
      if (/^(?:\?|#)/.test(folder)) continue;
      folders.push(folder);
    }
    return [...new Set(folders)].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base", numeric: true }));
  }

  function parseDirectoryPngFiles(html) {
    const files = [];
    const hrefRegex = /href=["']([^"']+\.png(?:\?[^"']*)?)["']/gi;
    let match;
    while ((match = hrefRegex.exec(String(html || "")))) {
      const cleanHref = String(match[1] || "").split("?")[0];
      const fileName = decodeURIComponent(cleanHref.split("/").pop() || "").trim();
      if (!fileName || fileName.startsWith(".")) continue;
      files.push(fileName);
    }
    return [...new Set(files)].sort((a, b) => compareBrandSponsorItems({ name: cleanBrandFileName(a), file: a }, { name: cleanBrandFileName(b), file: b }));
  }

  function removeArmbandItemsForCategory(categoryName) {
    for (let i = ARMBAND_ITEMS.length - 1; i >= 0; i--) {
      if (String(ARMBAND_ITEMS[i]?.category || "") === String(categoryName || "")) ARMBAND_ITEMS.splice(i, 1);
    }
  }

  async function refreshArmbandRootFoldersFromDisk() {
    try {
      const listed = await listKitlabAssetDirectory(["assets", "armband"]);
      const folders = Array.isArray(listed?.folders) ? listed.folders.filter(Boolean) : [];
      if (!folders.length) return false;
      armbandDiskScanAuthoritative = true;
      ARMBAND_DYNAMIC_CATEGORIES.clear();
      ARMBAND_DISK_CATEGORIES.clear();
      for (const folder of folders) {
        ARMBAND_DYNAMIC_CATEGORIES.add(folder);
        ARMBAND_DISK_CATEGORIES.add(folder);
      }
      // The manifest/list is authoritative: removed category folders must disappear too.
      for (let i = ARMBAND_ITEMS.length - 1; i >= 0; i--) {
        const cat = String(ARMBAND_ITEMS[i]?.category || "");
        if (cat && !ARMBAND_DISK_CATEGORIES.has(cat)) ARMBAND_ITEMS.splice(i, 1);
      }
      return true;
    } catch (error) {
      return false;
    }
  }

  async function refreshArmbandCategoryFolder(categoryName, options = {}) {
    const category = String(categoryName || "").trim();
    if (!category) return false;
    try {
      const listed = await listKitlabAssetDirectory(["assets", "armband", category]);
      const files = Array.isArray(listed?.files) ? listed.files.filter((f) => /\.(png|webp|jpg|jpeg|svg)$/i.test(f)) : [];
      armbandDiskScanAuthoritative = true;
      ARMBAND_DYNAMIC_CATEGORIES.add(category);
      ARMBAND_DISK_CATEGORIES.add(category);
      // The manifest/list is authoritative: deleted files disappear and new files appear after regenerating manifest.
      removeArmbandItemsForCategory(category);
      for (const fileName of files) ARMBAND_ITEMS.push(armbandFileItem(category, fileName));
      return true;
    } catch (error) {
      return false;
    }
  }

  async function refreshArmbandGalleryFromDisk() {
    const rootOk = await refreshArmbandRootFoldersFromDisk();
    if (!rootOk) return false;
    const folders = [...ARMBAND_DISK_CATEGORIES];
    await Promise.all(folders.map((folder) => refreshArmbandCategoryFolder(folder, { authoritative: true }).catch(() => false)));
    resetArmbandCategoryThumbs();
    return true;
  }

  function armbandRootCategories() {
    const cats = new Set();
    if (armbandDiskScanAuthoritative && ARMBAND_DISK_CATEGORIES.size) {
      for (const cat of ARMBAND_DISK_CATEGORIES) if (cat) cats.add(cat);
    } else {
      for (const item of ARMBAND_ITEMS) if (item && item.category) cats.add(item.category);
      for (const cat of ARMBAND_DYNAMIC_CATEGORIES) if (cat) cats.add(cat);
    }
    return [...cats].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base", numeric: true }));
  }

  function resetArmbandCategoryThumbs() {
    state.armbandCategoryThumbs = {};
  }

  function armbandCategoryRandomThumb(categoryName) {
    const cat = String(categoryName || "");
    if (!cat) return "";
    if (!state.armbandCategoryThumbs || typeof state.armbandCategoryThumbs !== "object") state.armbandCategoryThumbs = {};
    if (state.armbandCategoryThumbs[cat]) return state.armbandCategoryThumbs[cat];
    const candidates = ARMBAND_ITEMS
      .filter((item) => String(item?.category || "") === cat && String(item?.src || item?.thumb || item?.path || ""))
      .map((item) => String(item.thumb || item.src || item.path || ""))
      .filter(Boolean);
    if (!candidates.length) return "";
    const chosen = candidates[Math.floor(Math.random() * candidates.length)] || candidates[0];
    state.armbandCategoryThumbs[cat] = chosen;
    return chosen;
  }

  function flagTokens(value) {
    return decodeHashUnicode(String(value || ""))
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, " ")
      .trim()
      .split(/\s+/)
      .filter(Boolean);
  }

  function compactFlagKey(value) {
    const connectorWords = new Set(["and", "the", "of", "de", "del", "la", "el", "las", "los", "da", "do", "di", "du"]);
    return flagTokens(value).filter((token) => !connectorWords.has(token)).join("");
  }

  function flagFileMatchKeys(fileName) {
    const rawBase = decodeHashUnicode(String(fileName || "").replace(/\.(png|webp|jpg|jpeg|svg)$/i, ""));
    const tokens = flagTokens(rawBase).filter((token) => !/^\d+x\d+$/.test(token));
    const assetWords = new Set(["flag", "flags", "bandera", "banderas", "country", "countries", "nation", "national", "icon", "icons", "square", "round", "circle", "flat", "glossy", "small", "large", "big", "png", "svg", "image", "images", "4x3", "1x1"]);
    const keys = new Set();
    const add = (value) => {
      const k = normalizeAssetMatchKey(value);
      if (k) keys.add(k);
      const c = compactFlagKey(value);
      if (c) keys.add(c);
    };
    add(rawBase);
    const cleanedTokens = tokens.filter((token) => !assetWords.has(token));
    if (cleanedTokens.length) add(cleanedTokens.join(" "));
    if (tokens.length === 2) {
      if (assetWords.has(tokens[0])) add(tokens[1]);
      if (assetWords.has(tokens[1])) add(tokens[0]);
    }
    if (tokens.length === 3) {
      if (assetWords.has(tokens[0])) add(tokens.slice(1).join(" "));
      if (assetWords.has(tokens[2])) add(tokens.slice(0, 2).join(" "));
    }
    return [...keys];
  }

  function regionDisplayNamesForCode(code) {
    const normalizedCode = String(code || "").trim().toUpperCase();
    if (!/^[A-Z]{2}$/.test(normalizedCode)) return [];
    const locales = ["en", "es", "fr", "pt", "it", "de"];
    const names = [];
    for (const locale of locales) {
      try {
        const formatter = new Intl.DisplayNames([locale], { type: "region" });
        const name = formatter.of(normalizedCode);
        if (name && !names.includes(name)) names.push(name);
      } catch (error) {
        // Browser may not support Intl.DisplayNames in some environments.
      }
    }
    return names;
  }

  function teamFlagCandidateKeys(country) {
    const values = [];
    const push = (value) => {
      if (value === undefined || value === null) return;
      const text = decodeHashUnicode(String(value)).trim();
      if (!text) return;
      values.push(text);
    };
    const code = String(country?.code || "").trim().toUpperCase();
    push(country?.country);
    push(country?.display);
    push(code);
    if (code.includes("-")) push(code.replace(/-/g, ""));
    for (const alias of (TEAM_FLAG_ALIAS_BY_CODE[code] || [])) push(alias);
    const nameKey = normalizeAssetMatchKey(country?.country || country?.display || "");
    for (const alias of (TEAM_FLAG_ALIAS_BY_NAME_KEY[nameKey] || [])) push(alias);
    for (const intlName of regionDisplayNamesForCode(code)) push(intlName);

    const keys = new Set();
    for (const value of values) {
      const key = normalizeAssetMatchKey(value);
      if (key) keys.add(key);
      const compact = compactFlagKey(value);
      if (compact) keys.add(compact);
    }
    return [...keys];
  }

  function findTeamFlagFileForCountry(country) {
    const candidates = teamFlagCandidateKeys(country);
    for (const key of candidates) {
      const file = TEAM_FLAG_FILE_MAP.get(key);
      if (file) return file;
    }

    // Second pass: permissive match for names like "flag_argentina_4x3.png" or "bandera-españa.png".
    // Two/three-letter codes only match exact extracted keys so they do not hit random words by accident.
    for (const fileName of TEAM_FLAG_FILES) {
      const keys = flagFileMatchKeys(fileName);
      for (const candidate of candidates) {
        if (!candidate) continue;
        const codeLike = candidate.length <= 3;
        for (const key of keys) {
          if (!key) continue;
          if (key === candidate) return fileName;
          if (!codeLike && (key.includes(candidate) || candidate.includes(key))) return fileName;
        }
      }
    }
    return null;
  }

  async function refreshTeamFlagsFromFolder() {
    if (teamFlagsScanned) return;
    if (teamFlagsRefreshPromise) return teamFlagsRefreshPromise;
    teamFlagsRefreshPromise = (async () => {
      try {
        TEAM_FLAG_FILE_MAP.clear();
        TEAM_FLAG_FILES.length = 0;
        const listed = await listKitlabAssetDirectory(["assets", "flags"]);
        const fileNames = Array.isArray(listed?.files) ? listed.files : [];
        for (const fileName of fileNames) {
          if (!fileName || fileName.startsWith(".")) continue;
          if (TEAM_FLAG_FILES.includes(fileName)) continue;
          TEAM_FLAG_FILES.push(fileName);
          for (const key of flagFileMatchKeys(fileName)) {
            if (key && !TEAM_FLAG_FILE_MAP.has(key)) TEAM_FLAG_FILE_MAP.set(key, fileName);
          }
        }
        for (const country of TEAM_COUNTRIES) {
          const file = findTeamFlagFileForCountry(country);
          if (file) country.flagSrc = encodePathParts(["assets", "flags", file]);
        }
      } catch (error) {
        // If static manifest is unavailable, keep emoji flags.
      } finally {
        teamFlagsScanned = true;
      }
    })();
    return teamFlagsRefreshPromise;
  }

  function teamCountryFlagHtml(country) {
    if (country && country.flagSrc) {
      return `<img class="country-flag-img" src="${escapeAttr(country.flagSrc)}" alt="${escapeAttr(country.display || country.country || "Flag")}" loading="lazy">`;
    }
    return `<span class="country-flag">${escapeHtml(country.flag || "🏳️")}</span>`;
  }

  function teamCountryMetadataFromFolder(folderName) {
    const physicalName = String(folderName || "").trim();
    const key = normalizeAssetMatchKey(physicalName);
    const current = TEAM_COUNTRIES.find((item) => normalizeAssetMatchKey(item.country || item.display || "") === key);
    const fallback = TEAM_COUNTRY_METADATA_FALLBACK.get(key);
    const base = current || fallback || {};
    return {
      ...base,
      // country is also the physical directory name and must never be translated.
      country: physicalName,
      display: base.display || cleanDisplayName(decodeHashUnicode(physicalName)),
      flag: base.flag || "🏳️",
      teams: [],
    };
  }

  async function refreshTeamRootFoldersFromManifest() {
    try {
      const staticListed = await listKitlabStaticAssetDirectory(["assets", "team"]);
      const listed = staticListed || await listKitlabAssetDirectory(["assets", "team"]);
      if (!listed || !Array.isArray(listed.folders)) return false;
      const folders = [...new Set(listed.folders.filter((folder) => String(folder || "").trim() && !String(folder).startsWith(".")))]
        .sort((a, b) => cleanDisplayName(decodeHashUnicode(a)).localeCompare(cleanDisplayName(decodeHashUnicode(b)), undefined, { sensitivity: "base", numeric: true }));
      const nextCountries = folders.map(teamCountryMetadataFromFolder);
      TEAM_COUNTRIES.splice(0, TEAM_COUNTRIES.length, ...nextCountries);
      const allowed = new Set(folders);
      INTERNAL_TEAMS = INTERNAL_TEAMS.filter((item) => allowed.has(item.country));
      teamRootManifestAuthoritative = true;
      // New country folders may also have a flag file. Re-evaluate flag matching.
      teamFlagsScanned = false;
      teamFlagsRefreshPromise = null;
      return true;
    } catch (_) {
      return false;
    }
  }

  async function refreshInternalTeamsFromFolder() {
    // v1.3.262: the folder manifest is authoritative for both countries and PNGs.
    // This makes new/renamed/deleted team files visible without editing TEAM_COUNTRIES.
    const rootOk = await refreshTeamRootFoldersFromManifest();
    await refreshTeamFlagsFromFolder();
    if (rootOk) {
      await Promise.all(TEAM_COUNTRIES.map((country) => refreshTeamCountryFolder(country.country).catch(() => false)));
    } else if (state.teamGalleryCountry) {
      await refreshTeamCountryFolder(state.teamGalleryCountry);
    }
    return INTERNAL_TEAMS;
  }

  async function refreshTeamCountryFolder(countryName) {
    if (!countryName) return false;

    const applyFiles = (files, authoritative = false) => {
      const unique = [...new Set((Array.isArray(files) ? files : [])
        .filter((fileName) => /\.(png|webp|jpg|jpeg|svg)$/i.test(String(fileName || "")))
        .filter((fileName) => !String(fileName || "").startsWith(".")))]
        .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base", numeric: true }));
      if (!authoritative && !unique.length) return false;
      const country = TEAM_COUNTRIES.find((item) => item.country === countryName) || teamCountryMetadataFromFolder(countryName);
      const nextItems = unique.map((fileName) => teamItemFromCountryFile(country.country, fileName));
      INTERNAL_TEAMS = INTERNAL_TEAMS.filter((item) => item.country !== countryName).concat(nextItems);
      return true;
    };

    // Cloudflare does not expose directory listings. The generated manifest is the
    // source of truth and an empty folder must also remove stale embedded entries.
    try {
      const staticListed = await listKitlabStaticAssetDirectory(["assets", "team", countryName]);
      if (staticListed) return applyFiles(staticListed.files, true);
    } catch (_) {}

    try {
      const listed = await listKitlabAssetDirectory(["assets", "team", countryName]);
      if (listed && applyFiles(listed.files, false)) return true;
    } catch (_) {}

    try {
      const response = await fetch(kitlabNoCacheUrl(encodePathParts(["assets", "team", countryName]) + "/"), { cache: "no-store" });
      if (!response.ok) return false;
      const html = await response.text();
      const files = [];
      const hrefRegex = /href=["']([^"']+\.(?:png|webp|jpg|jpeg|svg))["']/gi;
      let match;
      while ((match = hrefRegex.exec(html))) {
        const fileName = decodeURIComponent(match[1].split("/").pop());
        if (!fileName || fileName.startsWith(".")) continue;
        files.push(fileName);
      }
      return applyFiles(files, false);
    } catch (error) {
      // file:// cannot list the folder. Keep the embedded fallback.
      return false;
    }
  }

  function assetTypeForPart(part) {
    return BRAND_PARTS[part]?.assetType || "brand";
  }


  // v1.3.244 — Template Gallery no-flicker high-quality thumbnails.
  // Users need template seams/details to be sharp, but the progressive WebP -> PNG
  // swap from v1.3.243 caused visible blinking. This version avoids visible swapping:
  // template cards render with their final original PNG thumbnail from the start,
  // while keeping lazy/async image loading and WebP only as a fallback.
  window.__KITLAB_TEMPLATE_GALLERY_THUMB_QUALITY_V244__ = true;

  function kitlabTemplateGalleryOriginalThumbSrc(src) {
    const raw = String(src || "").trim();
    if (!raw || raw.startsWith("data:")) return raw;
    const convertPath = (path) => String(path || "")
      .replace(/\/assets\/thumbs\/templates\//i, "/assets/templates/")
      .replace(/(^|\/)assets\/thumbs\/templates\//i, "$1assets/templates/")
      .replace(/\.webp$/i, ".png");
    try {
      const url = new URL(raw, window.location.href);
      const oldPath = url.pathname;
      url.pathname = convertPath(url.pathname);
      if (url.pathname === oldPath) return raw;
      if (url.origin === window.location.origin) {
        return url.pathname.replace(/^\/+/, "") + url.search + url.hash;
      }
      return url.toString();
    } catch (_) {
      const parts = raw.split(/([?#].*)/);
      const path = parts[0] || "";
      const suffix = parts.slice(1).join("");
      const converted = convertPath(path);
      return converted === path ? raw : converted + suffix;
    }
  }

  function kitlabTemplateGalleryFastThumbSrc(src) {
    const raw = String(src || "").trim();
    if (!raw || /^(data:|blob:|file:)/i.test(raw)) return raw;
    const hashIndex = raw.indexOf("#");
    const hash = hashIndex >= 0 ? raw.slice(hashIndex) : "";
    const noHash = hashIndex >= 0 ? raw.slice(0, hashIndex) : raw;
    const queryIndex = noHash.indexOf("?");
    const base = queryIndex >= 0 ? noHash.slice(0, queryIndex) : noHash;
    const query = queryIndex >= 0 ? noHash.slice(queryIndex) : "";
    const normalized = base.replace(/^\.?\//, "");
    if (!/^assets\/templates\//i.test(normalized)) return raw;
    const thumbBase = normalized
      .replace(/^assets\/templates\//i, "assets/thumbs/templates/")
      .replace(/\.(png|jpg|jpeg|webp)$/i, ".webp");
    return thumbBase + query + hash;
  }

  function templatePerformanceThumbSrc(src) {
    const raw = String(src || "").trim();
    // v1.3.244: return the final HQ thumbnail directly. Do not show WebP first
    // and swap later, because that creates visible flicker in Template Gallery.
    return kitlabTemplateGalleryOriginalThumbSrc(raw) || raw;
  }

  function templatePerformanceFallbacks(primary, original, fallbacks = []) {
    const out = [];
    const seen = new Set();
    [
      primary,
      kitlabTemplateGalleryOriginalThumbSrc(original),
      kitlabTemplateGalleryOriginalThumbSrc(primary),
      original,
      kitlabTemplateGalleryFastThumbSrc(original),
      kitlabTemplateGalleryFastThumbSrc(primary),
      ...(Array.isArray(fallbacks) ? fallbacks : []),
    ].forEach((value) => {
      const clean = String(value || "").trim();
      if (!clean || seen.has(clean)) return;
      seen.add(clean);
      out.push(clean);
    });
    const current = String(primary || "").trim();
    return out.filter((value) => value !== current);
  }

  const kitlabTemplateThumbHqQueue = [];
  const kitlabTemplateThumbHqQueued = new WeakSet();
  let kitlabTemplateThumbHqActive = 0;
  const KITLAB_TEMPLATE_THUMB_HQ_CONCURRENCY = 2;

  function kitlabPumpTemplateThumbHqQueue() {
    while (kitlabTemplateThumbHqActive < KITLAB_TEMPLATE_THUMB_HQ_CONCURRENCY && kitlabTemplateThumbHqQueue.length) {
      const img = kitlabTemplateThumbHqQueue.shift();
      if (!img || !img.isConnected) continue;
      const hq = img.dataset.kitlabHqTemplateThumb || "";
      const current = img.getAttribute("src") || img.currentSrc || "";
      if (!hq || current === hq || img.dataset.kitlabHqTemplateThumbDone === "1") continue;
      kitlabTemplateThumbHqActive += 1;
      const probe = new Image();
      probe.decoding = "async";
      probe.onload = () => {
        kitlabTemplateThumbHqActive = Math.max(0, kitlabTemplateThumbHqActive - 1);
        if (img.isConnected && img.dataset.kitlabHqTemplateThumb === hq) {
          img.removeAttribute("srcset");
          img.setAttribute("src", hq);
          img.dataset.kitlabHqTemplateThumbDone = "1";
          img.classList.add("kitlab-template-thumb-hq-ready");
        }
        kitlabPumpTemplateThumbHqQueue();
      };
      probe.onerror = () => {
        kitlabTemplateThumbHqActive = Math.max(0, kitlabTemplateThumbHqActive - 1);
        if (img.isConnected) img.dataset.kitlabHqTemplateThumbDone = "error";
        kitlabPumpTemplateThumbHqQueue();
      };
      probe.src = hq;
    }
  }

  function kitlabQueueTemplateThumbHq(img) {
    if (!img || kitlabTemplateThumbHqQueued.has(img)) return;
    const hq = img.dataset.kitlabHqTemplateThumb || "";
    const current = img.getAttribute("src") || img.currentSrc || "";
    if (!hq || current === hq || img.dataset.kitlabHqTemplateThumbDone) return;
    kitlabTemplateThumbHqQueued.add(img);
    kitlabTemplateThumbHqQueue.push(img);
    const run = () => kitlabPumpTemplateThumbHqQueue();
    if ("requestIdleCallback" in window) window.requestIdleCallback(run, { timeout: 450 });
    else setTimeout(run, 80);
  }

  const kitlabTemplateThumbHqObserver = (() => {
    if (!("IntersectionObserver" in window)) return null;
    return new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        kitlabTemplateThumbHqObserver.unobserve(entry.target);
        kitlabQueueTemplateThumbHq(entry.target);
      });
    }, { root: null, rootMargin: "260px 0px", threshold: 0.01 });
  })();

  function kitlabPrepareTemplateGalleryProgressiveThumb(img) {
    // v1.3.244: intentionally disabled. Any visible WebP -> PNG replacement
    // creates flicker. Cards now receive the final HQ source during render.
    return;
  }

  function kitlabUpgradeTemplateGalleryThumbDom(root = document) {
    // v1.3.244: no DOM source swapping. Keeping this as a no-op preserves
    // compatibility with any older calls without touching visible thumbnails.
    return;
  }

  if (!window.__KITLAB_TEMPLATE_GALLERY_THUMB_QUALITY_NO_FLICKER_V244__) {
    window.__KITLAB_TEMPLATE_GALLERY_THUMB_QUALITY_NO_FLICKER_V244__ = true;
  }

  const TEMPLATE_FOLDER_FALLBACK_THUMB = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 128 96'%3E%3Cpath fill='white' d='M10 20h37l10 12h61v44c0 7-5 12-12 12H22c-7 0-12-5-12-12V20z'/%3E%3Cpath fill='white' opacity='.72' d='M10 28V18c0-6 4-10 10-10h30l10 12h48c6 0 10 4 10 10v8H10z'/%3E%3C/svg%3E";

  function templateBrandSortKey(name) {
    const normalized = String(name || "").trim().toLowerCase();
    return normalized === "basic" ? "000_basic" : `100_${normalized}`;
  }

  const TEMPLATE_BRAND_THUMB_OVERRIDES = {
    hummel: ["hummel03", "hummel 03", "hummel_03", "hummel-03"],
    macron: ["macron03", "macron 03", "macron_03", "macron-03"],
    umbro: ["umbro02", "umbro 02", "umbro_02", "umbro-02"],
  };

  function templateBrandThumbToken(value) {
    return String(value || "")
      .toLowerCase()
      .replace(/\.png$/i, "")
      .replace(/[^a-z0-9]+/g, "");
  }

  function findInternalBrandByTemplateAliases(aliases = []) {
    const tokens = new Set((aliases || []).map(templateBrandThumbToken).filter(Boolean));
    if (!tokens.size) return null;
    return (INTERNAL_BRANDS || []).find((item) => {
      const itemNameToken = templateBrandThumbToken(item?.name || "");
      const itemFileToken = templateBrandThumbToken(cleanBrandFileName(item?.file || ""));
      return tokens.has(itemNameToken) || tokens.has(itemFileToken);
    }) || null;
  }

  function findTemplateBrandThumbnail(brand) {
    const raw = String(brand || "").trim();
    const normalized = raw.toLowerCase();
    const display = cleanDisplayName(raw).toLowerCase();
    // v1.1.46: Basic is always the first template folder and uses its own brand PNG.
    // Keep a fallback for old packs where the file was exported as Basic.png.
    if (normalized === "basic" || display === "basic") {
      return "assets/brand/Basic.png";
    }
    const candidates = INTERNAL_BRANDS || [];
    // v1.3.48: Template brand folder icons can use a specific logo variant
    // without changing the default Brand gallery or kit placement assets.
    const override = TEMPLATE_BRAND_THUMB_OVERRIDES[templateBrandThumbToken(normalized)] || TEMPLATE_BRAND_THUMB_OVERRIDES[templateBrandThumbToken(display)];
    const overrideBrand = findInternalBrandByTemplateAliases(override);
    if (overrideBrand?.src) return overrideBrand.src;
    const exact = candidates.find((item) => {
      const itemName = String(item?.name || "").trim().toLowerCase();
      const itemFile = cleanBrandFileName(item?.file || "").trim().toLowerCase();
      return itemName === normalized || itemFile === normalized || itemName === display || itemFile === display;
    });
    return exact?.src || TEMPLATE_FOLDER_FALLBACK_THUMB;
  }

  function templateBrandFolders() {
    const byBrand = new Map();
    for (const item of INTERNAL_TEMPLATES) {
      const brand = String(item.brand || "templates").toLowerCase();
      if (!byBrand.has(brand)) {
        const isBasic = brand === "basic";
        byBrand.set(brand, {
          isTemplateBrand: true,
          brand,
          name: cleanDisplayName(brand),
          thumb: findTemplateBrandThumbnail(brand),
          thumbFallbacks: isBasic ? ["assets/brand/Basic.png", "assets/brand/basic.PNG"] : [],
        });
      }
    }
    return [...byBrand.values()].sort((a, b) => {
      const ak = templateBrandSortKey(a.name);
      const bk = templateBrandSortKey(b.name);
      return ak.localeCompare(bk, undefined, { sensitivity: "base" });
    });
  }


  // v1.1.77 — Template gallery entry screen: Players / Goalkeepers.
  // It is visual/navigation-only for now. Existing complete templates still load as before
  // after choosing one of the two entry modes.
  const TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS = {
    players: ["assets/template_gallery/players/Haaland.png"],
    goalkeepers: ["assets/template_gallery/goalkeepers/Oblak.png"],
  };

  // v1.1.80 — Real user-editable preview folders for the Template entry screen.
  // Drop any PNG/WebP/JPG in these folders and the next Template opening can use it at random.
  const TEMPLATE_GALLERY_MODE_PREVIEW_FOLDERS = {
    players: [
      ["assets", "template_gallery", "players"],
      ["assets", "modular_preview", "players"], // backwards compatibility with the first visual test folder
    ],
    goalkeepers: [
      ["assets", "template_gallery", "goalkeepers"],
      ["assets", "template_gallery", "goalkeppers"], // tolerated typo, official folder is goalkeepers
      ["assets", "modular_preview", "goalkeepers"],
      ["assets", "modular_preview", "goalkeppers"],
    ],
  };

  function normalizeTemplateGalleryMode(mode) {
    return mode === "goalkeepers" ? "goalkeepers" : mode === "players" ? "players" : null;
  }

  function templateGalleryModeLabel(mode) {
    return normalizeTemplateGalleryMode(mode) === "goalkeepers" ? "Goalkeepers" : "Players";
  }

  function templateGalleryRandomFromList(list, fallback = "") {
    const arr = Array.isArray(list) ? list.filter(Boolean) : [];
    if (!arr.length) return fallback || "";
    return arr[Math.floor(Math.random() * arr.length)] || fallback || "";
  }

  function templateGalleryHasGoalkeeperMark(item) {
    const value = String(`${item?.name || ""} ${item?.id || ""} ${item?.folder || ""} ${item?.path || ""} ${item?.brand || ""}`)
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, " ")
      .replace(/[_\-.]+/g, " ");
    return /(^|[\s\/])gk([\s\/]|$)/i.test(value) || value.includes("goalkeeper") || value.includes("goalkeepers");
  }

  function templateGalleryMatchesMode(item, mode = state.templateGalleryMode) {
    const normalized = normalizeTemplateGalleryMode(mode);
    if (!normalized) return true;
    // v1.2.09: allow modular part-only templates (for example Macron Basic V1 short/socks)
    // to be explicitly shared between Players and Goalkeepers instead of relying only on
    // name/path GK detection.
    const explicitModes = Array.isArray(item?.templateGalleryModes)
      ? item.templateGalleryModes.map(normalizeTemplateGalleryMode).filter(Boolean)
      : [];
    if (explicitModes.length) return explicitModes.includes(normalized);
    const isGk = templateGalleryHasGoalkeeperMark(item);
    return normalized === "goalkeepers" ? isGk : !isGk;
  }

  function activeTemplateIsGoalkeeperContext() {
    const item = state.templateStyle?.selected || null;
    if (!item) return false;
    const explicitModes = Array.isArray(item?.templateGalleryModes)
      ? item.templateGalleryModes.map(normalizeTemplateGalleryMode).filter(Boolean)
      : [];
    const currentMode = normalizeTemplateGalleryMode(state.templateGalleryMode);
    if (currentMode === "goalkeepers" && (!explicitModes.length || explicitModes.includes("goalkeepers"))) return true;
    if (explicitModes.length === 1 && explicitModes[0] === "goalkeepers") return true;
    return templateGalleryHasGoalkeeperMark(item) && !explicitModes.includes("players");
  }

  function templateBrandFoldersForMode(mode = state.templateGalleryMode) {
    const normalized = normalizeTemplateGalleryMode(mode);
    const byBrand = new Map();
    for (const item of INTERNAL_TEMPLATES) {
      if (normalized && !templateGalleryMatchesMode(item, normalized)) continue;
      const brand = String(item.brand || "templates").toLowerCase();
      if (!byBrand.has(brand)) {
        const isBasic = brand === "basic";
        byBrand.set(brand, {
          isTemplateBrand: true,
          brand,
          name: cleanDisplayName(brand),
          thumb: findTemplateBrandThumbnail(brand),
          thumbFallbacks: isBasic ? ["assets/brand/Basic.png", "assets/brand/basic.PNG"] : [],
        });
      }
    }
    return [...byBrand.values()].sort((a, b) => {
      const ak = templateBrandSortKey(a.name);
      const bk = templateBrandSortKey(b.name);
      return ak.localeCompare(bk, undefined, { sensitivity: "base" });
    });
  }

  async function refreshTemplateGalleryModePreviewFolder(mode) {
    const key = normalizeTemplateGalleryMode(mode) || "players";
    const fallback = TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS[key] || [];
    const folders = TEMPLATE_GALLERY_MODE_PREVIEW_FOLDERS[key] || TEMPLATE_GALLERY_MODE_PREVIEW_FOLDERS.players;
    const found = [];
    for (const folderParts of folders) {
      try {
        const folderPath = encodePathParts(folderParts);
        const response = await fetch(`${folderPath}/`, { cache: "no-store" });
        if (!response.ok) continue;
        const html = await response.text();
        const hrefRegex = /href=["']([^"']+\.(?:png|webp|jpg|jpeg))["']/gi;
        let match;
        while ((match = hrefRegex.exec(html))) {
          const fileName = decodeURIComponent(String(match[1] || "").split("/").pop() || "");
          if (!fileName || fileName.startsWith(".")) continue;
          found.push(encodePathParts([...folderParts, fileName]));
        }
      } catch (_) {
        // file:// cannot list folders. The embedded fallback images remain active.
      }
    }
    const unique = [...new Set([...fallback, ...found])];
    if (!state.templateGalleryPreviewImages) state.templateGalleryPreviewImages = { players: [], goalkeepers: [] };
    state.templateGalleryPreviewImages[key] = unique;
    return unique;
  }

  async function refreshTemplateGalleryModePreviewImages() {
    const [players, goalkeepers] = await Promise.all([
      refreshTemplateGalleryModePreviewFolder("players"),
      refreshTemplateGalleryModePreviewFolder("goalkeepers"),
    ]);
    if (!state.templateGalleryRandomPreview) state.templateGalleryRandomPreview = { players: "", goalkeepers: "" };
    state.templateGalleryRandomPreview.players = templateGalleryRandomFromList(players, TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.players[0]);
    state.templateGalleryRandomPreview.goalkeepers = templateGalleryRandomFromList(goalkeepers, TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.goalkeepers[0]);
  }

  function preloadImageQuiet(src) {
    return new Promise((resolve) => {
      const value = String(src || "").trim();
      if (!value) { resolve(false); return; }
      const img = new Image();
      img.onload = async () => {
        try { if (img.decode) await img.decode(); } catch (_) {}
        resolve(true);
      };
      img.onerror = () => resolve(false);
      // Do not cache-bust the Template entry portraits: they must be browser-cached
      // so the Players/Goalkeepers screen opens instantly without late pop-in/flicker.
      img.src = value;
    });
  }

  async function warmTemplateGalleryModePreviewImages() {
    try {
      await refreshTemplateGalleryModePreviewImages();
      const random = state.templateGalleryRandomPreview || {};
      await Promise.all([
        preloadImageQuiet(random.players || TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.players[0]),
        preloadImageQuiet(random.goalkeepers || TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.goalkeepers[0]),
      ]);
      state.templateGalleryPreviewWarm = true;
    } catch (_) {
      state.templateGalleryPreviewWarm = false;
    }
  }

  function scheduleTemplateGalleryPreviewWarmup() {
    const run = () => { warmTemplateGalleryModePreviewImages().catch(() => {}); };
    if (window.requestIdleCallback) window.requestIdleCallback(run, { timeout: 1200 });
    else window.setTimeout(run, 250);
  }

  function resetTemplateGalleryModeEntry() {
    state.templateGalleryMode = null;
    state.templateGalleryBrand = null;
    state.templateGalleryModularBrand = null;
    state.templateGalleryModularActivePart = "shirt";
    state.templateGalleryModularSelections = { shirt: null, short: null, socks: null };
    const existingImages = state.templateGalleryPreviewImages || {};
    const players = Array.isArray(existingImages.players) && existingImages.players.length
      ? existingImages.players
      : TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.players.slice();
    const goalkeepers = Array.isArray(existingImages.goalkeepers) && existingImages.goalkeepers.length
      ? existingImages.goalkeepers
      : TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.goalkeepers.slice();
    state.templateGalleryPreviewImages = { players, goalkeepers };
    const existingRandom = state.templateGalleryRandomPreview || {};
    state.templateGalleryRandomPreview = {
      players: existingRandom.players || templateGalleryRandomFromList(players, TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.players[0]),
      goalkeepers: existingRandom.goalkeepers || templateGalleryRandomFromList(goalkeepers, TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.goalkeepers[0]),
    };
  }

  function renderTemplateGalleryModeEntry() {
    if (!els.internalBrandGrid) return;
    if (els.brandGalleryModal) {
      els.brandGalleryModal.dataset.templateModeEntry = "1";
    }
    const random = state.templateGalleryRandomPreview || {};
    const playersImg = random.players || TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.players[0];
    const keepersImg = random.goalkeepers || TEMPLATE_GALLERY_MODE_PREVIEW_FALLBACKS.goalkeepers[0];
    els.internalBrandGrid.innerHTML = `
      <div class="kitlab-template-mode-choice-wrap">
        <button type="button" class="kitlab-template-mode-choice-card" data-template-gallery-mode="players" aria-label="Players">
          <img src="${escapeAttr(playersImg)}" alt="Players" loading="eager" decoding="async" draggable="false">
          <span>Players</span>
        </button>
        <button type="button" class="kitlab-template-mode-choice-card" data-template-gallery-mode="goalkeepers" aria-label="Goalkeepers">
          <img src="${escapeAttr(keepersImg)}" alt="Goalkeepers" loading="eager" decoding="async" draggable="false">
          <span>Goalkeepers</span>
        </button>
      </div>`;
    installTemplateGalleryFinalSmoothHoverStyles();
  }

