  function applyTemplateModeChoiceHoverRuntimeStyles() {
    const root = els.internalBrandGrid || document;
    root.querySelectorAll('.kitlab-template-mode-choice-card').forEach((card) => {
      const img = card.querySelector('img');
      if (!img) return;
      card.style.setProperty('background', 'transparent', 'important');
      card.style.setProperty('background-color', 'transparent', 'important');
      card.style.setProperty('border-color', 'transparent', 'important');
      card.style.setProperty('box-shadow', 'none', 'important');
      card.style.setProperty('outline', 'none', 'important');
      img.style.setProperty('transition', 'transform 420ms cubic-bezier(.16,1,.3,1)', 'important');
      img.style.setProperty('transform-origin', 'center bottom', 'important');
      img.style.setProperty('will-change', 'transform', 'important');
      img.style.setProperty('filter', 'none', 'important');
      img.style.setProperty('transform', 'translate3d(0,0,0) scale(1)', 'important');
      if (card.dataset.kitlabModeChoiceHoverBound === '1') return;
      card.dataset.kitlabModeChoiceHoverBound = '1';
      const enter = () => {
        img.style.setProperty('transition', 'transform 420ms cubic-bezier(.16,1,.3,1)', 'important');
        img.style.setProperty('transform', 'translate3d(0,0,0) scale(1.045)', 'important');
      };
      const leave = () => {
        img.style.setProperty('transition', 'transform 420ms cubic-bezier(.16,1,.3,1)', 'important');
        img.style.setProperty('transform', 'translate3d(0,0,0) scale(1)', 'important');
      };
      card.addEventListener('pointerenter', enter, { passive: true });
      card.addEventListener('pointerleave', leave, { passive: true });
      card.addEventListener('focus', enter, { passive: true });
      card.addEventListener('blur', leave, { passive: true });
    });
  }


