  function pickerDomCurrentHex(kind, key) {
    try {
      const pop = document.querySelector(`.psh-popover[data-picker-kind="${CSS.escape(kind)}"][data-picker-key="${CSS.escape(key)}"]`);
      const hexInput = pop?.querySelector(".psh-hex");
      const raw = String(hexInput?.value || pop?.querySelector(".psh-hex-live")?.textContent || "").trim();
      const clean = raw.replace(/[^0-9a-fA-F]/g, "").slice(0, 6);
      if (/^[0-9a-fA-F]{6}$/.test(clean)) return normalizeHexColor(`#${clean}`);
    } catch (_) {}
    return "";
  }

  function syncPickerHueDomInPopover(pop, rawColor) {
    if (!pop) return;
    const color = normalizeHexColor(rawColor || "#151515");
    const [r, g, b] = hexToRgbLocal(color);
    const hsv = rgbToHsv(r, g, b);
    const hue = Math.round(hsv.h);
    const hueInput = pop.querySelector("[data-psh-hue-kind][data-psh-hue-key]");
    if (hueInput) {
      hueInput.value = String(hue);
      hueInput.title = `Hue ${hue}°`;
      hueInput.setAttribute("aria-valuetext", `Hue ${hue} degrees`);
    }
    const hexInput = pop.querySelector(".psh-hex");
    if (hexInput && document.activeElement !== hexInput) hexInput.value = color.replace("#", "").toUpperCase();
    const sv = pop.querySelector("[data-psh-sv-kind][data-psh-sv-key]");
    if (sv) sv.dataset.pshCurrentHex = color;
  }

  function normalizePickerHexInput(rawValue = "") {
    const clean = String(rawValue || "").replace(/[^0-9a-fA-F]/g, "").slice(0, 6).toUpperCase();
    if (clean.length !== 6) return "";
    return normalizeHexColor(`#${clean}`);
  }

  function sanitizePickerHexInputElement(input) {
    if (!input) return "";
    const clean = String(input.value || "").replace(/[^0-9a-fA-F]/g, "").slice(0, 6).toUpperCase();
    if (input.value !== clean) input.value = clean;
    return clean.length === 6 ? normalizeHexColor(`#${clean}`) : "";
  }

  function drawPieceColorPickerCanvases() {
    const canvases = document.querySelectorAll("[data-psh-sv-kind][data-psh-sv-key]");
    canvases.forEach((pickerCanvas) => {
      const kind = pickerCanvas.dataset.pshSvKind;
      const key = pickerCanvas.dataset.pshSvKey;
      const ctx2 = pickerCanvas.getContext("2d");
      const rect = pickerCanvas.getBoundingClientRect ? pickerCanvas.getBoundingClientRect() : null;
      const cssW = Math.max(1, Math.round(rect?.width || pickerCanvas.clientWidth || pickerCanvas.width || 360));
      const cssH = Math.max(1, Math.round(rect?.height || pickerCanvas.clientHeight || pickerCanvas.height || 210));
      const dpr = Math.max(1, Math.min(3, window.devicePixelRatio || 1));
      const pxW = Math.max(1, Math.round(cssW * dpr));
      const pxH = Math.max(1, Math.round(cssH * dpr));
      if (pickerCanvas.width !== pxW || pickerCanvas.height !== pxH) {
        pickerCanvas.width = pxW;
        pickerCanvas.height = pxH;
      }
      ctx2.setTransform(dpr, 0, 0, dpr, 0, 0);
      const target = pickerDomCurrentHex(kind, key) || pickerCanvas.dataset.pshCurrentHex || pickerCurrentHex(kind, key);
      const [r, g, b] = hexToRgbLocal(target);
      const hsv = rgbToHsv(r, g, b);
      const pure = hsvToRgb(hsv.h, 1, 1);
      ctx2.clearRect(0, 0, cssW, cssH);
      const gradX = ctx2.createLinearGradient(0, 0, cssW, 0);
      gradX.addColorStop(0, "#ffffff");
      gradX.addColorStop(1, rgbToHex(pure[0], pure[1], pure[2]));
      ctx2.fillStyle = gradX;
      ctx2.fillRect(0, 0, cssW, cssH);
      const gradY = ctx2.createLinearGradient(0, 0, 0, cssH);
      gradY.addColorStop(0, "rgba(0,0,0,0)");
      gradY.addColorStop(1, "#000000");
      ctx2.fillStyle = gradY;
      ctx2.fillRect(0, 0, cssW, cssH);
      const x = hsv.s * cssW;
      const y = (1 - hsv.v) * cssH;
      const radius = clamp(Math.round(Math.min(cssW, cssH) * 0.038), 7, 13);
      const outerLine = clamp(Math.round(radius * 0.24), 2, 4);
      ctx2.save();
      ctx2.beginPath();
      ctx2.arc(x, y, radius, 0, Math.PI * 2);
      ctx2.lineWidth = outerLine;
      ctx2.strokeStyle = "#ffffff";
      ctx2.stroke();
      ctx2.lineWidth = 1.25;
      ctx2.strokeStyle = "rgba(0,0,0,0.92)";
      ctx2.stroke();
      ctx2.restore();
    });
  }

  function updatePickerColorFromSvCanvas(kind, key, event, pickerCanvas = null) {
    pickerCanvas = pickerCanvas || event.currentTarget;
    if (!pickerCanvas || !pickerCanvas.getBoundingClientRect) return;
    const rect = pickerCanvas.getBoundingClientRect();
    const x = clamp((event.clientX - rect.left) / rect.width, 0, 1);
    const y = clamp((event.clientY - rect.top) / rect.height, 0, 1);
    const current = pickerDomCurrentHex(kind, key) || pickerCurrentHex(kind, key);
    const [r, g, b] = hexToRgbLocal(current);
    const hsv = rgbToHsv(r, g, b);
    const rgb = hsvToRgb(hsv.h, x, 1 - y);
    applyPickerColor(kind, key, rgbToHex(rgb[0], rgb[1], rgb[2]));
  }


  function updatePieceColorHue(pieceId, hue) {
    if (!state.pieceColors[pieceId]) return;
    const current = normalizeHexColor(state.pieceColors[pieceId].target || state.pieceColors[pieceId].source || "#151515");
    const [r, g, b] = hexToRgbLocal(current);
    const hsv = rgbToHsv(r, g, b);
    const rgb = hsvToRgb(Number(hue), hsv.s, hsv.v);
    applyPieceColor(pieceId, rgbToHex(rgb[0], rgb[1], rgb[2]));
  }

  function updatePieceColorRgb(pieceId) {
    if (!state.pieceColors[pieceId]) return;
    const r = document.querySelector(`[data-psh-rgb="${CSS.escape(pieceId)}:r"]`);
    const g = document.querySelector(`[data-psh-rgb="${CSS.escape(pieceId)}:g"]`);
    const b = document.querySelector(`[data-psh-rgb="${CSS.escape(pieceId)}:b"]`);
    if (!r || !g || !b) return;
    applyPieceColor(pieceId, rgbToHex(r.value, g.value, b.value));
  }


  const DEFAULT_COLOR_PRESETS = [
    "#151515", "#f1f1f1", "#666666", "#a9834f", "#533b2e", "#83101b", "#e8641b", "#efb900", "#b7dd31", "#125b33", "#23347c", "#2386ec", "#421d51", "#d54471"
  ];

  function loadColorPresets() {
    const presets = [...DEFAULT_COLOR_PRESETS];
    try {
      const stored = JSON.parse(localStorage.getItem("kitlab6_color_presets_final14_v1") || "null");
      if (Array.isArray(stored)) {
        stored.forEach((color, index) => {
          if (index < presets.length) presets[index] = normalizeHexColor(color || presets[index]);
        });
      }
    } catch {}
    return presets;
  }

  function saveColorPresets(presets) {
    try { localStorage.setItem("kitlab6_color_presets_final14_v1", JSON.stringify((Array.isArray(presets) ? presets : []).slice(0, DEFAULT_COLOR_PRESETS.length))); } catch {}
  }

  function setColorPreset(index, color) {
    const presets = loadColorPresets();
    const safeIndex = clamp(Number(index) || 0, 0, presets.length - 1);
    presets[safeIndex] = normalizeHexColor(color);
    saveColorPresets(presets);
  }


  function pickerSessionId(kind, key) {
    return `${kind}|${key}`;
  }

  function activePickerRef() {
    if (state.activeColorPicker) return { kind: "piece", key: state.activeColorPicker };
    const raw = state.logoColorPicker || "";
    if (!raw) return null;
    if (raw.startsWith("template|")) return { kind: "template", key: raw.slice("template|".length) };
    if (raw.startsWith("border|")) return { kind: "border", key: raw.slice("border|".length) };
    return { kind: "logo", key: raw };
  }

  function refreshPickerUi(kind) {
    if (kind === "piece") { renderPieceColorPanels(); renderTemplateDetailPanels(); }
    else if (kind === "template") renderTemplateDetailPanels();
    else updateAllBrandUI();
  }

  function setActivePicker(kind, key) {
    state.activeColorPicker = null;
    state.logoColorPicker = null;
    if (kind === "piece") state.activeColorPicker = key;
    else if (kind === "template") state.logoColorPicker = `template|${key}`;
    else if (kind === "border") state.logoColorPicker = `border|${key}`;
    else state.logoColorPicker = key;
  }

  function rememberPickerOriginal(kind, key) {
    const id = pickerSessionId(kind, key);
    if (!state.pickerOriginals) state.pickerOriginals = {};
    if (!state.pickerOriginals[id]) state.pickerOriginals[id] = pickerCurrentHex(kind, key);
  }

  function openPickerSession(kind, key) {
    const current = activePickerRef();
    if (current && (current.kind !== kind || current.key !== key)) closePickerSession(false);
    rememberPickerOriginal(kind, key);
    setActivePicker(kind, key);
    refreshPickerUi(kind);
  }

  window.kitlabOpenTemplatePicker = function(event, key) {
    try {
      event.preventDefault();
      event.stopPropagation();
      openPickerSession("template", key);
    } catch (error) {
      console.error(error);
      setStatus(`Palette error: ${error?.message || error}`);
    }
  };

  function closePickerSession(applyChanges = true) {
    const current = activePickerRef();
    if (!current) return;
    const id = pickerSessionId(current.kind, current.key);
    const original = state.pickerOriginals?.[id];
    if (!applyChanges && original) applyPickerColor(current.kind, current.key, original);
    if (state.pickerOriginals) delete state.pickerOriginals[id];
    const refreshKind = current.kind;
    state.activeColorPicker = null;
    state.logoColorPicker = null;
    refreshPickerUi(refreshKind);
  }

  function colorPickerPresetRows(target) {
    const presets = loadColorPresets();
    const perRow = 14;
    const rows = [];
    for (let i = 0; i < presets.length; i += perRow) rows.push(presets.slice(i, i + perRow));
    return rows.map((row, rowIndex) => `<div class="psh-preset-row">${row.map((hex, columnIndex) => {
      const index = rowIndex * perRow + columnIndex;
      return `<button type="button" class="psh-preset${hex.toLowerCase() === target.toLowerCase() ? " active" : ""}" data-color="${hex}" data-preset-index="${index}" style="background:${hex}" title="${hex} · click apply · Ctrl+click save current"></button>`;
    }).join("")}</div>`).join("");
  }


  function photoshopPickerHtml(kind, key, target, title) {
    installPhotoshopPickerVisualStyles();
    const rgb = hexToRgbLocal(target);
    const hsv = rgbToHsv(rgb[0], rgb[1], rgb[2]);
    const attrKind = escapeAttr(kind);
    const attrKey = escapeAttr(key);
    const safeTitle = escapeHtml(title || "Color");
    return `
      <div class="psh-popover compact" data-picker-kind="${attrKind}" data-picker-key="${attrKey}">
        <div class="psh-head-row">
          <strong class="psh-layer-name">${safeTitle}</strong>
          <div class="psh-current" style="background:${target}" title="${target.toUpperCase()}"></div>
          <strong class="psh-hex-live">${target.toUpperCase()}</strong>
        </div>
        <div class="psh-main">
          <div class="psh-sv-wrap">
            <canvas class="psh-sv" width="360" height="210" data-psh-sv-kind="${attrKind}" data-psh-sv-key="${attrKey}"></canvas>
          </div>
          <div class="psh-current-wrap psh-compact-controls">
            <div class="psh-rgb">
              <label>R <input type="number" min="0" max="255" data-psh-rgb-kind="${attrKind}" data-psh-rgb-key="${attrKey}" data-channel="r" value="${rgb[0]}"></label>
              <label>G <input type="number" min="0" max="255" data-psh-rgb-kind="${attrKind}" data-psh-rgb-key="${attrKey}" data-channel="g" value="${rgb[1]}"></label>
              <label>B <input type="number" min="0" max="255" data-psh-rgb-kind="${attrKind}" data-psh-rgb-key="${attrKey}" data-channel="b" value="${rgb[2]}"></label>
            </div>
            <div class="psh-hex-field">
              <span class="psh-hex-prefix" aria-hidden="true">#</span>
              <input class="piece-hex-input psh-hex" type="text" inputmode="text" autocomplete="off" data-psh-hex-kind="${attrKind}" data-psh-hex-key="${attrKey}" value="${target.replace("#", "").toUpperCase()}" maxlength="7" spellcheck="false" title="HEX color, with or without #, example 151515">
              <button type="button" data-copy-picker-hex="${attrKind}|${attrKey}" title="Copy HEX">⧉</button>
            </div>
            <button type="button" class="psh-eyedrop icon-only" data-eyedropper-kind="${attrKind}" data-eyedropper-key="${attrKey}" title="Eyedropper"><img src="./assets/ui/eyedropper-red.png" alt="" /> Eyedropper</button>
          </div>
        </div>
        <div class="psh-hue-row">
          <label>Hue</label>
          <input class="psh-hue-slider" type="range" min="0" max="360" value="${Math.round(hsv.h)}" data-psh-hue-kind="${attrKind}" data-psh-hue-key="${attrKey}" title="Hue ${Math.round(hsv.h)}°">
        </div>
        <div class="psh-presets" data-psh-presets-kind="${attrKind}" data-psh-presets-key="${attrKey}">${colorPickerPresetRows(target)}</div>
        <div class="psh-apply-row">
          <button type="button" class="psh-apply" data-psh-apply="${attrKind}|${attrKey}">Apply</button>
          <button type="button" class="psh-cancel" data-psh-cancel="${attrKind}|${attrKey}">Cancel</button>
        </div>
      </div>
    `;
  }

  function applyPickerColor(kind, key, rawValue) {
    const value = normalizeHexColor(rawValue);
    if (kind === "piece") {
      applyPieceColor(key, value);
      // v1.3.117: piece color changes update the current chip/HEX/Hue immediately;
      // repaint the SV square too so the selector crosshair does not stay frozen.
      requestAnimationFrame(drawPieceColorPickerCanvases);
      return;
    }
    if (kind === "logo") {
      const [part, index, source] = key.split("|");
      const layer = getLayerByIndex(part, index);
      if (!layer || !layerAllowsLogoColor(part, layer)) return;
      getPart(part).selected = Number(index);
      layer.colorMap = layer.colorMap || {};
      const normalizedSource = normalizeHexColor(source);
      if (value === normalizedSource) delete layer.colorMap[normalizedSource];
      else layer.colorMap[normalizedSource] = value;
      layer._processedImageCache = {};
      syncLogoColorChipDom(part, index, normalizedSource, value);
      requestAnimationFrame(drawPieceColorPickerCanvases);
      scheduleBrandInteractionRender({ accurate: true, accurateDelayMs: 420 });
      return;
    }
    if (kind === "template") {
      const [id, source] = key.split("|");
      const layer = findTemplateLayer(id);
      if (!layer) return;
      const normalizedSource = normalizeHexColor(source || templatePaletteSource(layer));
      layer.colorMap = layer.colorMap || {};
      if (value === normalizedSource) {
        delete layer.colorMap[normalizedSource];
        layer._templateChipColor = normalizedSource;
      } else {
        layer.colorMap[normalizedSource] = value;
        layer._templateChipColor = value;
      }
      layer._renderCache = null;
      layer._renderCacheKey = "";
      const chip = templateVisibleChipColor(layer, normalizedSource);
      const changed = templateLayerHasUserColor(layer, normalizedSource);
      // Do not rebuild the whole detail row while the picker is open. Brand works
      // because its swatch is tied to the live colorMap; update the exact DOM chip
      // and picker header, then refresh the panel only when Apply/Cancel closes it.
      syncTemplateColorChipDom(key, normalizedSource, chip, changed);
      requestAnimationFrame(drawPieceColorPickerCanvases);
      renderAfterTemplateLayerEdit(layer);
      return;
    }
    if (kind === "border") {
      const [part, index] = key.split("|");
      const layer = getLayerByIndex(part, index);
      if (!layer) return;
      getPart(part).selected = Number(index);
      layer.border.color = value;
      layer._processedImageCache = {};
      syncBorderColorChipDom(part, index, value);
      requestAnimationFrame(drawPieceColorPickerCanvases);
      scheduleBrandInteractionRender({ accurate: true, accurateDelayMs: 420 });
    }
  }

  function updatePickerHue(kind, key, hue) {
    const current = pickerDomCurrentHex(kind, key) || pickerCurrentHex(kind, key);
    const [r, g, b] = hexToRgbLocal(current);
    const hsv = rgbToHsv(r, g, b);
    const rgb = hsvToRgb(Number(hue), hsv.s, hsv.v);
    applyPickerColor(kind, key, rgbToHex(rgb[0], rgb[1], rgb[2]));
  }

  function updatePickerRgb(kind, key) {
    const inputs = document.querySelectorAll(`[data-psh-rgb-kind="${CSS.escape(kind)}"][data-psh-rgb-key="${CSS.escape(key)}"]`);
    const values = { r: 0, g: 0, b: 0 };
    inputs.forEach((input) => { values[input.dataset.channel] = input.value; });
    applyPickerColor(kind, key, rgbToHex(values.r, values.g, values.b));
  }

  function pickerCurrentHex(kind, key) {
    if (kind === "piece") return normalizeHexColor(state.pieceColors[key]?.target || state.pieceColors[key]?.source || "#151515");
    if (kind === "logo") {
      const [part, index, source] = key.split("|");
      const layer = getLayerByIndex(part, index);
      return normalizeHexColor(layer?.colorMap?.[normalizeHexColor(source)] || source || "#ffffff");
    }
    if (kind === "template") {
      const [id, source] = key.split("|");
      const layer = findTemplateLayer(id);
      const normalizedSource = normalizeHexColor(source);
      return normalizeHexColor(layer ? templateVisibleChipColor(layer, normalizedSource) : (normalizedSource || "#ffffff"));
    }
    if (kind === "border") {
      const [part, index] = key.split("|");
      return normalizeHexColor(getLayerByIndex(part, index)?.border?.color || "#ffffff");
    }
    return "#151515";
  }

  function pieceColorRowHtml(pieceId) {
    const meta = PIECE_META_BY_ID[pieceId];
    const colorState = state.pieceColors[pieceId];
    const source = normalizeHexColor(colorState?.source || "#111111");
    const target = normalizeHexColor(colorState?.target || source);
    const isOpen = state.activeColorPicker === pieceId;
    return `
      <div class="piece-color-row photoshop-color-row ${isOpen ? "picker-open" : ""}" data-color-row="${escapeAttr(pieceId)}">
        <span>${escapeHtml(meta?.label || pieceId)}</span>
        <button type="button" class="piece-color-swatch" data-open-piece-picker="${escapeAttr(pieceId)}" style="background:${target}" title="${target}"></button>
        ${isOpen ? photoshopPickerHtml("piece", pieceId, target, `${meta?.label || pieceId} color`) : ""}
      </div>
    `;
  }


  function renderPieceColorPanels() {
    if (els.shirtPieceColors) els.shirtPieceColors.innerHTML = PIECE_PANELS.shirt.map(pieceColorRowHtml).join("");
    if (els.shortPieceColors) els.shortPieceColors.innerHTML = PIECE_PANELS.short.map(pieceColorRowHtml).join("");
    if (els.socksPieceColors) els.socksPieceColors.innerHTML = PIECE_PANELS.socks.map(pieceColorRowHtml).join("");
    requestAnimationFrame(drawPieceColorPickerCanvases);
  }


  const PHOTOSHOP_BLEND_MODES = [
    ["source-over", "Normal"],
    ["multiply", "Multiply"],
    ["screen", "Screen"],
    ["overlay", "Overlay"],
    ["soft-light", "Soft Light"],
    ["hard-light", "Hard Light"],
    ["color-dodge", "Color Dodge"],
    ["color-burn", "Color Burn"],
    ["darken", "Darken"],
    ["lighten", "Lighten"],
    ["difference", "Difference"],
    ["exclusion", "Exclusion"],
    ["hue", "Hue"],
    ["saturation", "Saturation"],
    ["color", "Color"],
    ["luminosity", "Luminosity"],
  ];

  const TEXTURE_BLEND_MODES = [
    ["source-over", "Normal"],
    ["multiply", "Multiply"],
    ["overlay", "Overlay"],
  ];

  function makeTextureLayer(image, name, blendMode = "multiply", opacity = 1, src = null) {
    return {
      id: uid(),
      image,
      src: src || image?.src || null,
      name: name || "Texture",
      enabled: true,
      blendMode,
      opacity: clamp(Number(opacity), 0, 1),
    };
  }

  function makeDefaultWrinkleTextureLayers() {
    const textureImage = templateImages.texture || null;
    return [
      makeTextureLayer(textureImage, "VillaPilla texture", "overlay", 0.5, TEMPLATE_ASSETS.texture),
      makeTextureLayer(textureImage, "VillaPilla texture copy", "multiply", 1, TEMPLATE_ASSETS.texture),
    ];
  }

  function hydrateBuiltinTextureLayers() {
    if (!templateImages.texture || !Array.isArray(state.textureLayers)) return;
    for (const layer of state.textureLayers) {
      if (!layer || layer.image) continue;
      const src = String(layer.src || layer.dataSrc || "");
      if (src === TEMPLATE_ASSETS.texture || /^VillaPilla texture( copy)?$/i.test(String(layer.name || "").trim())) {
        layer.image = templateImages.texture;
        layer.src = TEMPLATE_ASSETS.texture;
      }
    }
  }

  async function ensureDefaultWrinkleTextureLoaded() {
    if (templateImages.texture) {
      hydrateBuiltinTextureLayers();
      return templateImages.texture;
    }
    try {
      const loaded = await loadImagePromise(TEMPLATE_ASSETS.texture);
      if (loaded && loaded.image) {
        templateImages.texture = loaded.image;
        hydrateBuiltinTextureLayers();
        return loaded.image;
      }
    } catch (error) {
      console.warn("Default texture warmup skipped:", error);
    }
    return null;
  }

  function applyDefaultUvGuideSettings() {
    state.showUv = false;
    state.showGuide = false;
    state.uvOpacity = 0.5;
    state.guideOpacity = 0.5;
    syncSettingsVisibilityIcons();
  }

  function initializeTextureLayers(options = {}) {
    if (state.textureLayers.length && options.force !== true) {
      hydrateBuiltinTextureLayers();
      return;
    }
    state.textureLayers = makeDefaultWrinkleTextureLayers();
    state.textureSelected = 0;
    hydrateBuiltinTextureLayers();
  }

  function savedTextureLayersAreOnlyBuiltinTexture(savedLayers = []) {
    if (!Array.isArray(savedLayers) || !savedLayers.length) return true;
    return savedLayers.every((layer) => {
      if (!layer || typeof layer !== "object") return false;
      const src = String(layer.src || layer.dataSrc || "");
      return layer.builtinTexture === true || src === TEMPLATE_ASSETS.texture || /^VillaPilla texture( copy)?$/i.test(String(layer.name || "").trim());
    });
  }

  function renderTextureLayers() {
    if (!els.textureLayerList) return;
    if (KITLAB_PUBLIC_BETA_HIDE.textureWrinklesSettings) {
      els.textureLayerList.innerHTML = "";
      return;
    }
    if (!state.textureLayers.length) {
      els.textureLayerList.innerHTML = `<div class="settings-texture-empty">No texture loaded</div>`;
      return;
    }
    state.textureSelected = clamp(Number(state.textureSelected || 0), 0, state.textureLayers.length - 1);
    els.textureLayerList.innerHTML = state.textureLayers.map((layer, index) => {
      const opacityPct = Math.round(clamp(Number(layer.opacity ?? 1), 0, 1) * 100);
      const blend = layer.blendMode || "multiply";
      const options = TEXTURE_BLEND_MODES.map(([value, label]) => `<option value="${value}" ${blend === value ? "selected" : ""}>${label}</option>`).join("");
      const activeClass = index === state.textureSelected ? " is-selected" : "";
      return `
        <div class="settings-texture-row${activeClass}" data-texture-layer="${index}">
          <button class="settings-icon-btn settings-texture-duplicate-btn" type="button" data-texture-duplicate="${index}" title="Duplicate texture" aria-label="Duplicate texture">
            <img src="./assets/ui/Duplicado_white_v0924.png?v=0924" alt="" />
          </button>
          <span class="settings-texture-name" title="${escapeAttr(layer.name || "Texture")}">${escapeHtml(layer.name || "Texture")}</span>
          <select class="settings-texture-blend" data-texture-blend="${index}">${options}</select>
          <input class="settings-texture-opacity" type="range" min="0" max="100" value="${opacityPct}" data-texture-opacity="${index}">
          <input class="settings-texture-opacity-number" type="number" min="0" max="100" step="1" value="${opacityPct}" data-texture-opacity-num="${index}" aria-label="Texture opacity percent">
        </div>
      `;
    }).join("");
  }

  function syncTextureOpacityControls(index, value) {
    if (!els.textureLayerList) return;
    const row = els.textureLayerList.querySelector(`[data-texture-layer="${index}"]`);
    if (!row) return;
    const pct = Math.round(clamp(Number(value), 0, 100));
    const range = row.querySelector(`[data-texture-opacity="${index}"]`);
    const number = row.querySelector(`[data-texture-opacity-num="${index}"]`);
    if (range && document.activeElement !== range) range.value = String(pct);
    if (number && document.activeElement !== number) number.value = String(pct);
  }

  function syncSettingsVisibilityIcons() {
    const uvOn = !!state.showUv;
    const guideOn = !!state.showGuide;
    if (els.showUv) els.showUv.checked = uvOn;
    if (els.showGuide) els.showGuide.checked = guideOn;
    if (els.showUvEyeIcon) els.showUvEyeIcon.src = uvOn ? "./assets/ui/Ojo_abierto_white.png" : "./assets/ui/Ojo_cerrado_red.png";
    if (els.showGuideEyeIcon) els.showGuideEyeIcon.src = guideOn ? "./assets/ui/Ojo_abierto_white.png" : "./assets/ui/Ojo_cerrado_red.png";
    if (els.uvOpacity) els.uvOpacity.value = String(Math.round(clamp(Number(state.uvOpacity ?? 1), 0, 1) * 100));
    if (els.guideOpacity) els.guideOpacity.value = String(Math.round(clamp(Number(state.guideOpacity ?? 1), 0, 1) * 100));
    if (els.uvOpacityText) els.uvOpacityText.textContent = `${Math.round(clamp(Number(state.uvOpacity ?? 1), 0, 1) * 100)}%`;
    if (els.guideOpacityText) els.guideOpacityText.textContent = `${Math.round(clamp(Number(state.guideOpacity ?? 1), 0, 1) * 100)}%`;
  }

  function loadTextureFile(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      loadImageFromSrc(reader.result, (image) => {
        state.textureLayers.push(makeTextureLayer(image, file.name, "multiply", 1, reader.result));
        state.textureSelected = state.textureLayers.length - 1;
        renderTextureLayers();
        render();
        setStatus(`Texture loaded: ${file.name}`);
      });
    };
    reader.readAsDataURL(file);
  }

  function duplicateTextureLayer(index) {
    const sourceIndex = Number(index);
    const layer = state.textureLayers[sourceIndex];
    if (!layer) return;
    const copy = makeTextureLayer(layer.image, `${layer.name} copy`, layer.blendMode, layer.opacity, layer.src);
    state.textureLayers.splice(sourceIndex + 1, 0, copy);
    state.textureSelected = sourceIndex + 1;
    renderTextureLayers();
    scheduleRender();
  }

  function deleteTextureLayer(index) {
    const idx = Number(index);
    if (!state.textureLayers[idx]) return;
    state.textureLayers.splice(idx, 1);
    state.textureSelected = clamp(state.textureSelected, 0, Math.max(0, state.textureLayers.length - 1));
    renderTextureLayers();
    scheduleRender();
  }

  function buildTemplateCache() {
    clearTemplatePieceCanvasCache();
    const base = makeCanvas();
    const bctx = base.getContext("2d");
    const bottomToTopPieces = [...TEMPLATE_ASSETS.pieces].sort((a, b) => (b.order || 0) - (a.order || 0));
    bottomToTopPieces.forEach((piece) => {
      const index = TEMPLATE_ASSETS.pieces.findIndex((p) => p.id === piece.id);
      const templateBasePiece = state.templateStyle?.basePieces?.[piece.id]?.image;
      drawTemplatePiece(bctx, templateBasePiece || templateImages.pieces[index], piece.id);
    });
    // v0.8.43: detalles/armband/ankle boxes are no longer painted as separate base pieces.
    // They stay inside the full texture layer exactly as supplied by Texturas/VillaPilla/textura.png,
    // so the Photoshop stack is: ordered kit pieces below, then full texture/wrinkles above.

    const mask = makeCanvas();
    const mctx = mask.getContext("2d");
    TEMPLATE_ASSETS.pieces.forEach((piece, index) => {
      const templateBasePiece = state.templateStyle?.basePieces?.[piece.id]?.image;
      drawFullSize(mctx, templateBasePiece || templateImages.pieces[index]);
    });

    const texture = null;

    const seamsFj = makeCanvas();
    const fjCtx = seamsFj.getContext("2d");
    for (const image of templateImages.seamsFj) drawFullSize(fjCtx, image);
    maskCanvasWithTemplate(seamsFj, mask);

    const seamsIv = buildAdaptiveIvCanvas();
    maskCanvasWithTemplate(seamsIv, mask);

    templateCache = {
      base,
      mask,
      texture,
      seamsFj,
      seamsIv,
      transparency: templateImages.transparency,
    };
    invalidateInteractionRenderCache("all");
  }

  function rebuildTemplateBaseOnly() {
    if (!templateCache) { buildTemplateCache(); return; }
    const base = makeCanvas();
    const bctx = base.getContext("2d");
    const bottomToTopPieces = [...TEMPLATE_ASSETS.pieces].sort((a, b) => (b.order || 0) - (a.order || 0));
    bottomToTopPieces.forEach((piece) => {
      const index = TEMPLATE_ASSETS.pieces.findIndex((p) => p.id === piece.id);
      const templateBasePiece = state.templateStyle?.basePieces?.[piece.id]?.image;
      drawTemplatePiece(bctx, templateBasePiece || templateImages.pieces[index], piece.id);
    });
    templateCache.base = base;
    invalidateInteractionRenderCache("base");
  }

  
  function drawTemplateBase() {
    // Basic color pieces are always the base of the kit.
    // This function was missing in the previous branch and caused render() to stop.
    if (!templateCache || !templateCache.base) return;
    ctx.drawImage(templateCache.base, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
  }

  function loadImagePromise(src) {
    return new Promise((resolve) => {
      if (!src) { resolve(null); return; }
      let done = false;
      const finish = (value) => {
        if (done) return;
        done = true;
        resolve(value);
      };

      const img = new Image();
      img.onload = () => finish({ image: img, src });
      img.onerror = () => {
        console.warn("Template image skipped:", src);
        finish(null);
      };

      // Same-name PNG replacements must be detected safely.
      // Keep the original src stored in state/settings, but request local assets with a fresh
      // cache-busting token every time the image is actually loaded.
      img.src = withAssetCacheBust(src);

      // Safety timeout: never leave the kit blank because one asset did not answer.
      setTimeout(() => {
        if (!done) {
          console.warn("Template image timeout:", src);
          finish(null);
        }
      }, 2500);
    });
  }

  function safeDetectOnePredominantColor(image) {
    try {
      // Use the same palette detector that already works for Brand/Team/Sponsor.
      // Template detail chips must be driven by the PNG source color, not by a
      // separate UI-only guess. Keep one chip for template rows, but detect it
      // with the proven logo pipeline.
      const colors = safeDetectPredominantColors(image);
      if (colors.length) return [normalizeHexColor(colors[0])];
    } catch (error) {
      console.warn("Template detail palette detection skipped:", error);
    }
    try {
      const iw = image.naturalWidth || image.width;
      const ih = image.naturalHeight || image.height;
      if (!iw || !ih) return [];
      const maxSide = 512;
      const ratio = Math.min(maxSide / iw, maxSide / ih, 1);
      const sample = document.createElement("canvas");
      sample.width = Math.max(1, Math.round(iw * ratio));
      sample.height = Math.max(1, Math.round(ih * ratio));
      const sctx = sample.getContext("2d", { willReadFrequently: true });
      sctx.imageSmoothingEnabled = false;
      sctx.drawImage(image, 0, 0, sample.width, sample.height);
      const data = sctx.getImageData(0, 0, sample.width, sample.height).data;
      const counts = new Map();
      for (let i = 0; i < data.length; i += 4) {
        const a = data[i + 3];
        if (a < 18) continue;
        const r = data[i], g = data[i + 1], b = data[i + 2];
        if (a < 180 && r > 245 && g > 245 && b > 245) continue;
        const q = 8;
        const qr = clamp(Math.round(r / q) * q, 0, 255);
        const qg = clamp(Math.round(g / q) * q, 0, 255);
        const qb = clamp(Math.round(b / q) * q, 0, 255);
        const key = `${qr},${qg},${qb}`;
        counts.set(key, (counts.get(key) || 0) + Math.max(1, a / 255));
      }
      if (!counts.size) return [];
      const [key] = [...counts.entries()].sort((a, b) => b[1] - a[1])[0];
      const [r, g, b] = key.split(",").map(Number);
      return [rgbToHex(r, g, b)];
    } catch (error) {
      return [];
    }
  }

  function templateLayerKeepsOriginalColor(meta = {}) {
    const folder = String(meta.folder || "").trim().toLowerCase();
    // PNGs that live in the real template `detalles/details` folder must start
    // with their detected original color. Base pieces keep #151515 separately.
    return folder === "detalles" || folder === "detalle" || folder === "details" || folder === "detail";
  }

  function templateLayerDirectiveText(meta = {}) {
    // v1.0.1: directives must survive visible-name cleanup and data: URLs.
    // Importer stores the original relative ZIP path because that is the
    // authoritative place where words like "fusion opacidad" / "no color" live.
    let text = `${meta?.name || ""} ${meta?.displayName || ""} ${meta?.folder || ""} ${meta?.rawName || ""} ${meta?.originalName || ""} ${meta?.originalPath || ""} ${meta?.importRel || ""} ${meta?.directiveSource || ""} ${meta?.sourceName || ""} ${meta?.path || meta?.src || ""}`;
    try { text = decodeURIComponent(text); } catch (_) {}
    return String(text || "")
      .normalize("NFD")
      .replace(/[̀-ͯ]/g, "")
      .replace(/[_.-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  }

  function templateLayerDirectiveCompact(meta = {}) {
    return templateLayerDirectiveText(meta).replace(/\s+/g, "");
  }

  function templateLayerHasBlendDirective(meta = {}) {
    const text = templateLayerDirectiveText(meta);
    const compact = templateLayerDirectiveCompact(meta);
    return /(^|\s)(fusion|blend|blending|modo fusion|modo de fusion)(\s|$)/i.test(text) || compact.includes("fusion") || compact.includes("blend");
  }

  function templateLayerHasOpacityDirective(meta = {}) {
    const text = templateLayerDirectiveText(meta);
    const compact = templateLayerDirectiveCompact(meta);
    return /(^|\s)(opacidad|opacity|opacityctl|opa)(\s|$)/i.test(text) || compact.includes("opacidad") || compact.includes("opacity") || compact.includes("opaciadad");
  }

  function templateLayerIsRubberBand(meta = {}) {
    return /(^|\s)rubber\s*band(\s|$)/i.test(templateLayerDirectiveText(meta)) || templateLayerDirectiveCompact(meta).includes("rubberband");
  }

  function templateLayerIsLockedOriginalColor(meta = {}) {
    const text = templateLayerDirectiveText(meta);
    const compact = templateLayerDirectiveCompact(meta);
    const isBrilloTechnical = /(^|\s)(brillo|highlight)(\s|$)/i.test(text) && (compact.includes("fusion") || compact.includes("blend")) && (compact.includes("opacidad") || compact.includes("opacity"));
    return templateLayerIsButtonShine(meta) || templateLayerIsRubberBand(meta) || isBrilloTechnical || /(^|\s)(etiqueta|label|no color|sin color|original color|color original)(\s|$)/i.test(text) || compact.includes("nocolor") || compact.includes("sincolor");
  }

  function templateLayerIsTights(meta = {}) {
    return /(^|\b)(?:tights?|mesh)(\b|$)/i.test(templateLayerDirectiveText(meta));
  }

  // v1.3.263: Collar shadow law. A collar layer named exactly
  // "detail shadow opacidad.png" is a technical black alpha shadow:
  // no colour control, opacity only, and Normal mode. This applies to every
  // collar category while collar transparency remains the final cut.
  function templateLayerIsRetroFixedBlackShadow(meta = {}) {
    const rawName = String(meta?.rawName || meta?.name || "").trim().toLowerCase();
    const section = String(meta?.section || "").trim().toLowerCase();
    const candidates = [meta?.originalPath, meta?.path, meta?.src]
      .map((value) => {
        let path = String(value || "");
        try { path = decodeURIComponent(path); } catch (_) {}
        return path.replace(/\\/g, "/").toLowerCase();
      });
    const isExactFile = rawName === "detail shadow opacidad.png"
      || candidates.some((path) => path.endsWith("/detail shadow opacidad.png"));
    const isCollarLayer = section === "collar" || section === "collar_seams"
      || candidates.some((path) => path.includes("/collar/") || path.startsWith("collar/"));
    return isExactFile && isCollarLayer;
  }

  function enforceRetroFixedBlackShadowLayer(layer = null) {
    if (!layer || !templateLayerIsRetroFixedBlackShadow(layer)) return layer;
    layer.blend = false;
    layer.opacityCtl = true;
    layer.noColor = true;
    layer.blendMode = "source-over";
    layer.palette = [];
    layer.colorMap = {};
    layer._detectedColor = "#000000";
    layer.sourceColor = "#000000";
    layer._templateChipColor = "#000000";
    layer._userColorApplied = false;
    layer._appliedChipColor = "";
    layer._renderCache = null;
    layer._renderCacheKey = "";
    return layer;
  }

  function templateLayerForcesBlendOpacity(meta = {}) {
    const folder = String(meta?.folder || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
    const text = templateLayerDirectiveText(meta);
    // Law v1.0.99: Rubber Band PNGs are technical/original-color layers:
    // no color swatch, preserve PNG colors, and always expose Fusion + Opacity.
    // Law v1.0.2+: mesh/fabric always carry Photoshop Fusion + Opacity controls,
    // including collar-local layers like "Tights Rubber Band" even when they are
    // not inside the global tights folder.
    return templateLayerIsButtonShine(meta) || templateLayerIsRubberBand(meta) || folder === "tights" || folder === "mesh" || folder === "fabric" || folder === "extra" || templateLayerIsTights(meta) || /(^|\s)(fabric|extra)(\s|$)/i.test(text);
  }

  function templateLayerHasAnyFusionOpacityControl(meta = {}) {
    return templateLayerForcesBlendOpacity(meta) || meta?.blend === true || meta?.opacityCtl === true || templateLayerHasBlendDirective(meta) || templateLayerHasOpacityDirective(meta);
  }

  function templateLayerIsAeroFit(meta = {}) {
    return /aero\s*fit|aero-fit/i.test(templateLayerDirectiveText(meta));
  }

  function templateLayerIsColorableCollar(meta = {}) {
    // Collar color must behave like a true selected base color, not like a
    // re-detected rendered pixel. If user selects #151515, UI state and base
    // fill remain exactly #151515; texture/wrinkles are applied above later.
    const section = String(meta.section || "").toLowerCase();
    if (section !== "collar") return false;
    if (templateLayerIsLockedOriginalColor(meta) || templateLayerIsTights(meta)) return false;
    return true;
  }

  function templateCollarColorSource(meta = {}) {
    return templateLayerIsColorableCollar(meta) ? KITLAB_CANONICAL_DEFAULT_COLOR : null;
  }

  function templateFolderIsAeroFit(folder = "") {
    return /aero\s*fit|aero-fit|^fabric$|^extra$/i.test(String(folder || "").replace(/[_-]+/g, " ").trim());
  }

  function templateSectionFromMeta(meta = {}) {
    const text = templateLayerDirectiveText(meta);
    // Sleeve/short-sleeve assets belong to SHIRT. This must win before the word "short".
    if (/\b(sleeve short|short sleeve|short sleeves|sleeve long|long sleeve|sleeves?|manga)\b/i.test(text)) return "shirt";
    if (/\bshirt\b|\bcamiseta\b/i.test(text)) return "shirt";
    if (/\bsocks?\b|\bankle\b|\bmedias?\b|\bcalcetin(?:es)?\b/i.test(text)) return "socks";
    if (/\bshorts?\b|\bpantal[oó]n\b/i.test(text)) return "short";
    return meta.section || "shirt";
  }

  function templateBasePieceIdFromMeta(meta = {}) {
    // Some uploaded templates may include the real base pieces inside `detalles/`.
    // Those files are not details and must never be duplicated in the detail stack.
    // Match only exact clean layer names, so "shirt final" or "sleeve short puno"
    // remain real details, while "shirt" / "sleeve short" become base pieces.
    // v1.0.65: never classify technical template folders as base pieces, even if
    // a fabric/tights layer is named exactly "short" or "sleeve short". Puma 2026
    // Ultraweaver exposed this: those PNGs belong in Fabric, not in BASE.
    const pathText = (() => { try { return decodeURIComponent(String(meta.originalPath || meta.path || "")); } catch (_) { return String(meta.originalPath || meta.path || ""); } })().replace(/\\/g, "/").toLowerCase();
    if (/(^|\/)(fabric|extra|tights|mesh|brand|pattern|seams|collar)(\/|$)/i.test(pathText)) return null;
    const rawName = String(meta.name && meta.name !== "Layer" ? meta.name : (meta.path || "").split("/").pop() || "");
    let clean = rawName;
    try { clean = decodeURIComponent(clean); } catch (_) {}
    clean = clean
      .replace(/\.[a-z0-9]+$/i, "")
      .replace(/^\s*\d+\s*[\.\-_ ]\s*/i, "")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
    const map = {
      "sleeve short": "sleeve_short",
      "shirt": "shirt",
      "sleeve long": "sleeve_long",
      "short": "short",
      "socks": "socks",
      "ankle": "ankle",
    };
    return map[clean] || null;
  }

  function templateInitialColorMap(palette, meta = {}) {
    if (meta.noColor || templateLayerIsLockedOriginalColor(meta) || templateLayerIsTights(meta)) return {};
    const collarSource = templateCollarColorSource(meta);
    if (collarSource) return { [normalizeHexColor(collarSource)]: normalizeHexColor(collarSource) };
    if (!Array.isArray(palette) || !palette.length) return {};
    const source = normalizeHexColor(palette[0]);
    if (templateLayerKeepsOriginalColor(meta)) return {};
    return { [source]: KITLAB_CANONICAL_DEFAULT_COLOR };
  }

  function sanitizeTemplateColorMap(layer, incoming = null) {
    const base = incoming && typeof incoming === "object" ? incoming : (layer.colorMap || {});
    const out = {};
    for (const [source, target] of Object.entries(base || {})) {
      const s = normalizeHexColor(source);
      const t = normalizeHexColor(target);
      if (s && t) out[s] = t;
    }
    if (!layer.noColor && !templateLayerIsLockedOriginalColor(layer) && !templateLayerIsTights(layer)) {
      const collarSource = templateCollarColorSource(layer);
      if (collarSource) {
        const source = normalizeHexColor(collarSource);
        if (!out[source]) out[source] = source;
        return out;
      }
      if (Array.isArray(layer.palette) && layer.palette.length && !templateLayerKeepsOriginalColor(layer)) {
        const source = normalizeHexColor(layer.palette[0]);
        if (!out[source]) out[source] = KITLAB_CANONICAL_DEFAULT_COLOR;
      }
    }
    return out;
  }

  function directiveDisplayName(name) {
    return String(name || "")
      .replace(/^\d+[\.\-_ ]*/, "")
      .replace(/\b(fusion|opacidad|opacity|no\s*color|no\s*colours|no\s*colors)\b/gi, "")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function templateLayerSort(a, b) {
    // Photoshop-style UI order: smaller numbers are visually above larger numbers.
    return (Number(a.order) || 999) - (Number(b.order) || 999);
  }

  function templateFolderIsBaseDesign(folder = "") {
    const normalized = String(folder || "").replace(/[_-]+/g, " ").trim().toLowerCase();
    return normalized === "base design" || normalized === "base desing";
  }

  function templateLayerSourcePath(layer = {}) {
    let raw = String(layer?.src || layer?.path || layer?.key || "");
    try { raw = decodeURIComponent(raw); } catch (_) {}
    return raw.replace(/\\/g, "/");
  }

  function templateLayerUsesGuidedPatternEngine(layer = {}) {
    if (layer?.isUserPattern === true || layer?.isUserBaseDesign === true) return true;
    // v1.3.160: Base Design must use the exact same guided paint engine as Pattern.
    // Color guide PNGs place the artwork; the active template /guide PNGs only crop visibility.
    // This also covers template-local folders named `base design` / the old typo `base desing`.
    if (templateFolderIsBaseDesign(layer?.folder)) return true;
    const src = templateLayerSourcePath(layer).toLowerCase();
    const original = safeDecodeKitlabPath(layer?.originalPath || layer?.sourceName || layer?.directiveSource || layer?.rawName || layer?.path || layer?.src || "")
      .replace(/\\/g, "/")
      .toLowerCase();
    // Backwards compatibility for saved user-added assets that may not have flags.
    // Official template Pattern folders stay as normal template detail layers; only Base Design is promoted here.
    return src.includes("assets/base_design/") || /(^|\/)base\s+desi(?:gn|ng)(\/|$)/i.test(original);
  }

  function markGuidedPatternLayerKind(layer = {}) {
    if (!layer || !templateLayerUsesGuidedPatternEngine(layer)) return layer;
    const src = templateLayerSourcePath(layer).toLowerCase();
    const original = safeDecodeKitlabPath(layer?.originalPath || layer?.sourceName || layer?.directiveSource || layer?.rawName || layer?.path || layer?.src || "")
      .replace(/\\/g, "/")
      .toLowerCase();
    if (layer.isUserBaseDesign === true || src.includes("assets/base_design/") || templateFolderIsBaseDesign(layer.folder) || /(^|\/)base\s+desi(?:gn|ng)(\/|$)/i.test(original)) {
      layer.isUserBaseDesign = true;
      layer.isUserPattern = false;
      layer.folder = "Base Design";
    } else {
      layer.isUserPattern = true;
      layer.isUserBaseDesign = false;
      layer.folder = "Pattern";
    }
    normalizePatternZones(layer);
    return layer;
  }

  function normalizePatternBelowFabric(section) {
    const list = state.templateStyle.details?.[section];
    if (!Array.isArray(list) || !list.length) return;
    const normalizeFolder = (value) => String(value || "").toLowerCase().replace(/[_-]+/g, " ").trim();
    const isPatternLikeLayer = (layer) => templateFolderIsPattern(layer?.folder) || templateFolderIsBaseDesign(layer?.folder) || layer?.isUserPattern === true || layer?.isUserBaseDesign === true;
    const isFabricLayer = (layer) => {
      const folder = normalizeFolder(layer?.folder);
      return folder === "fabric" || folder === "extra";
    };
    const patternItems = list.filter(isPatternLikeLayer);
    if (!patternItems.length || !list.some(isFabricLayer)) return;
    const withoutPattern = list.filter((layer) => !isPatternLikeLayer(layer));
    let insertAt = -1;
    for (let i = 0; i < withoutPattern.length; i += 1) {
      if (isFabricLayer(withoutPattern[i])) insertAt = i + 1;
    }
    if (insertAt < 0) return;
    const nextList = [
      ...withoutPattern.slice(0, insertAt),
      ...patternItems,
      ...withoutPattern.slice(insertAt),
    ];
    list.splice(0, list.length, ...nextList);
  }

  function normalizeAllPatternBelowFabric() {
    for (const section of ["shirt", "short", "socks"]) normalizePatternBelowFabric(section);
  }

  async function selectTemplateStyle(item) {
    kitlabApplyPuma2026SharedCollarsToTemplate(item);
    const freshTemplateDraftLoad = window.__kitlabFreshTemplateDraftLoad === true && !window.__kitlabPendingProjectSettings;
    window.__kitlabFreshTemplateDraftLoad = false;
    if (freshTemplateDraftLoad) {
      kitlabProjectDraftMode = true;
      clearEditableKitDecorationsForFreshTemplate();
    }
    const defaultCollarForProgress = (item.collars || []).find((c) => String(c.id || c.name || "").match(/(^|\D)01(\D|$)/)) || (item.collars || [])[0];
    const progressTotal = Math.max(1,
      // template details, body seams, transparency
      (item.details || []).length +
      (item.seams || []).length +
      (item.transparency || []).length +
      // six base pieces
      6 +
      // base fallback scan through details
      (item.details || []).length +
      // default collar assets
      (defaultCollarForProgress?.details || []).length +
      (defaultCollarForProgress?.seams || []).length +
      (defaultCollarForProgress?.transparency || []).length +
      // ordering/UI cache/settings/final preparation tasks
      4
    );
    const templateLoadingDisplayName = window.__kitlabTemplateLoadingDisplayName || templateGalleryDisplayName(item);
    window.__kitlabTemplateLoadingDisplayName = "";
    const loadingTracker = makeTemplateLoadingTracker(templateLoadingDisplayName, progressTotal);

    try {
      state.templateStyle.selected = item;
      item.__kitlabGuideAssetsChecked = false;
      item.__kitlabGuideAssetsAvailable = false;
      item.__kitlabGuideAssetsStatus = "pending";
      item.__kitlabGuidePaintRolesAvailable = {};
      item.__kitlabGeneratedGuideAssetsChecked = {};
      item.__kitlabGeneratedGuideAssetsAvailable = {};
      item.__kitlabGeneratedGuideAssetsStatus = {};
      state.templateStyle.shortVariant = (Array.isArray(item.shortVariants) && item.shortVariants.length ? (item.shortVariants.find((variant) => variant.default === true)?.id || item.shortVariants[0]?.id || "v1") : "v1");
      installShortVariantButtonStyles();
      state.templateStyle.details = { shirt: [], short: [], socks: [] };
      state.templateStyle.seams = [];
      state.selectedSeamId = null;
      state.seamFolderOpen = false;
      state.templateStyle.transparency = [];
      state.templateStyle.basePieces = {};
      state.templateStyle.collarOptions = item.collars || [];
      INTERNAL_COLLARS = state.templateStyle.collarOptions.slice();
      state.templateStyle.collarLayers = [];
      state.templateStyle.collarSeams = [];
      state.templateStyle.collarTransparency = [];
      state.templateStyle.selectedCollar = null;
      state.templateStyle.collarConfigurations = {};
      state.templateDetailOpen = { shirt: {}, short: {}, socks: {}, collar: {} };
      state.collarDetailsOpen = false;
      // Every template starts with the same Settings defaults unless a project/custom texture overrides them later.
      await ensureDefaultWrinkleTextureLoaded();
      applyDefaultUvGuideSettings();
      initializeTextureLayers({ force: true });
      if (els.selectedTemplateName) els.selectedTemplateName.textContent = templateGalleryDisplayName(item);
      if (els.selectedCollarName) els.selectedCollarName.textContent = "Collar:";
      setStatus(`Loading template: ${templateGalleryDisplayName(item)}`);

      // EAGER load: the template is complete from the beginning.
      // UI folders stay folded, but their details are already loaded in memory.
      const baseDetailFallbacks = {};
      const baseFileByPiece = {
        sleeve_short: "sleeve short.png",
        shirt: "shirt.png",
        sleeve_long: "sleeve long.png",
        short: "short.png",
        socks: "socks.png",
        ankle: "ankle.png",
      };

      const layerPromises = (item.details || []).map(async (meta, index) => {
        try {
          // v0.9.89: never let an old/duplicated "sleeve short basic" detail override the
          // template-local base/01.sleeve short.png. The base/ folder is authoritative.
          if (/sleeve\s*short\s*basic/i.test(`${meta?.name || ""} ${meta?.path || ""}`)) return;
          if (templateBasePieceIdFromMeta(meta)) return;
          const loaded = await loadImagePromise(meta.path);
          if (!loaded || !loaded.image) return;
          const lockedOriginal = templateLayerIsLockedOriginalColor(meta);
          const forceBlendOpacity = templateLayerForcesBlendOpacity(meta);
          const hasBlend = forceBlendOpacity || meta.blend === true || templateLayerHasBlendDirective(meta);
          const hasOpacity = forceBlendOpacity || meta.opacityCtl === true || templateLayerHasOpacityDirective(meta);
          const layer = {
            ...meta,
            id: uid(),
            index,
            section: templateSectionFromMeta(meta),
            blend: hasBlend,
            opacityCtl: hasOpacity,
            noColor: meta.noColor === true || lockedOriginal,
            enabled: meta.enabled !== false && !/puntos|dots/i.test(meta.name || meta.path || ""),
            image: loaded.image,
            src: loaded.src,
            loaded: true,
            palette: (meta.noColor === true || lockedOriginal) ? [] : (templateLayerIsColorableCollar(meta) ? [KITLAB_CANONICAL_DEFAULT_COLOR] : safeDetectOnePredominantColor(loaded.image)),
            colorMap: {},
            blendMode: hasBlend ? "overlay" : (meta.blendMode || "source-over"),
            opacity: Number(meta.opacity ?? 1),
          };
          templatePatternSubfolderDefaults(layer, item);
          if (templateLayerUsesGuidedPatternEngine(layer)) {
            markGuidedPatternLayerKind(layer);
            await loadPatternGuidesForLayer(layer);
          }
          layer.colorMap = templateInitialColorMap(layer.palette, layer);
          state.templateStyle.details[layer.section || "shirt"].push(layer);
        } finally {
          loadingTracker.step();
        }
      });
      const seamPromises = (item.seams || []).map(async (meta) => {
        try {
          const loaded = await loadImagePromise(meta.path);
          if (!loaded || !loaded.image) return;
          state.templateStyle.seams.push({
            ...meta,
            id: uid(),
            image: loaded.image,
            src: loaded.src,
            enabled: meta.enabled !== false,
            manualLab: meta.manualLab === true,
            ivMode: meta.ivMode || (isIvuUnionSeamMeta(meta) ? "shirtSideUnion" : undefined),
            blendMode: meta.manualLab ? "overlay" : (meta.blendMode || "source-over"),
            opacity: meta.manualLab ? (isManualFjSeam(meta) ? 1 : 0.4) : Number(meta.opacity ?? 1),
            inverted: meta.manualLab && !isManualFjSeam(meta) ? meta.inverted === true : false,
          });
        } finally {
          loadingTracker.step();
        }
      });
      const transPromises = (item.transparency || []).map(async (meta) => {
        try {
          const loaded = await loadImagePromise(meta.path);
          if (!loaded || !loaded.image) return;
          state.templateStyle.transparency.push({ ...meta, image: loaded.image, src: loaded.src, enabled: true });
        } finally {
          loadingTracker.step();
        }
      });

      const basePromises = Object.entries(baseFileByPiece).map(async ([pieceId, fileName]) => {
        try {
          const candidates = [];
          const manifestBase = item.basePieces?.[pieceId];
          if (typeof manifestBase === "string") candidates.push(manifestBase);
          else if (manifestBase?.path) candidates.push(manifestBase.path);
          const encodedName = encodeURIComponent(fileName).replace(/%2F/g, "/");
          candidates.push(`${String(item.path || "").replace(/\/+$/, "")}/base/${encodedName}`);
          for (const src of candidates) {
            const loaded = await loadImagePromise(src);
            if (loaded && loaded.image) {
              state.templateStyle.basePieces[pieceId] = { image: loaded.image, src: loaded.src };
              const detectedBaseColor = normalizeKitDefaultColor((safeDetectOnePredominantColor(loaded.image) || [])[0] || PIECE_COLOR_FALLBACKS[pieceId] || KITLAB_CANONICAL_DEFAULT_COLOR);
              state.pieceColors[pieceId] = { source: detectedBaseColor, target: detectedBaseColor };
              break;
            }
          }
        } finally {
          loadingTracker.step();
        }
      });

      const baseFromDetailsPromises = (item.details || []).map(async (meta) => {
        try {
          const pieceId = templateBasePieceIdFromMeta(meta);
          if (!pieceId) return;
          const loaded = await loadImagePromise(meta.path);
          if (loaded && loaded.image) baseDetailFallbacks[pieceId] = { image: loaded.image, src: loaded.src };
        } finally {
          loadingTracker.step();
        }
      });

      await Promise.all([...layerPromises, ...seamPromises, ...transPromises, ...basePromises, ...baseFromDetailsPromises]);
      loadingTracker.step();
      for (const [pieceId, data] of Object.entries(baseDetailFallbacks)) {
        if (!state.templateStyle.basePieces[pieceId]) state.templateStyle.basePieces[pieceId] = data;
      }

      for (const section of ["shirt", "short", "socks"]) {
        state.templateStyle.details[section].sort(templateLayerSort);
        for (const layer of state.templateStyle.details[section]) {
          state.templateDetailOpen[section][layer.folder] = false;
          const patternSubfolder = templatePatternSubfolderKey(layer);
          if (patternSubfolder) state.templateDetailOpen[section][templatePatternSubfolderStateKey(layer.folder || "Pattern", patternSubfolder)] = false;
        }
      }
      normalizeAllPatternBelowFabric();
      await Promise.all([
        validateTemplateGuideAssets(item, { force: true }),
        validateActiveTemplateGeneratedGuideAssets({ force: true }),
      ]);
      loadingTracker.step();

      renderTemplateDetailPanels();
      setStatus(`Template assets loaded: ${templateGalleryDisplayName(item)}`);

      // Default Collar 01 if available; otherwise first collar.
      // The loading screen stays on top, so the new template is shown only after the final clean render.
      const defaultCollar = defaultCollarForProgress;
      if (defaultCollar) {
        try {
          await selectCollarStyle(defaultCollar, true, loadingTracker);
        } catch (error) {
          console.warn("Default collar skipped:", error);
        }
      }
      schedulePreloadActiveTemplateCollars();

      // v1.0.91: cache the clean loaded template base before applying project/kit settings.
      // Future kits using this template can switch faster without reloading all template PNG assets.
      cacheProjectTemplateBaseRuntimeState(item);

      await new Promise((resolve) => {
        loadSavedTemplateSettings(() => {
          loadingTracker.step();
          buildTemplateCache();
          renderTemplateDetailPanels();
          renderTextureLayers();
          renderPieceColorPanels();
          hideWelcomeScreen();
          updateOverlayUi();
          render({ immediate: true });
          loadingTracker.step();
          setStatus(`Template loaded: ${templateGalleryDisplayName(item)}`);
          try {
            if (state.project?.activeKitId && !kitlabProjectDraftMode) ensureCurrentKitSaved({ capturePreview: false });
            else renderProjectKitPanel();
          } catch (_) {}
          loadingTracker.finish();
          resolve();
        });
      });
    } catch (error) {
      loadingTracker.fail();
      console.error(error);
      setStatus(`Template load failed: ${item?.name || "Template"}`);
      throw error;
    }
  }

  function collarAssetFallbackCandidates(meta = {}, collarItem = null) {
    const seen = new Set();
    const out = [];
    const add = (value) => {
      const raw = String(value || "").trim();
      if (!raw || seen.has(raw)) return;
      seen.add(raw);
      out.push(raw);
    };
    add(meta.path || meta.src);
    try { add(decodeURI(String(meta.path || meta.src || ""))); } catch (_) {}
    try { add(encodeURI(String(meta.path || meta.src || ""))); } catch (_) {}

    const selected = state.templateStyle?.selected || {};
    const root = String(selected.path || "").replace(/\/+$/, "");
    const collarId = String(collarItem?.id || collarItem?.folder || collarItem?.name || "").trim();
    const originalPath = String(meta.originalPath || "").replace(/^\/+/, "");
    const rawName = String(meta.rawName || "").trim();
    const fileFromPath = String(meta.path || meta.src || "").split(/[\/]/).pop() || "";
    const decodedFile = (() => { try { return decodeURIComponent(fileFromPath); } catch (_) { return fileFromPath; } })();
    const names = [rawName, decodedFile].filter(Boolean);

    if (root && originalPath) {
      add(`${root}/${encodeURI(originalPath).replace(/%2F/g, "/")}`);
      add(`${root}/${originalPath}`);
    }
    if (root && collarId) {
      for (const name of names) {
        add(`${root}/collar/${encodeURIComponent(collarId).replace(/%2F/g, "/")}/${encodeURIComponent(name).replace(/%2F/g, "/")}`);
        add(`${root}/collar/${collarId}/${name}`);
      }
    }
    return out;
  }

  // v1.1.31: collar loading speed test.
  // Keep the collar render exact, but avoid decoding/downloading the same PNGs every time.
  const collarImageLoadCache = new Map();
  let collarPreloadToken = 0;

  function collarImageCacheKey(src) {
    return String(src || "").trim();
  }

  function loadCollarImagePromiseCached(src) {
    const key = collarImageCacheKey(src);
    if (!key) return Promise.resolve(null);
    if (collarImageLoadCache.has(key)) return collarImageLoadCache.get(key);
    const promise = loadImagePromise(key).catch(() => null);
    collarImageLoadCache.set(key, promise);
    return promise;
  }

  async function loadCollarImageWithFallback(meta = {}, collarItem = null, options = {}) {
    const candidates = collarAssetFallbackCandidates(meta, collarItem);
    if (!candidates.length) return null;

    // Fast path: if any candidate was already cached and valid, reuse it immediately.
    for (const src of candidates) {
      const key = collarImageCacheKey(src);
      const cached = key ? collarImageLoadCache.get(key) : null;
      if (!cached) continue;
      const loaded = await cached;
      if (loaded && loaded.image) return loaded;
    }

    // Start all fallback candidates together. This avoids waiting 2.5s on a stale/missing
    // path when another valid candidate is available immediately.
    const loaded = await new Promise((resolve) => {
      let pending = candidates.length;
      let done = false;
      const finish = (value) => {
        if (done) return;
        if (value && value.image) {
          done = true;
          resolve(value);
          return;
        }
        pending -= 1;
        if (pending <= 0) {
          done = true;
          resolve(null);
        }
      };
      for (const src of candidates) loadCollarImagePromiseCached(src).then(finish).catch(() => finish(null));
    });

    if (!loaded && !options.silent) console.warn("Collar asset skipped after fallbacks:", meta.path || meta.src || meta.name);
    return loaded;
  }

  function collarItemAssetMetas(item = {}) {
    return [
      ...(Array.isArray(item.details) ? item.details : []),
      ...(Array.isArray(item.seams) ? item.seams : []),
      ...(Array.isArray(item.transparency) ? item.transparency : []),
    ];
  }

  // v1.1.32: smart collar preloading.
  // Do not preload 50+ full collars at once. Warm the first visible/hovered collars first,
  // one or two image loads at a time, so first user selection feels fast without saturating Chrome.
  function schedulePreloadCollarItems(collars = [], options = {}) {
    if (!Array.isArray(collars) || !collars.length) return;
    const token = options.reuseToken === true ? collarPreloadToken : ++collarPreloadToken;
    const maxCollars = Number.isFinite(Number(options.limit)) ? Math.max(1, Number(options.limit)) : 8;
    const maxActive = Number.isFinite(Number(options.maxActive)) ? Math.max(1, Number(options.maxActive)) : 1;
    const delayMs = Number.isFinite(Number(options.delayMs)) ? Math.max(0, Number(options.delayMs)) : 30;
    const selectedKey = collarConfigurationKey(state.templateStyle?.selectedCollar);

    const unique = [];
    const seen = new Set();
    for (const collar of collars) {
      if (!collar || collar.isCollarCategory) continue;
      const key = collarConfigurationKey(collar) || String(collar.id || collar.name || unique.length);
      if (seen.has(key)) continue;
      seen.add(key);
      unique.push(collar);
    }
    unique.sort((a, b) => {
      const ak = collarConfigurationKey(a);
      const bk = collarConfigurationKey(b);
      if (ak === selectedKey) return -1;
      if (bk === selectedKey) return 1;
      return 0;
    });

    const tasks = [];
    for (const collar of unique.slice(0, maxCollars)) {
      for (const meta of collarItemAssetMetas(collar)) tasks.push([meta, collar]);
    }
    if (!tasks.length) return;

    let index = 0;
    let active = 0;
    const pump = () => {
      if (token !== collarPreloadToken) return;
      while (active < maxActive && index < tasks.length) {
        const [meta, collar] = tasks[index++];
        active += 1;
        loadCollarImageWithFallback(meta, collar, { silent: true })
          .catch(() => null)
          .finally(() => {
            active -= 1;
            if (index < tasks.length) setTimeout(pump, delayMs);
          });
      }
    };

    const start = () => pump();
    if (options.immediate === true) start();
    else if (typeof requestIdleCallback === "function") requestIdleCallback(start, { timeout: Number(options.idleTimeout || 250) });
    else setTimeout(start, Number(options.startDelay || 80));
  }

  function schedulePreloadActiveTemplateCollars(options = {}) {
    const selected = state.templateStyle?.selected;
    if (!selected) return;
    const collars = getActiveTemplateCollarOptions();
    // Template load: only warm a small starter group. Gallery/hover handles the rest.
    schedulePreloadCollarItems(collars, { limit: 6, maxActive: 1, delayMs: 45, idleTimeout: 300, ...options });
  }

  function schedulePreloadVisibleCollars(options = {}) {
    if (state.gallerySource !== "collar") return;
    const items = filteredInternalBrands().filter((item) => item && !item.isCollarCategory);
    schedulePreloadCollarItems(items, { limit: 10, maxActive: 2, delayMs: 20, immediate: true, ...options });
  }

  function preloadCollarItemNow(item) {
    if (!item || item.isCollarCategory) return;
    // Hover/soon-to-click: do not cancel the background queue, just put this collar in cache now.
    for (const meta of collarItemAssetMetas(item)) {
      loadCollarImageWithFallback(meta, item, { silent: true }).catch(() => null);
    }
  }

  async function selectCollarStyle(item, silent = false, loadingTracker = null, options = {}) {
    if (!item) return;
    const userSelect = options && options.userSelect === true;
    rememberCurrentCollarConfiguration();
    state.templateStyle.selectedCollar = item;
    state.templateStyle.collarLayers = [];
    state.templateStyle.collarSeams = [];
    state.templateStyle.collarTransparency = [];
    state.collarDetailsOpen = true;
    state.collarSeamsFolderOpen = false;
    state.templateDetailOpen.collar = {};
    const visibleCollarName = collarVisibleName(item);
    if (els.selectedCollarName) els.selectedCollarName.textContent = `Collar: ${visibleCollarName}`.trim();
    setStatus(`Loading collar: ${visibleCollarName}`);

    const detailPromises = (item.details || []).map(async (meta, index) => {
      try {
        const loaded = await loadCollarImageWithFallback(meta, item);
        if (!loaded || !loaded.image) return;
        const lockedOriginal = templateLayerIsLockedOriginalColor(meta);
        const forceBlendOpacity = templateLayerForcesBlendOpacity(meta);
        const hasBlend = forceBlendOpacity || meta.blend === true || templateLayerHasBlendDirective(meta);
        const hasOpacity = forceBlendOpacity || meta.opacityCtl === true || templateLayerHasOpacityDirective(meta);
        const collarPanelFolder = collarLayerPanelFolder(meta, item);
        state.templateStyle.collarLayers.push({
          ...meta,
          id: uid(),
          section: "collar",
          folder: collarPanelFolder.folder,
          _collarPanelFolder: collarPanelFolder.folder,
          _collarNestedFolder: collarPanelFolder.nested === true,
          _collarMainFolder: collarPanelFolder.mainFolder,
          index,
          blend: hasBlend,
          opacityCtl: hasOpacity,
          noColor: meta.noColor === true || lockedOriginal,
          enabled: true,
          image: loaded.image,
          src: loaded.src,
          loaded: true,
          palette: (meta.noColor === true || lockedOriginal) ? [] : (templateLayerIsColorableCollar(meta) ? [KITLAB_CANONICAL_DEFAULT_COLOR] : safeDetectOnePredominantColor(loaded.image)),
          colorMap: {},
          opacity: Number(meta.opacity ?? 1),
          blendMode: hasBlend ? "overlay" : (meta.blendMode || "source-over"),
        });
        const added = state.templateStyle.collarLayers[state.templateStyle.collarLayers.length - 1];
        if (added) {
          if (templateLayerIsColorableCollar(added)) {
            added._detectedColor = KITLAB_CANONICAL_DEFAULT_COLOR;
            added.sourceColor = KITLAB_CANONICAL_DEFAULT_COLOR;
            added.palette = [KITLAB_CANONICAL_DEFAULT_COLOR];
          }
          added.colorMap = templateInitialColorMap(added.palette, added);
          if (templateLayerIsColorableCollar(added)) added._templateChipColor = normalizeHexColor(added.colorMap[KITLAB_CANONICAL_DEFAULT_COLOR] || KITLAB_CANONICAL_DEFAULT_COLOR);
          enforceRetroFixedBlackShadowLayer(added);
        }
      } finally {
        if (loadingTracker) loadingTracker.step();
      }
    });

    const seamPromises = (item.seams || []).map(async (meta, index) => {
      try {
        const loaded = await loadCollarImageWithFallback(meta, item);
        if (!loaded || !loaded.image) return;
        const seamText = `${meta?.name || ""} ${meta?.path || ""}`;
        const isCollarSeamLayer = /collar[_\s\-.]*seams/i.test(seamText) || meta.manualLab === true;
        const seamLayer = {
          ...meta,
          id: meta.id || uid(),
          section: "collar_seams",
          folder: "SEAMS",
          image: loaded.image,
          src: loaded.src,
          enabled: true,
          loaded: true,
          manualLab: isCollarSeamLayer,
          iv: meta.iv === true || /(^|[\s_\-.])iv([\s_\-.]|$)/i.test(seamText),
          fj: meta.fj === true || /(^|[\s_\-.])fj([\s_\-.]|$)/i.test(seamText),
          order: Number.isFinite(Number(meta.order)) ? Number(meta.order) : index,
        };
        if (seamLayer.manualLab) {
          seamLayer.blendMode = seamLayer.blendMode || "overlay";
          seamLayer.opacity = Number.isFinite(Number(seamLayer.opacity)) ? Number(seamLayer.opacity) : manualSeamDefaultOpacity(seamLayer);
          seamLayer.inverted = seamLayer.inverted === true;
        }
        state.templateStyle.collarSeams.push(seamLayer);
      } finally {
        if (loadingTracker) loadingTracker.step();
      }
    });

    const transPromises = (item.transparency || []).map(async (meta) => {
      try {
        const loaded = await loadCollarImageWithFallback(meta, item);
        if (!loaded || !loaded.image) return;
        state.templateStyle.collarTransparency.push({ ...meta, image: loaded.image, src: loaded.src, enabled: true });
      } finally {
        if (loadingTracker) loadingTracker.step();
      }
    });

    await Promise.all([...detailPromises, ...seamPromises, ...transPromises]);

    state.templateStyle.collarLayers.sort(templateLayerSort);
    const loadedCollarLayerCount = (state.templateStyle.collarLayers || []).length + (state.templateStyle.collarSeams || []).length + (state.templateStyle.collarTransparency || []).length;
    await importCollarSpecificSettingsForFastVisual(item);
    applyCurrentCollarConfiguration();
    if (userSelect && loadedCollarLayerCount > 0) {
      // Direct gallery selection must always visibly load the chosen collar.
      // If an old saved configuration disabled every matching layer, recover the default visible state.
      const anyVisible = (state.templateStyle.collarLayers || []).some((layer) => layer.enabled !== false) ||
        (state.templateStyle.collarSeams || []).some((layer) => layer.enabled !== false);
      if (!anyVisible) {
        for (const layer of state.templateStyle.collarLayers || []) layer.enabled = true;
        for (const layer of state.templateStyle.collarSeams || []) layer.enabled = true;
      }
    }
    if (els.selectedCollarName) els.selectedCollarName.textContent = `Collar: ${visibleCollarName}`.trim();
    // Collar changes do not affect the body/base cache. Rebuilding the whole 2048 body cache
    // here made first collar selection feel much slower, especially with large collar libraries.
    render({ immediate: true });
    renderTemplateDetailPanels();
    try {
      if (state.project?.activeKitId) {
        ensureCurrentKitSaved({ capturePreview: false, renderPanel: false });
        cacheProjectKitRuntimeState(state.project);
        renderProjectKitPanel();
      }
    } catch (_) {}
    setStatus(loadedCollarLayerCount > 0 ? `Collar loaded: ${visibleCollarName}` : `Collar selected but no assets loaded: ${visibleCollarName}`);
  }


  function templateLayerImageAnalysis(layer) {
    if (!layer?.image) return { bbox: null, nearlyFlat: false };
    const key = imageAssetCacheKey(layer.image);
    const cached = templateLayerImageAnalysisCache.get(layer.image);
    if (cached && cached.key === key) return cached;
    const img = imageToImageData(layer.image);
    const data = img.data;
    const bbox = alphaBBoxFromData(data, 1);
    let baseR = -1, baseG = -1, baseB = -1, seen = 0, nearlyFlat = true;
    const tolerance = 3;
    if (bbox) {
      for (let y = bbox.y0; y <= bbox.y1 && nearlyFlat; y += 1) {
        const row = y * CANVAS_SIZE;
        for (let x = bbox.x0; x <= bbox.x1; x += 1) {
          const i = (row + x) * 4;
          const alpha = data[i + 3];
          if (alpha < 8) continue;
          const r = data[i], g = data[i + 1], b = data[i + 2];
          if (baseR < 0) { baseR = r; baseG = g; baseB = b; seen = 1; continue; }
          seen += 1;
          if (Math.abs(r - baseR) > tolerance || Math.abs(g - baseG) > tolerance || Math.abs(b - baseB) > tolerance) {
            nearlyFlat = false;
            break;
          }
        }
      }
    } else {
      nearlyFlat = false;
    }
    const analysis = { key, bbox, nearlyFlat: nearlyFlat && seen > 0 };
    templateLayerImageAnalysisCache.set(layer.image, analysis);
    return analysis;
  }

  function applyPaletteColorMapInBounds(octx, canvas, layer, bbox = null) {
    const colorMap = layer.colorMap || {};
    const replacements = Object.entries(colorMap)
      .map(([source, target]) => ({ source: normalizeHexColor(source), target: normalizeHexColor(target) }))
      .filter((item) => item.source !== item.target);
    if (!replacements.length || !layer.palette.length) return;
    const palette = layer.palette.map((color) => {
      const source = normalizeHexColor(color);
      return { source, rgb: hexToRgb(source) };
    });
    const replacementBySource = Object.fromEntries(replacements.map((item) => [item.source, hexToRgb(item.target)]));
    const x = bbox ? bbox.x0 : 0;
    const y = bbox ? bbox.y0 : 0;
    const w = bbox ? bbox.w : canvas.width;
    const h = bbox ? bbox.h : canvas.height;
    const data = octx.getImageData(x, y, w, h);
    const maxDistanceSq = 72 * 72;
    for (let i = 0; i < data.data.length; i += 4) {
      const alpha = data.data[i + 3];
      if (alpha < 20) continue;
      const pixel = { r: data.data[i], g: data.data[i + 1], b: data.data[i + 2] };
      let nearest = null;
      let nearestDist = Infinity;
      for (const item of palette) {
        const dist = colorDistanceSq(pixel, item.rgb);
        if (dist < nearestDist) { nearestDist = dist; nearest = item; }
      }
      if (!nearest || nearestDist > maxDistanceSq) continue;
      const target = replacementBySource[nearest.source];
      if (!target) continue;
      data.data[i] = target.r;
      data.data[i + 1] = target.g;
      data.data[i + 2] = target.b;
    }
    octx.putImageData(data, x, y);
  }

  function recolorTemplatePieceCanvasInBounds(pieceCanvas, sourceHex, targetHex, bbox = null, options = {}) {
    const source = hexToRgb(normalizeHexColor(sourceHex));
    const target = hexToRgb(normalizeHexColor(targetHex));
    const pctx = pieceCanvas.getContext("2d", { willReadFrequently: true });
    const x = bbox ? bbox.x0 : 0;
    const y = bbox ? bbox.y0 : 0;
    const w = bbox ? bbox.w : pieceCanvas.width;
    const h = bbox ? bbox.h : pieceCanvas.height;
    let imageData;
    try { imageData = pctx.getImageData(x, y, w, h); }
    catch (_) { return recolorTemplatePieceCanvas(pieceCanvas, sourceHex, targetHex, options); }
    const data = imageData.data;
    const sourceLumFromHex = 0.2126 * source.r + 0.7152 * source.g + 0.0722 * source.b;
    const sourceLum = sourceLumFromHex;
    for (let i = 0; i < data.length; i += 4) {
      const alpha = data[i + 3];
      if (alpha < 8) continue;
      const lum = 0.2126 * data[i] + 0.7152 * data[i + 1] + 0.0722 * data[i + 2];
      const delta = lum - sourceLum;
      data[i] = clamp(target.r + delta, 0, 255);
      data[i + 1] = clamp(target.g + delta, 0, 255);
      data[i + 2] = clamp(target.b + delta, 0, 255);
    }
    pctx.putImageData(imageData, x, y);
    return pieceCanvas;
  }

  function templateLayerIsColorableTemplateDetail(layer = {}) {
    if (!layer || layer.noColor || templateLayerIsLockedOriginalColor(layer) || templateLayerIsTights(layer)) return false;
    // Only clean normal color-detail PNGs. Technical fusion/opacity layers keep their original soft alpha.
    if ((layer.blendMode || "source-over") !== "source-over") return false;
    return true;
  }

  function cleanupTemplateColorDetailAlpha(canvas, layer, bbox = null) {
    if (!canvas || !templateLayerIsColorableTemplateDetail(layer)) return canvas;
    const folder = String(layer?.folder || "").replace(/[_-]+/g, " ").trim().toLowerCase();
    const original = safeDecodeKitlabPath(layer?.originalPath || layer?.path || layer?.src || "").replace(/\\/g, "/").toLowerCase();
    const isTemplatePattern = folder === "pattern" || /(^|\/)pattern(\/|$)/i.test(original);
    // Photoshop often exports almost-invisible alpha dust around color overlay details.
    // When KitLab recolors those pixels, they become visible as dirty halos/marks.
    // Pattern-folder template details get a slightly stronger cutoff; normal details keep softer edges.
    const alphaCutoff = isTemplatePattern ? 18 : 7;
    const cctx = canvas.getContext("2d", { willReadFrequently: true });
    const x = bbox ? bbox.x0 : 0;
    const y = bbox ? bbox.y0 : 0;
    const w = bbox ? bbox.w : canvas.width;
    const h = bbox ? bbox.h : canvas.height;
    if (!w || !h) return canvas;
    let imageData;
    try { imageData = cctx.getImageData(x, y, w, h); }
    catch (_) { return canvas; }
    const data = imageData.data;
    let changed = false;
    for (let i = 0; i < data.length; i += 4) {
      const a = data[i + 3];
      if (a > 0 && a < alphaCutoff) {
        data[i + 3] = 0;
        changed = true;
      }
    }
    if (changed) cctx.putImageData(imageData, x, y);
    return canvas;
  }

  function templateLayerColorApply(layer) {
    layer.colorMap = sanitizeTemplateColorMap(layer);
    const key = JSON.stringify(layer.colorMap || {});
    if (layer._renderCache && layer._renderCacheKey === key) return layer._renderCache;

    const off = document.createElement("canvas");
    off.width = layer.image.naturalWidth || layer.image.width;
    off.height = layer.image.naturalHeight || layer.image.height;
    const octx = off.getContext("2d", { willReadFrequently: true });
    octx.drawImage(layer.image, 0, 0);
    try {
      const analysis = templateLayerImageAnalysis(layer);
      const palette = Array.isArray(layer.palette) ? layer.palette.map(normalizeHexColor) : [];
      const source = palette[0];
      const target = source ? normalizeKitDefaultColor(layer.colorMap?.[source] || source) : null;
      if (templateLayerIsColorableCollar(layer) && target) {
        // Collar base color is a true flat chosen color. Texture/wrinkles are
        // rendered above it, so do not let PNG source #181818 become the UI/state color.
        recolorTemplatePieceCanvasFlat(off, target);
      } else {
        const isSingleSourceColorable = source && target && palette.length === 1 && !layer.noColor;
        const isFlatSingleColorLayer = isSingleSourceColorable && analysis.nearlyFlat === true;
        const canNeutralRecolor = isSingleSourceColorable && (layer.blendMode || "source-over") === "source-over";
        if (isFlatSingleColorLayer) {
          // Flat template details such as Umbro triangle/cuff pieces must follow the
          // selected UI color exactly. Preserving luminance is useful for textured PNGs,
          // but a one-color PNG should not keep hidden blue/red source tint.
          recolorTemplatePieceCanvasFlat(off, target);
        } else if (canNeutralRecolor) recolorTemplatePieceCanvasInBounds(off, source, target, analysis.bbox);
        else applyPaletteColorMapInBounds(octx, off, layer, analysis.bbox);
      }
    } catch (e) { /* keep original */ }
    try { cleanupTemplateColorDetailAlpha(off, layer, templateLayerImageAnalysis(layer).bbox); } catch (_) {}

    layer._renderCache = off;
    layer._renderCacheKey = key;
    return off;
  }

  function ensureGuidedPatternLayerGuidesLoaded(layer) {
    if (!layer || !templateLayerUsesGuidedPatternEngine(layer)) return;
    if (Array.isArray(layer.patternGuides) && layer.patternGuides.length) return;
    if (layer._patternGuidesLoading === true) return;
    layer._patternGuidesLoading = true;
    Promise.resolve(loadPatternGuidesForLayer(layer))
      .then(() => {
        layer._patternGuidesLoading = false;
        normalizeAllPatternBelowFabric();
        try { renderTemplateDetailPanels(); } catch (_) {}
        try { render(); } catch (_) {}
      })
      .catch((error) => {
        layer._patternGuidesLoading = false;
        console.warn("Guided Base Design/Pattern guides could not be loaded:", error);
      });
  }

  function drawOneTemplateLayer(layer) {
    enforceButtonShineWhiteLayer(layer);
    enforceRetroFixedBlackShadowLayer(layer);
    if (!layer?.enabled) return;
    if (isGeneratedStripeLayer(layer)) { drawGeneratedStripeLayer(layer, { clipToCurrentAlpha: true }); return; }
    if (templateLayerUsesGuidedPatternEngine(layer)) { markGuidedPatternLayerKind(layer); ensureGuidedPatternLayerGuidesLoaded(layer); drawUserPatternLayer(layer); return; }
    if (!layer.image) return;
    const canvas = templateLayerColorApply(layer);
    ctx.save();
    ctx.globalAlpha = clamp(Number(layer.opacity ?? 1), 0, 1);
    ctx.globalCompositeOperation = layer.blendMode || "source-over";
    ctx.drawImage(canvas, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
    ctx.restore();
  }

  function templateSectionUiOrderedLayers(section) {
    // v1.0.15: render exactly in the same order as the UI list.
    // The template manifest defines the initial Photoshop stack; manual arrows can move Pattern as a folder.
    return (state.templateStyle.details?.[section] || []).filter(templateLayerMatchesActiveShortVariant);
  }

  function drawTemplateStyleBodyDetails() {
    // Same Photoshop rule as the UI: first visible row/folder is on top.
    // Paint bottom-to-top, so Aero Fit/bottom folders are painted first, and Tights/Brand above Details stay above them in render.
    drawTemplateStyleBodySectionDetails("socks");
    drawTemplateStyleBodySectionDetails("short");
    drawTemplateStyleBodySectionDetails("shirt");
  }

  function drawTemplateStyleCollarDetails() {
    // Collar is a real Photoshop group over the shirt body seams. No shirt seam may paint over it.
    for (const layer of [...state.templateStyle.collarLayers].reverse()) drawOneTemplateLayer(layer);
  }

  function drawTemplateStyleDetails() {
    drawTemplateStyleBodyDetails();
    drawTemplateStyleCollarDetails();
  }

  function buildAdaptiveExternalIvCanvas(ivSeams) {
    const out = makeCanvas();
    const ox = out.getContext("2d", { willReadFrequently: true });
    const baseData = ctx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE).data;

    for (const seam of ivSeams) {
      if (!seam.enabled || !seam.image) continue;

      const analysis = seamSourceAnalysis(seam.image);
      if (!analysis) continue;
      const src = cloneImageDataFromAnalysis(analysis);
      const data = src.data;
      const components = analysis.components;
      const isIvuUnion = isIvuUnionSeamMeta(seam);

      if (isIvuUnion) {
        const adjacentDecision = ivuUnionAdjacentSideDecision(analysis, baseData, null);
        const sideDecision = adjacentDecision !== null ? adjacentDecision : ivuUnionSideDecision(analysis, baseData, null);
        const unionDecision = sideDecision !== null ? sideDecision : ivuUnionVoteDecision(analysis, baseData, null);
        if (unionDecision !== null) {
          if (unionDecision === true) applyInvertToVisiblePixels(data, 0);
          const temp = makeCanvas();
          temp.getContext("2d").putImageData(src, 0, 0);
          ox.drawImage(temp, 0, 0);
          continue;
        }
      }

      for (const component of components) {
        let whiteSum = 0, whiteW = 0, blackSum = 0, blackW = 0;

        for (const p of component) {
          const i = p * 4;
          const alpha = data[i + 3];
          if (alpha < 12) continue;

          const srcLum = (data[i] + data[i + 1] + data[i + 2]) / 3;
          const baseA = baseData[i + 3];
          if (baseA < 8) continue;
          const baseLum = linearSrgbLuma255(baseData[i], baseData[i + 1], baseData[i + 2]);
          const w = alpha / 255;

          if (srcLum >= 150) {
            whiteSum += baseLum * w;
            whiteW += w;
          } else if (srcLum <= 105) {
            blackSum += baseLum * w;
            blackW += w;
          }
        }

        if (whiteW >= 0.01 && blackW >= 0.01) {
          const whiteAvg = whiteSum / whiteW;
          const blackAvg = blackSum / blackW;

          // IV formula: white side must follow lighter area, black side darker area.
          // Strict IV: any real light/dark difference flips; only exact numeric ties stay stable.
          if (ivAverageSaysInvert(whiteAvg, blackAvg)) {
            for (const p of component) invertRgbInData(data, p * 4);
          }
        }
      }

      const temp = makeCanvas();
      temp.getContext("2d").putImageData(src, 0, 0);
      ox.drawImage(temp, 0, 0);
    }

    return out;
  }


  function linearSrgbLuma255(r, g, b) {
    const toLinear = (v) => {
      const x = clamp((Number(v) || 0) / 255, 0, 1);
      return x <= 0.04045 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4);
    };
    const rr = toLinear(r);
    const gg = toLinear(g);
    const bb = toLinear(b);
    return 0.2126 * rr + 0.7152 * gg + 0.0722 * bb;
  }

  function alphaBBoxFromData(data, alphaThreshold = 1) {
    let x0 = CANVAS_SIZE, y0 = CANVAS_SIZE, x1 = -1, y1 = -1;
    for (let y = 0; y < CANVAS_SIZE; y += 1) {
      const row = y * CANVAS_SIZE;
      for (let x = 0; x < CANVAS_SIZE; x += 1) {
        const a = data[(row + x) * 4 + 3];
        if (a <= alphaThreshold) continue;
        if (x < x0) x0 = x;
        if (x > x1) x1 = x;
        if (y < y0) y0 = y;
        if (y > y1) y1 = y;
      }
    }
    if (x1 < x0 || y1 < y0) return null;
    return { x0, y0, x1, y1, w: x1 - x0 + 1, h: y1 - y0 + 1 };
  }

  function smoothBooleanRows(rows, strengths, minRun) {
    const n = rows.length;
    const out = rows.slice();
    const strong = [];
    for (let i = 0; i < n; i += 1) {
      if (out[i] === 0 || out[i] === 1) strong.push(i);
    }
    if (!strong.length) return null;

    for (let i = 0; i < n; i += 1) {
      if (out[i] === 0 || out[i] === 1) continue;
      let best = strong[0];
      let bestD = Math.abs(i - best);
      for (let j = 1; j < strong.length; j += 1) {
        const d = Math.abs(i - strong[j]);
        if (d < bestD) { best = strong[j]; bestD = d; }
      }
      out[i] = out[best];
    }

    // Remove tiny accidental one-row/two-row flips. Collar IV should change in broad bands,
    // not in isolated pixels/rows, otherwise it creates exactly the dotted/noisy look.
    const minLen = Math.max(3, Math.floor(Number(minRun) || 8));
    let start = 0;
    while (start < n) {
      let end = start + 1;
      while (end < n && out[end] === out[start]) end += 1;
      const len = end - start;
      if (len < minLen) {
        const prev = start > 0 ? out[start - 1] : null;
        const next = end < n ? out[end] : null;
        let replacement = prev;
        if (prev == null) replacement = next;
        else if (next != null && strengths[end] > strengths[Math.max(0, start - 1)]) replacement = next;
        if (replacement != null) {
          for (let k = start; k < end; k += 1) out[k] = replacement;
        }
      }
      start = end;
    }
    return out;
  }

  function buildAdaptiveCollarIvCanvas(collarIvSeams) {
    const out = makeCanvas();
    const ox = out.getContext("2d", { willReadFrequently: true });
    const baseData = ctx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE).data;

    for (const seam of collarIvSeams) {
      if (!seam.enabled || !seam.image) continue;

      const analysis = seamSourceAnalysis(seam.image);
      if (!analysis) continue;
      const src = cloneImageDataFromAnalysis(analysis);
      const data = src.data;
      const bbox = analysis.bbox;
      if (!bbox) continue;

      const rowState = new Array(CANVAS_SIZE).fill(null);
      const rowStrength = new Array(CANVAS_SIZE).fill(0);
      const eps = IV_STRICT_LUMA_EPS;

      for (let y = bbox.y0; y <= bbox.y1; y += 1) {
        let whiteSum = 0, whiteW = 0, blackSum = 0, blackW = 0;
        const row = y * CANVAS_SIZE;
        for (let x = bbox.x0; x <= bbox.x1; x += 1) {
          const i = (row + x) * 4;
          const alpha = data[i + 3];
          if (alpha < 12) continue;
          const srcLum = (data[i] + data[i + 1] + data[i + 2]) / 3;
          if (srcLum > 122 && srcLum < 133) continue;
          const baseA = baseData[i + 3];
          if (baseA < 8) continue;
          const baseLum = linearSrgbLuma255(baseData[i], baseData[i + 1], baseData[i + 2]);
          const w = alpha / 255;
          if (srcLum >= 150) {
            whiteSum += baseLum * w;
            whiteW += w;
          } else if (srcLum <= 105) {
            blackSum += baseLum * w;
            blackW += w;
          }
        }

        if (whiteW >= 0.01 && blackW >= 0.01) {
          const whiteAvg = whiteSum / whiteW;
          const blackAvg = blackSum / blackW;
          const score = whiteAvg - blackAvg;
          rowStrength[y] = Math.abs(score) * Math.min(1, (whiteW + blackW) / 4);
          if (score < -eps) rowState[y] = 1;       // invert this collar band
          else if (score > eps) rowState[y] = 0;   // keep original orientation
        }
      }

      const minRun = Math.max(3, Math.min(36, Math.round(bbox.h / 18)));
      const smoothRows = smoothBooleanRows(rowState, rowStrength, minRun);

      if (!smoothRows) {
        // Safety fallback: if the collar analysis has no clear row information,
        // use the same per-component IV formula as normal body seams.
        const fallback = buildAdaptiveExternalIvCanvas([seam]);
        ox.drawImage(fallback, 0, 0);
        continue;
      }

      for (let y = bbox.y0; y <= bbox.y1; y += 1) {
        const invert = smoothRows[y] === 1;
        if (!invert) continue;
        const row = y * CANVAS_SIZE;
        for (let x = bbox.x0; x <= bbox.x1; x += 1) {
          const i = (row + x) * 4;
          if (data[i + 3] < 1) continue;
          invertRgbInData(data, i);
        }
      }

      const temp = makeCanvas();
      temp.getContext("2d").putImageData(src, 0, 0);
      ox.drawImage(temp, 0, 0);
    }

    return out;
  }

  function fuseSeamCanvasIntoGroup(groupCtx, seamCanvas) {
    // v0.9.48: costuras inside the same Photoshop folder must not cut each other
    // harshly when they cross. Source-over can overwrite an existing seam if the
    // upper seam has strong alpha. This fuses overlapping seam pixels by weighted
    // averaging before the full folder is applied once as Overlay/Superponer.
    if (!seamCanvas) return;
    const groupImage = groupCtx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE);
    const dst = groupImage.data;
    let src = seamCanvasPixelDataCache.get(seamCanvas);
    if (!src) {
      src = new Uint8ClampedArray(seamCanvas.getContext("2d", { willReadFrequently: true }).getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE).data);
      seamCanvasPixelDataCache.set(seamCanvas, src);
    }
    for (let i = 0; i < dst.length; i += 4) {
      const sa = src[i + 3] / 255;
      if (sa <= 0) continue;
      const da = dst[i + 3] / 255;
      if (da <= 0) {
        dst[i] = src[i]; dst[i + 1] = src[i + 1]; dst[i + 2] = src[i + 2]; dst[i + 3] = src[i + 3];
        continue;
      }
      const total = Math.max(0.0001, da + sa);
      dst[i] = Math.round((dst[i] * da + src[i] * sa) / total);
      dst[i + 1] = Math.round((dst[i + 1] * da + src[i + 1] * sa) / total);
      dst[i + 2] = Math.round((dst[i + 2] * da + src[i + 2] * sa) / total);
      dst[i + 3] = Math.round(Math.min(1, Math.max(da, sa, da + sa * 0.35)) * 255);
    }
    groupCtx.putImageData(groupImage, 0, 0);
  }

  function seamImageToCanvas(seam) {
    if (!seam?.enabled || !seam.image) return null;
    const key = imageAssetCacheKey(seam.image);
    if (seam._exactCanvas && seam._exactCanvasKey === key) return seam._exactCanvas;
    const c = makeCanvas();
    const cctx = c.getContext("2d");
    cctx.drawImage(seam.image, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
    seam._exactCanvas = c;
    seam._exactCanvasKey = key;
    return c;
  }


  function seamCanvasFromLayer(seam) {
    if (!seam?.enabled || !seam.image) return null;
    const key = `${imageAssetCacheKey(seam.image)}|inv:${seam.inverted === true ? 1 : 0}`;
    if (seam._manualCanvas && seam._manualCanvasKey === key) return seam._manualCanvas;
    const c = makeCanvas();
    const cctx = c.getContext("2d", { willReadFrequently: true });
    cctx.drawImage(seam.image, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
    if (seam.inverted === true) {
      const img = cctx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE);
      const data = img.data;
      for (let i = 0; i < data.length; i += 4) {
        if (data[i + 3] <= 0) continue;
        data[i] = 255 - data[i];
        data[i + 1] = 255 - data[i + 1];
        data[i + 2] = 255 - data[i + 2];
      }
      cctx.putImageData(img, 0, 0);
    }
    seam._manualCanvas = c;
    seam._manualCanvasKey = key;
    return c;
  }

  function drawManualSeamsLab(seams) {
    autoUpdateManualSeamInversions(seams);
    const ordered = [...seams].sort((a, b) => Number(a.order ?? 0) - Number(b.order ?? 0));
    for (const seam of ordered) {
      if (!seam.enabled || !seam.image) continue;
      const c = seamCanvasFromLayer(seam);
      if (!c) continue;
      ctx.save();
      ctx.globalCompositeOperation = seam.blendMode || "overlay";
      ctx.globalAlpha = clamp(Number(seam.opacity ?? 1), 0, 1);
      ctx.drawImage(c, 0, 0);
      ctx.restore();
    }
  }

  function seamFastPreviewCanvas(seam) {
    if (!seam?.image) return null;
    const key = `${seam.src || seam.path || seam.name || seam.id}|${seam.inverted ? 1 : 0}`;
    if (seam._fastPreviewCanvas && seam._fastPreviewKey === key) return seam._fastPreviewCanvas;
    if (seam.inverted !== true) {
      seam._fastPreviewCanvas = seam.image;
      seam._fastPreviewKey = key;
      return seam.image;
    }
    const c = makeCanvas();
    const cctx = c.getContext("2d", { willReadFrequently: true });
    cctx.drawImage(seam.image, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
    try {
      const img = cctx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE);
      const data = img.data;
      for (let i = 0; i < data.length; i += 4) {
        if (data[i + 3] <= 0) continue;
        data[i] = 255 - data[i];
        data[i + 1] = 255 - data[i + 1];
        data[i + 2] = 255 - data[i + 2];
      }
      cctx.putImageData(img, 0, 0);
    } catch (_) {}
    seam._fastPreviewCanvas = c;
    seam._fastPreviewKey = key;
    return c;
  }

  function drawExternalTemplateSeamsFast(options = {}) {
    const includeBody = options.body !== false;
    const includeCollar = options.collar !== false;
    const allSeams = [
      ...(includeBody ? activeTemplateBodySeams() : []),
      ...(includeCollar ? (state.templateStyle.collarSeams || []) : []),
    ];
    // IVU must be recalculated against the current kit colors even during previews.
    // Otherwise side-union seams look frozen while colors are being changed.
    if (allSeams.some((seam) => seam?.enabled !== false && isIvuUnionSeamMeta(seam))) {
      drawExternalTemplateSeams(options);
      return;
    }
    for (const seam of allSeams) {
      if (!seam?.enabled || !seam.image) continue;
      const image = seamFastPreviewCanvas(seam);
      if (!image) continue;
      ctx.save();
      ctx.globalCompositeOperation = seam.manualLab ? (seam.blendMode || "overlay") : "overlay";
      ctx.globalAlpha = seam.manualLab ? clamp(Number(seam.opacity ?? 1), 0, 1) : 1;
      ctx.drawImage(image, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
      ctx.restore();
    }
  }

  function drawExternalTemplateSeams(options = {}) {
    const includeBody = options.body !== false;
    const includeCollar = options.collar !== false;
    const bodySeams = includeBody ? activeTemplateBodySeams() : [];
    const collarSeams = includeCollar ? (state.templateStyle.collarSeams || []) : [];
    const allSeams = [...bodySeams, ...collarSeams];

    if (!allSeams.length) return;
    const labSeams = allSeams.filter((seam) => seam.manualLab === true);
    if (labSeams.length) {
      drawManualSeamsLab(labSeams);
      return;
    }

    // Photoshop formula:
    // Folder "Costuras" is set to Overlay/Superponer.
    // Every seam PNG inside the folder remains Normal at 100%.
    const seamGroup = makeCanvas();
    const sg = seamGroup.getContext("2d");

    const bodyFjSeams = bodySeams.filter((seam) => seam.fj || /fj/i.test(seam.name || seam.path || ""));
    const bodyIvSeams = bodySeams.filter((seam) => seam.iv || /iv/i.test(seam.name || seam.path || ""));
    const collarFjSeams = collarSeams.filter((seam) => seam.fj || /fj/i.test(seam.name || seam.path || ""));
    const collarIvSeams = collarSeams.filter((seam) => seam.iv || /iv/i.test(seam.name || seam.path || ""));
    const collarRawSeams = collarSeams.filter((seam) => !collarFjSeams.includes(seam) && !collarIvSeams.includes(seam));

    // BODY/TEMPLATE FJ: fixed, normal inside folder.
    for (const seam of bodyFjSeams) {
      if (!seam.enabled || !seam.image) continue;
      sg.globalCompositeOperation = "source-over";
      sg.globalAlpha = 1;
      fuseSeamCanvasIntoGroup(sg, seamImageToCanvas(seam));
    }

    // BODY/TEMPLATE IV: existing working adaptive inversion, then normal inside folder.
    if (bodyIvSeams.length) {
      const ivCanvas = buildAdaptiveExternalIvCanvas(bodyIvSeams);
      sg.globalCompositeOperation = "source-over";
      sg.globalAlpha = 1;
      fuseSeamCanvasIntoGroup(sg, ivCanvas);
    }

    // COLLAR FJ/raw: fixed, normal inside folder.
    for (const seam of [...collarFjSeams, ...collarRawSeams]) {
      if (!seam.enabled || !seam.image) continue;
      sg.globalCompositeOperation = "source-over";
      sg.globalAlpha = 1;
      fuseSeamCanvasIntoGroup(sg, seamImageToCanvas(seam));
    }

    // COLLAR IV: local row/band IV only for collar seams. This restores inversion
    // without touching the now-clean body seam/detail color fix.
    if (collarIvSeams.length) {
      const collarIvCanvas = buildAdaptiveCollarIvCanvas(collarIvSeams);
      sg.globalCompositeOperation = "source-over";
      sg.globalAlpha = 1;
      fuseSeamCanvasIntoGroup(sg, collarIvCanvas);
    }

    // Apply complete Costuras folder once as Overlay/Superponer 100%.
    ctx.save();
    ctx.globalCompositeOperation = "overlay";
    ctx.globalAlpha = 1;
    ctx.drawImage(seamGroup, 0, 0);
    ctx.restore();
  }


  function applyExternalTemplateTransparency(options = {}) {
    const includeBody = options.body !== false;
    const includeCollar = options.collar !== false;
    const transparencies = [
      ...(includeBody ? (state.templateStyle.transparency || []) : []),
      ...(includeCollar ? (state.templateStyle.collarTransparency || []) : []),
    ];
    for (const t of transparencies) {
      if (!t.enabled || !t.image) continue;
      ctx.save();
      ctx.globalCompositeOperation = "destination-out";
      ctx.drawImage(t.image, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
      ctx.restore();
    }
  }

  function layerFileBaseName(layer) {
    const raw = String(layer?.path || layer?.src || layer?.name || "").split(/[\/]/).pop() || String(layer?.name || "");
    try { return decodeURIComponent(raw); } catch { return raw; }
  }

  function cleanLayerVisibleName(name, path) {
    const generic = !name || /^layer(?:\s*\d+)?$/i.test(String(name).trim());
    const sourceName = generic ? layerFileBaseName({ path, name }) : name;
    let out = directiveDisplayName(sourceName)
      .replace(/\.[a-z0-9]+$/i, "")
      .replace(/\b(shirt|short|shorts|socks|sleeve|sleeves|long|collar|camiseta|pantalon|pantalón|manga|corta|larga)\b/gi, "")
      .replace(/\b(front|back|left|right|delantero|trasero|izquierdo|derecho)\b/gi, "")
      .replace(/\bpunos\b/gi, "cuffs")
      .replace(/\bpuños\b/gi, "cuffs")
      .replace(/\bpuno\b/gi, "cuff")
      .replace(/\bpuño\b/gi, "cuff")
      .replace(/\bdoblado\b/gi, "fold")
      .replace(/\bfranja\b/gi, "stripe")
      .replace(/\blineas\b/gi, "lines")
      .replace(/\blíneas\b/gi, "lines")
      .replace(/\brespiraderos\b/gi, "vents")
      .replace(/\bgoma\b/gi, "rubber")
      .replace(/\bmalla\b/gi, "mesh")
      .replace(/\btights?\b/gi, "mesh")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    out = cleanDisplayName(out);
    return out || "Detail";
  }

  function templateLayerVisibleLabel(layer) {
    const manual = String(layer?.displayName || "").replace(/\s+/g, " ").trim();
    if (manual) return manual;
    return cleanLayerVisibleName(layer?.name, layer?.path || layer?.src);
  }


  function isNikeTotal90SideTriangleShortLayer(layer = {}) {
    const selectedName = String(state.templateStyle?.selected?.name || "").toLowerCase();
    const selectedPath = safeDecodeKitlabPath(state.templateStyle?.selected?.path || "").toLowerCase();
    if (!selectedName.includes("nike total 90") && !selectedPath.includes("nike total 90")) return false;
    const text = [layer.path, layer.src, layer.originalPath, layer.rawName, layer.name, layer.displayName]
      .map((value) => safeDecodeKitlabPath(value || "").toLowerCase().replace(/[_-]+/g, " "))
      .join(" | ");
    return /(?:shirt|short)\s+side\s+triangle\s+(left|right)\.png/.test(text) || /(?:details|short)\/(?:shirt|short)\s+side\s+triangle\s+(left|right)\.png/.test(text);
  }

  function applyNikeTotal90ShortSideTriangleAsset(layer = {}) {
    if (!layer || !isNikeTotal90SideTriangleShortLayer(layer)) return false;
    const text = [layer.path, layer.src, layer.originalPath, layer.rawName, layer.name, layer.displayName]
      .map((value) => safeDecodeKitlabPath(value || "").toLowerCase().replace(/[_-]+/g, " "))
      .join(" | ");
    const side = /right/.test(text) ? "right" : "left";
    const cap = side === "right" ? "Right" : "Left";
    const file = `short side triangle ${side}.png`;
    const encoded = file.replace(/ /g, "%20");
    layer.path = `assets/templates/nike/nike%20total%2090%2025-26/short/${encoded}`;
    layer.src = layer.path;
    layer.originalPath = `short/${file}`;
    layer.rawName = file;
    layer.section = "short";
    layer.folder = "Details";
    layer.displayName = `Short Side Triangle ${cap}`;
    layer.name = layer.displayName;
    return true;
  }

  function normalizeNikeTotal90SideTriangleSections() {
    const details = state.templateStyle?.details;
    if (!details || !Array.isArray(details.shirt) || !Array.isArray(details.short)) return false;
    const moved = [];
    details.shirt = details.shirt.filter((layer) => {
      if (!isNikeTotal90SideTriangleShortLayer(layer)) return true;
      applyNikeTotal90ShortSideTriangleAsset(layer);
      moved.push(layer);
      return false;
    });
    if (!moved.length) {
      for (const layer of details.short) {
        if (!isNikeTotal90SideTriangleShortLayer(layer)) continue;
        applyNikeTotal90ShortSideTriangleAsset(layer);
      }
      return false;
    }
    const seen = new Set(details.short.map((layer) => normalizeLayerSettingsMatchKey(layer.originalPath || layer.path || layer.rawName || layer.id || layer.name)));
    for (const layer of moved) {
      const key = normalizeLayerSettingsMatchKey(layer.originalPath || layer.path || layer.rawName || layer.id || layer.name);
      if (!key || !seen.has(key)) {
        details.short.push(layer);
        if (key) seen.add(key);
      }
    }
    details.short.sort(templateLayerSort);
    return true;
  }

  function cleanFolderVisibleName(folder) {
    return cleanDisplayName(String(folder || "").replace(/\btights?\b/gi, "mesh")
      .replace(/^overlay[_\-\s]*/i, "")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim()) || "Details";
  }

  function isTechnicalFolderName(folder, section = "") {
    const f = String(folder || "").toLowerCase().replace(/[_-]+/g, " ").trim();
    if (!f || /^detalles?$|^details?$/i.test(f) || f === "collar") return false;
    return f === "tights" || f === "mesh" || f === "brand" || f === "pattern" || f === "base design" || f === "base desing" || f === "fabric" || f === "extra" || f.includes("aero fit") || f.includes("overlay") || f.includes("climacool");
  }


  function safeDecodeKitlabPath(value = "") {
    const text = String(value || "").replace(/\\/g, "/");
    try { return decodeURIComponent(text); }
    catch (_) { return text; }
  }

  function collarMainPanelFolder(item = {}) {
    const visible = collarVisibleName(item);
    const category = item?.category ? cleanFolderVisibleName(item.category) : "";
    const label = [category, visible].filter(Boolean).join(" ").replace(/\s+/g, " ").trim();
    return label || item?.name || "Collar";
  }

  function collarLayerPanelFolder(meta = {}, collarItem = {}) {
    const mainFolder = collarMainPanelFolder(collarItem);
    const original = safeDecodeKitlabPath(meta.originalPath || meta.sourceName || meta.directiveSource || meta.path || meta.rawName || "").replace(/\\/g, "/");
    // Folder law: if an asset is physically inside a subfolder of the selected collar
    // folder, it must appear in that same subfolder in the web. Example:
    // collar/3_NO/button/button.png => folder "Button", not mixed with Collar 3_NO.
    const candidates = [collarItem.folder, collarItem.id, collarItem.name]
      .map((value) => safeDecodeKitlabPath(value || "").replace(/\\/g, "/").replace(/^\/+|\/+$/g, ""))
      .filter(Boolean);
    let after = "";
    const lowerOriginal = original.toLowerCase();
    for (const candidate of candidates) {
      const prefix = `collar/${candidate}/`.toLowerCase();
      const prefixIndex = lowerOriginal.indexOf(prefix);
      if (prefixIndex >= 0) {
        after = original.slice(prefixIndex + prefix.length);
        break;
      }
      const nestedPrefix = `/collar/${candidate}/`.toLowerCase();
      const nestedIndex = lowerOriginal.indexOf(nestedPrefix);
      if (nestedIndex >= 0) {
        after = original.slice(nestedIndex + nestedPrefix.length);
        break;
      }
    }
    if (!after) {
      const match = original.match(/(?:^|\/)collar\/[^\/]+\/(.+)$/i);
      if (match) after = match[1] || "";
    }
    const parts = after.split("/").filter(Boolean);
    if (parts.length > 1) {
      const folderName = cleanFolderVisibleName(parts[0]) || parts[0] || mainFolder;
      return { folder: folderName, nested: true, mainFolder };
    }
    return { folder: mainFolder, nested: false, mainFolder };
  }

  function baseDesignUsesNativeFullCanvas(layer = {}) {
    if (layer?.isUserBaseDesign !== true) return false;
    const image = layer.image || null;
    const w = Number(image?.naturalWidth || image?.width || 0);
    const h = Number(image?.naturalHeight || image?.height || 0);
    // Base Design files can be full 2048 template maps, unlike Pattern stamps.
    // Those must keep their native canvas position and be cropped by guides, never moved to a guide bbox origin.
    return w >= Math.round(CANVAS_SIZE * 0.75) && h >= Math.round(CANVAS_SIZE * 0.75);
  }

  function normalizePatternZones(layer = {}) {
    if (!layer.patternZones || typeof layer.patternZones !== "object") layer.patternZones = {};
    const section = normalizePatternTargetSection(layer?.section || "shirt");
    if (section === "short") {
      layer.patternZones.short = true;
      return layer.patternZones;
    }
    const fullCanvasBaseDesign = baseDesignUsesNativeFullCanvas(layer);
    if (typeof layer.patternZones.shirtFront !== "boolean") layer.patternZones.shirtFront = true;
    if (typeof layer.patternZones.shirtBack !== "boolean") layer.patternZones.shirtBack = fullCanvasBaseDesign ? true : false;
    if (typeof layer.patternZones.sleeveShort !== "boolean") layer.patternZones.sleeveShort = fullCanvasBaseDesign ? true : false;
    return layer.patternZones;
  }

  function patternZoneEnabled(layer, zone) {
    const zones = normalizePatternZones(layer);
    return zones[zone] !== false;
  }

  function patternZoneDropdownHtml(layer) {
    if (!layer?.patternMenuOpen) return "";
    if (normalizePatternTargetSection(layer?.section || "shirt") !== "shirt") return "";
    const zones = normalizePatternZones(layer);
    const rows = [
      ["shirtFront", "Shirt Front"],
      ["shirtBack", "Shirt Back"],
      ["sleeveShort", "Sleeve Short"],
    ].map(([key, label]) => `<label class="pattern-zone-row"><span>${label}</span><button type="button" class="pattern-zone-switch${zones[key] !== false ? " is-on" : ""}" data-pattern-zone-toggle="${escapeAttr(layer.id)}|${key}" aria-pressed="${zones[key] !== false ? "true" : "false"}"><span></span></button></label>`).join("");
    return `<div class="pattern-zone-dropdown" data-pattern-zone-menu="${escapeAttr(layer.id)}">${rows}</div>`;
  }

  function userPatternLayerRowHtml(layer) {
    normalizePatternZones(layer);
    const name = escapeHtml(templateLayerVisibleLabel(layer));
    const kindLabel = layer?.isUserBaseDesign === true ? "Base Design" : (normalizePatternTargetSection(layer?.section || "shirt") === "short" ? "Short Pattern" : "Pattern");
    const enabled = layer.enabled !== false;
    const paletteHtml = templatePaletteHtml(layer);
    const noSwatchClass = paletteHtml ? "" : " no-swatch";
    const isShirtPattern = normalizePatternTargetSection(layer?.section || "shirt") === "shirt";
    const zoneOpenAttr = isShirtPattern ? ` data-pattern-zone-open="${layer.id}"` : "";
    const nameTitle = isShirtPattern ? `Click to show ${kindLabel} zones. Double click to rename.` : `Double click to rename ${kindLabel}.`;
    const safeId = escapeAttr(layer.id);
    const actionBtnStyle = "display:inline-flex!important;align-items:center!important;justify-content:center!important;width:14px!important;min-width:14px!important;height:14px!important;min-height:14px!important;padding:0!important;margin:0!important;line-height:1!important;flex:0 0 14px!important;opacity:1!important;visibility:visible!important;overflow:visible!important;";
    const deleteBtnStyle = `${actionBtnStyle}border:0!important;background:transparent!important;color:#ff3b3b!important;font-size:13px!important;font-weight:900!important;font-family:Arial,sans-serif!important;text-shadow:0 0 2px rgba(0,0,0,.8)!important;`;
    const rowStyle = "display:grid!important;grid-template-columns:16px 20px minmax(0,1fr) 14px 14px 14px!important;align-items:center!important;column-gap:6px!important;width:100%!important;box-sizing:border-box!important;overflow:visible!important;";
    return `<div class="template-detail-block template-user-pattern-block" data-template-layer-block="${safeId}" style="overflow:visible!important;">
      <div class="template-detail-row template-user-pattern-row${noSwatchClass}" data-template-layer="${safeId}" style="${rowStyle}">
        <button type="button" class="template-eye-btn" data-template-eye-toggle="${safeId}" title="Show / hide" style="${actionBtnStyle}"><img src="./assets/ui/${enabled ? "eye_open_white_v0944.png" : "eye_closed_red_v0944.png"}" alt=""></button>
        ${paletteHtml}
        <span class="template-detail-name pattern-layer-name" data-template-rename="${safeId}"${zoneOpenAttr} title="${nameTitle}" style="min-width:0!important;overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important;padding-left:3px!important;box-sizing:border-box!important;">${name}</span>
        <button type="button" class="template-arrow-btn" data-template-up="${safeId}" title="Move up" style="${actionBtnStyle}"><img src="./assets/ui/flecha_arriba_white_v091.png?v=1.0.9" alt=""></button>
        <button type="button" class="template-arrow-btn" data-template-down="${safeId}" title="Move down" style="${actionBtnStyle}"><img src="./assets/ui/flecha_abajo_white_v091.png?v=1.0.9" alt=""></button>
        <button type="button" class="pattern-delete-x-btn" data-pattern-delete="${safeId}" title="Delete ${kindLabel} layer" aria-label="Delete ${kindLabel} layer" style="${deleteBtnStyle}">✕</button>
      </div>
      ${patternZoneDropdownHtml(layer)}
      ${templatePalettePopoverHtml(layer)}
    </div>`;
  }

  function templateEditableLayerRowHtml(layer) {
    if (templateLayerUsesGuidedPatternEngine(layer)) {
      markGuidedPatternLayerKind(layer);
      return userPatternLayerRowHtml(layer);
    }
    if (isGeneratedStripeLayer(layer)) return generatedStripeLayerRowHtml(layer);
    return templateLayerHasAnyFusionOpacityControl(layer) ? technicalLayerRowHtml(layer) : templateDetailRowHtml(layer);
  }

  function technicalLayerRowHtml(layer) {
    enforceRetroFixedBlackShadowLayer(layer);
    const name = escapeHtml(templateLayerVisibleLabel(layer));
    const enabled = layer.enabled !== false;
    const pct = Math.round((layer.opacity ?? 1) * 100);
    const forceBlendOpacity = templateLayerForcesBlendOpacity(layer);
    const hasBlend = forceBlendOpacity || layer.blend === true || templateLayerHasBlendDirective(layer);
    const hasOpacity = forceBlendOpacity || layer.opacityCtl === true || templateLayerHasOpacityDirective(layer);
    const paletteHtml = templatePaletteHtml(layer);
    const noSwatchClass = paletteHtml ? "" : " no-swatch";
    const opacity = hasOpacity ? `<input class="template-opacity" type="range" min="0" max="100" value="${pct}" data-template-opacity="${layer.id}"><span class="template-opacity-value" data-template-opacity-value="${layer.id}" title="Click to type opacity">${pct}%</span>` : "";
    const blend = hasBlend ? `<select data-template-blend="${layer.id}"><option value="source-over" ${layer.blendMode === "source-over" ? "selected" : ""}>Normal</option><option value="multiply" ${layer.blendMode === "multiply" ? "selected" : ""}>Multiply</option><option value="overlay" ${layer.blendMode === "overlay" ? "selected" : ""}>Overlay</option></select>` : "";
    return `<div class="template-detail-block template-tech-block" data-template-layer-block="${layer.id}">
      <div class="template-detail-row template-tech-row${noSwatchClass}" data-template-layer="${layer.id}">
        <button type="button" class="template-eye-btn" data-template-eye-toggle="${layer.id}" title="Show / hide"><img src="./assets/ui/${enabled ? "eye_open_white_v0944.png" : "eye_closed_red_v0944.png"}" alt=""></button>
        ${paletteHtml}
        <span class="template-detail-name" data-template-rename="${layer.id}" title="Click to rename">${name}</span>
        <span class="template-row-spacer"></span>
        ${blend}
        ${opacity}
        <button type="button" class="template-arrow-btn" data-template-up="${layer.id}" title="Move up"><img src="./assets/ui/flecha_arriba_white_v091.png?v=1.0.9" alt=""></button>
        <button type="button" class="template-arrow-btn" data-template-down="${layer.id}" title="Move down"><img src="./assets/ui/flecha_abajo_white_v091.png?v=1.0.9" alt=""></button>
      </div>
      ${templatePalettePopoverHtml(layer)}
    </div>`;
  }

  function templateFolderIsPattern(folder = "") {
    return /^pattern$/i.test(String(folder || "").replace(/[_-]+/g, " ").trim());
  }

  function templatePatternSubfolderKey(layer = {}) {
    if (!templateFolderIsPattern(layer?.folder)) return "";
    // Button-added user Pattern/Base Design layers live directly inside the main
    // Pattern/Base Design folder and must show their zone switches on the row.
    // Do not group them by their source asset folder (team/folder name), because that
    // creates an extra folder such as "Aston Villa Fc" and hides the old zone UI.
    if (layer?.isUserPattern === true || layer?.isUserBaseDesign === true) return "";
    const original = safeDecodeKitlabPath(layer.originalPath || layer.sourceName || layer.directiveSource || layer.path || layer.rawName || "").replace(/\\/g, "/");
    const match = original.match(/(?:^|\/)pattern\/([^\/]+)\//i);
    return match ? String(match[1] || "").trim() : "";
  }

  function templatePatternSubfolderStateKey(folder, subfolder) {
    return `${String(folder || "Pattern")}/${String(subfolder || "")}`;
  }

  function templatePatternSubfolderLabel(subfolder = "") {
    const raw = cleanFolderVisibleName(subfolder || "Pattern");
    return raw
      .replace(/\bcolour\b/ig, "Colours")
      .replace(/\bcolor\b/ig, "Colours")
      .replace(/\bcolours\b/ig, "Colours")
      .replace(/\bcolors\b/ig, "Colours")
      .replace(/\s+/g, " ")
      .trim();
  }

  function templatePatternSubfolderSortValue(subfolder = "") {
    const label = templatePatternSubfolderLabel(subfolder).toLowerCase();
    const num = Number((label.match(/\d+/) || [999])[0]);
    return Number.isFinite(num) ? num : 999;
  }

  function templatePatternSubfolderDefaults(layer = {}, templateItem = state.templateStyle?.selected || {}) {
    const templateName = String(templateItem?.name || templateItem?.path || "").toLowerCase();
    if (!templateName.includes("puma") || !templateName.includes("worldcup")) return;
    const subfolder = templatePatternSubfolderKey(layer).toLowerCase();
    if (!subfolder) return;
    // Puma GK WorldCup 26/27 has two official Pattern groups. The 2 Colours group is
    // the active/default version; 4 Colours is present but disabled by default.
    if (/^4\s*colou?r/.test(subfolder)) layer.enabled = false;
    if (/^2\s*colou?r/.test(subfolder)) layer.enabled = true;
  }

  function templatePatternSubfolderRowsHtml(section, folder, items) {
    const grouped = new Map();
    const loose = [];
    for (const layer of items || []) {
      const key = templatePatternSubfolderKey(layer);
      if (!key) { loose.push(layer); continue; }
      if (!grouped.has(key)) grouped.set(key, []);
      grouped.get(key).push(layer);
    }
    const groupRows = [...grouped.entries()]
      .sort((a, b) => templatePatternSubfolderSortValue(a[0]) - templatePatternSubfolderSortValue(b[0]) || templatePatternSubfolderLabel(a[0]).localeCompare(templatePatternSubfolderLabel(b[0]), undefined, { sensitivity: "base" }))
      .map(([subfolder, groupItems]) => {
        const stateKey = templatePatternSubfolderStateKey(folder, subfolder);
        const safeKey = escapeAttr(`${section}|${folder}|${subfolder}`);
        const isOpen = state.templateDetailOpen?.[section]?.[stateKey] === true;
        const groupEnabled = groupItems.some((layer) => layer.enabled !== false);
        const label = escapeHtml(templatePatternSubfolderLabel(subfolder));
        const rows = groupItems.map((layer) => templateEditableLayerRowHtml(layer)).join("");
        return `<div class="template-folder template-pattern-subfolder${isOpen ? " is-open" : " is-closed"}" data-template-pattern-subfolder-block="${escapeAttr(subfolder)}"><div class="template-folder-header" style="display:flex;align-items:center;gap:4px;width:100%;"><button type="button" class="template-eye-btn" data-template-pattern-subfolder-eye="${safeKey}" title="Show / hide folder"><img src="./assets/ui/${groupEnabled ? "eye_open_white_v0944.png" : "eye_closed_red_v0944.png"}" alt=""></button><button type="button" class="template-folder-title" data-template-pattern-subfolder="${safeKey}" style="flex:1;min-width:0;text-align:left;">${label}</button></div><div class="template-folder-body" ${isOpen ? "" : "hidden"}>${rows}</div></div>`;
      }).join("");
    const looseRows = loose.map((layer) => templateEditableLayerRowHtml(layer)).join("");
    return `${groupRows}${looseRows}`;
  }

  function templateFolderBlockHtml(section, folder, items) {
    const label = escapeHtml(cleanFolderVisibleName(folder));
    const folderKey = `${section}|${folder}`;
    const safeFolderKey = escapeAttr(folderKey);
    const isOpen = state.templateDetailOpen?.[section]?.[folder] !== false;
    const canMoveFolder = section === "collar";
    const titleBtn = `<button type="button" class="template-folder-title" data-template-folder="${safeFolderKey}" onclick="kitlabToggleTemplateFolder(event,this)" style="${canMoveFolder ? "flex:1;min-width:0;text-align:left;" : ""}">${label}</button>`;
    const moveControls = canMoveFolder ? `<button type="button" class="template-arrow-btn template-folder-arrow-btn" data-template-folder-up="${safeFolderKey}" title="Move folder up"><img src="./assets/ui/flecha_arriba_white_v091.png?v=1.0.9" alt=""></button><button type="button" class="template-arrow-btn template-folder-arrow-btn" data-template-folder-down="${safeFolderKey}" title="Move folder down"><img src="./assets/ui/flecha_abajo_white_v091.png?v=1.0.9" alt=""></button>` : "";
    const header = canMoveFolder ? `<div class="template-folder-header" style="display:flex;align-items:center;gap:4px;width:100%;">${titleBtn}${moveControls}</div>` : titleBtn;
    const folderIsPattern = templateFolderIsPattern(folder);
    const folderIsBaseDesign = templateFolderIsBaseDesign(folder);
    const rows = (folderIsPattern && (items || []).some((layer) => templatePatternSubfolderKey(layer)))
      ? templatePatternSubfolderRowsHtml(section, folder, items)
      : items.map((layer) => templateEditableLayerRowHtml(layer)).join("");
    return `<div class="template-folder template-tech-folder${isOpen ? " is-open" : " is-closed"}" data-template-tech-folder="${escapeAttr(folder)}">${header}<div class="template-folder-body" ${isOpen ? "" : "hidden"}>${rows}</div></div>`;
  }

  function templateDetailsRowsHtml(items) {
    // Law v1.0.2: any layer anywhere (details/brand/pattern/collar) whose original
    // path/name says fusion/opacidad, or any tights/extra layer, must show the
    // Fusion + Opacity controls. Button-added Pattern/Base Design layers always use
    // the special Pattern row with the delete X, even outside a technical folder.
    return items.map((layer) => templateEditableLayerRowHtml(layer)).join("");
  }


  function collarLayerShouldRenderAsFolder(layer) {
    if (!layer) return false;
    return layer._collarNestedFolder === true || isTechnicalFolderName(layer.folder, "collar");
  }

  function collarLayerFolderKey(layer) {
    return String(layer?.folder || "Details");
  }

  function collarLayerUnits(layersInput = state.templateStyle?.collarLayers || []) {
    const layers = Array.isArray(layersInput) ? layersInput : [];
    const seenFolders = new Set();
    const units = [];
    for (const layer of layers) {
      if (!collarLayerShouldRenderAsFolder(layer)) {
        units.push({ type: "layer", items: [layer] });
        continue;
      }
      const folder = collarLayerFolderKey(layer);
      if (seenFolders.has(folder)) continue;
      seenFolders.add(folder);
      units.push({
        type: "folder",
        folder,
        items: layers.filter((candidate) => collarLayerShouldRenderAsFolder(candidate) && collarLayerFolderKey(candidate) === folder),
      });
    }
    return units;
  }

  function applyCollarLayerUnits(units) {
    state.templateStyle.collarLayers = (Array.isArray(units) ? units : []).flatMap((unit) => unit.items || []);
  }

  function templateCollarRowsHtml(items) {
    const units = collarLayerUnits(Array.isArray(items) ? items : []);
    let html = "";
    for (const unit of units) {
      if (unit.type === "folder") {
        if (kitlabPublicBetaIsHiddenSeamsFolder(unit.folder)) continue;
        html += templateFolderBlockHtml("collar", unit.folder, unit.items);
      } else {
        const visibleItems = (unit.items || []).filter((layer) => !kitlabPublicBetaIsHiddenSeamsFolder(layer?.folder));
        html += templateDetailsRowsHtml(visibleItems);
      }
    }
    return html;
  }

  function templateSectionRowsHtml(section) {
    const layers = (state.templateStyle.details?.[section] || []).filter(templateLayerMatchesActiveShortVariant);
    let html = "";
    for (let i = 0; i < layers.length;) {
      const layer = layers[i];
      if (kitlabPublicBetaIsHiddenSeamsFolder(layer?.folder)) {
        const folder = layer.folder || "Seams";
        while (i < layers.length && String(layers[i].folder || "") === String(folder || "")) i += 1;
        continue;
      }
      if (isTechnicalFolderName(layer.folder, section)) {
        const folder = layer.folder || "Details";
        const items = [];
        while (i < layers.length && String(layers[i].folder || "") === String(folder || "") && isTechnicalFolderName(layers[i].folder, section)) {
          items.push(layers[i]);
          i += 1;
        }
        if (!kitlabPublicBetaIsHiddenSeamsFolder(folder)) html += templateFolderBlockHtml(section, folder, items);
      } else {
        html += templateDetailsRowsHtml([layer]);
        i += 1;
      }
    }
    return html;
  }

  function templateShortVariantSelectorHtml() {
    const variants = templateShortVariants();
    if (!variants.length) return "";
    const active = activeShortVariantId();
    const buttons = variants.map((variant) => {
      const id = String(variant.id || "v1").toLowerCase();
      const selected = id === active;
      return `<button type="button" class="kitlab-short-variant-btn${selected ? " is-selected" : ""}" data-short-variant-select="${escapeAttr(id)}">${escapeHtml(variant.name || id.toUpperCase())}</button>`;
    }).join("");
    return `<div class="kitlab-short-variant-block" style="margin:6px 0 7px;padding:7px 8px;border:1px solid rgba(255,255,255,.10);border-radius:10px;background:rgba(0,0,0,.16);">
      <div style="font-size:9px;line-height:1;font-weight:900;letter-spacing:.08em;color:rgba(255,255,255,.58);text-transform:uppercase;margin-bottom:6px;text-align:center;">Short Version</div>
      <div style="display:flex;gap:6px;justify-content:center;align-items:center;">
        ${buttons}
      </div>
    </div>`;
  }

  function installShortVariantButtonStyles() {
    if (document.getElementById("kitlab-short-variant-style")) return;
    const style = document.createElement("style");
    style.id = "kitlab-short-variant-style";
    style.textContent = `.kitlab-short-variant-btn{min-width:72px;padding:5px 10px;border:1px solid rgba(255,255,255,.18);border-radius:8px;background:rgba(255,255,255,.06);color:rgba(255,255,255,.82);font-size:10px;font-weight:900;line-height:1;cursor:pointer;transition:transform .14s ease,background .14s ease,border-color .14s ease,color .14s ease}.kitlab-short-variant-btn:hover{transform:scale(1.04);border-color:rgba(240,181,21,.8);background:rgba(240,181,21,.14)}.kitlab-short-variant-btn.is-selected{background:#f0b515;border-color:#f0b515;color:#151515;box-shadow:0 0 0 1px rgba(240,181,21,.35)}`;
    document.head.appendChild(style);
  }

  function setTemplateShortVariant(id) {
    const variants = templateShortVariants();
    if (!variants.length) return;
    const wanted = String(id || "v1").toLowerCase();
    const next = variants.some((variant) => String(variant.id || "").toLowerCase() === wanted) ? wanted : activeShortVariantId();
    if (next === activeShortVariantId()) return;
    state.templateStyle.shortVariant = next;
    invalidateInteractionRenderCache("details");
    renderTemplateDetailPanels();
    render({ immediate: true });
    persistTemplateSettingsQuietly();
    setStatus(`Short version: ${shortVariantDisplayName(next)}`);
  }

  function basicPieceRowHtml(pieceId) {
    const meta = PIECE_META_BY_ID[pieceId] || { label: pieceId };
    const colorState = state.pieceColors[pieceId] || {};
    const target = normalizeKitDefaultColor(colorState.target || colorState.source || PIECE_COLOR_FALLBACKS[pieceId] || KITLAB_CANONICAL_DEFAULT_COLOR);
    const enabled = state.pieceVisible?.[pieceId] !== false;
    const popover = state.activeColorPicker === pieceId
      ? `<div class="logo-color-popover-row template-picker-popover">${photoshopPickerHtml("piece", pieceId, target, `${meta.label || pieceId} color`)}</div>`
      : "";
    return `<div class="template-detail-block basic-piece-block" data-basic-piece-block="${pieceId}">
      <div class="template-detail-row basic-piece-row" data-basic-piece="${pieceId}">
        <button type="button" class="template-eye-btn" data-piece-eye-toggle="${pieceId}" title="Show / hide"><img src="./assets/ui/${enabled ? "eye_open_white_v0944.png" : "eye_closed_red_v0944.png"}" alt=""></button>
        <span class="template-palette-wrap"><button type="button" class="palette-color-swatch template-palette-swatch" data-open-piece-picker="${escapeAttr(pieceId)}" style="--template-chip-color:${target};background:${target};background-color:${target}" title="${target}"></button></span>
        <span class="template-detail-name">${escapeHtml(meta.label || pieceId)}</span>
        <span class="template-row-spacer"></span>
      </div>
      ${popover}
    </div>`;
  }


  const PATTERN_ASSET_ROOT = "assets/pattern";
  const PATTERN_FOLDER_FALLBACK_THUMB = TEMPLATE_FOLDER_FALLBACK_THUMB;

  function kitlabNoCacheUrl(url) {
    const clean = String(url || "");
    if (!clean) return clean;
    const sep = clean.includes("?") ? "&" : "?";
    return `${clean}${sep}_kitlab_nc=${Date.now()}_${Math.random().toString(36).slice(2)}`;
  }

  function patternPathParts(pathStack = state.patternGalleryPath || []) {
    return Array.isArray(pathStack) ? pathStack.filter(Boolean).map((part) => String(part)) : [];
  }

  function patternAssetUrl(parts = []) {
    return kitlabDynamicAssetUrl(encodePathParts(["assets", "pattern", ...parts]));
  }

  function cleanPatternName(name = "") {
    return cleanBrandFileName(decodeHashUnicode(String(name || "").replace(/\.[a-z0-9]+$/i, "").replace(/[_-]+/g, " ")));
  }

  function uniquePatternUrls(urls = []) {
    const out = [];
    const seen = new Set();
    (Array.isArray(urls) ? urls : []).forEach((url) => {
      const clean = String(url || "").trim();
      if (!clean || seen.has(clean)) return;
      seen.add(clean);
      out.push(clean);
    });
    return out;
  }

  function kitlabGalleryImageFallbackHtml(src, alt, fallbackList = [], extraAttrs = "") {
    const all = uniquePatternUrls([src, ...(Array.isArray(fallbackList) ? fallbackList : [])]);
    const first = all[0] || PATTERN_FOLDER_FALLBACK_THUMB || "";
    const fallbacks = all.slice(1);
    const fbAttr = fallbacks.length ? ` data-kitlab-img-fallbacks="${escapeAttr(JSON.stringify(fallbacks))}" onerror="window.__kitlabGalleryImageFallback&&window.__kitlabGalleryImageFallback(this)"` : "";
    return `<img src="${escapeAttr(first)}" alt="${escapeAttr(alt || "")}" ${extraAttrs || ""}${fbAttr}>`;
  }

  window.__kitlabGalleryImageFallback = window.__kitlabGalleryImageFallback || function(img) {
    try {
      const raw = img.getAttribute("data-kitlab-img-fallbacks") || "[]";
      const list = JSON.parse(raw);
      const next = Array.isArray(list) ? list.shift() : "";
      if (next) {
        img.setAttribute("data-kitlab-img-fallbacks", JSON.stringify(list || []));
        img.src = next;
      } else {
        img.onerror = null;
        if (typeof TEMPLATE_FOLDER_FALLBACK_THUMB !== "undefined" && TEMPLATE_FOLDER_FALLBACK_THUMB) img.src = TEMPLATE_FOLDER_FALLBACK_THUMB;
      }
    } catch (_) {
      img.onerror = null;
      if (typeof TEMPLATE_FOLDER_FALLBACK_THUMB !== "undefined" && TEMPLATE_FOLDER_FALLBACK_THUMB) img.src = TEMPLATE_FOLDER_FALLBACK_THUMB;
    }
  };

  const kitlabAssetListCache = new Map();

  // v1.3.262: global static asset manifest for Cloudflare/web-static galleries.
  // Templates remain deliberately hardcoded; only daily-changing assets use this catalog.
  let kitlabStaticAssetManifestPromise = null;
  var kitlabStaticAssetRevision = "";

  function kitlabDynamicAssetUrl(url) {
    const raw = String(url || "").trim();
    if (!raw || !kitlabStaticAssetRevision) return raw;
    if (!/^(?:\.\/|\/)?assets\/(?:pattern|team|brand|sponsor)\//i.test(raw)) return raw;
    if (/[?&]_kitlab_manifest=/.test(raw)) return raw;
    const separator = raw.includes("?") ? "&" : "?";
    return `${raw}${separator}_kitlab_manifest=${encodeURIComponent(kitlabStaticAssetRevision)}`;
  }

  function resetKitlabStaticAssetManifestCache() {
    kitlabStaticAssetManifestPromise = null;
    kitlabStaticAssetRevision = "";
    kitlabAssetListCache.clear();
    patternTeamThumbIndexPromise = null;
  }

  async function refreshKitlabStaticAssetManifest() {
    resetKitlabStaticAssetManifestCache();
    return loadKitlabStaticAssetManifest();
  }

  function kitlabStaticAssetDirKey(pathSegments = []) {
    const parts = Array.isArray(pathSegments) ? pathSegments.filter(Boolean).map((part) => String(part)) : [];
    return parts.join("/").replace(/\\+/g, "/").replace(/^\/+|\/+$/g, "");
  }

  async function loadKitlabStaticAssetManifest() {
    if (kitlabStaticAssetManifestPromise) return kitlabStaticAssetManifestPromise;
    kitlabStaticAssetManifestPromise = (async () => {
      try {
        const response = await fetch(kitlabNoCacheUrl("kitlab-data/asset_manifest.json"), { cache: "no-store" });
        if (!response.ok) return null;
        const payload = await response.json();
        if (!payload || !payload.dirs) return null;
        kitlabStaticAssetRevision = String(payload.generated || payload.version || "").trim();
        return payload;
      } catch (_) {
        return null;
      }
    })();
    return kitlabStaticAssetManifestPromise;
  }

  async function listKitlabStaticAssetDirectory(pathSegments = []) {
    const key = kitlabStaticAssetDirKey(pathSegments);
    if (!key) return null;
    const manifest = await loadKitlabStaticAssetManifest();
    const entry = manifest?.dirs?.[key];
    if (!entry) return null;
    const byName = (a, b) => cleanPatternName(a).localeCompare(cleanPatternName(b), undefined, { sensitivity: "base" });
    const folders = Array.isArray(entry.folders) ? [...new Set(entry.folders.filter(Boolean))].sort(byName) : [];
    const files = Array.isArray(entry.files) ? [...new Set(entry.files.filter((f) => /\.(png|webp|jpg|jpeg|svg)$/i.test(f)))].sort(byName) : [];
    return { folders, files };
  }

  function kitlabManifestTextPathKey(value = "") {
    let clean = String(value || "").split("?")[0].split("#")[0].replace(/\\/g, "/").replace(/^\/+/, "");
    try { clean = decodeURIComponent(clean); } catch (_) {}
    return decodeHashUnicode(clean).toLowerCase();
  }

  async function kitlabStaticManifestHasTextFile(path = "") {
    const manifest = await loadKitlabStaticAssetManifest();
    if (!manifest || !Array.isArray(manifest.textFiles)) return null;
    const wanted = kitlabManifestTextPathKey(path);
    return manifest.textFiles.some((item) => kitlabManifestTextPathKey(item) === wanted);
  }

  async function listKitlabAssetDirectory(pathSegments = []) {
    const parts = Array.isArray(pathSegments) ? pathSegments.filter(Boolean).map((part) => String(part)) : [];
    const key = parts.join("/");
    if (kitlabAssetListCache.has(key)) return kitlabAssetListCache.get(key);
    const byName = (a, b) => cleanPatternName(a).localeCompare(cleanPatternName(b), undefined, { sensitivity: "base" });
    const readPromise = (async () => {
      try {
        const staticListed = await listKitlabStaticAssetDirectory(parts);
        if (staticListed) return staticListed;
      } catch (_) {}
      try {
        const apiUrl = `/kitlab-api/list-assets?dir=${encodeURIComponent(key)}`;
        const response = await fetch(kitlabNoCacheUrl(apiUrl), { cache: "no-store" });
        if (response.ok) {
          const payload = await response.json();
          const folders = Array.isArray(payload?.folders) ? payload.folders.filter(Boolean) : [];
          const files = Array.isArray(payload?.files) ? payload.files.filter((f) => /\.(png|webp|jpg|jpeg|svg)$/i.test(f)) : [];
          return { folders: [...new Set(folders)].sort(byName), files: [...new Set(files)].sort(byName) };
        }
      } catch (_) {}
      try {
        const url = encodePathParts(parts) + "/";
        const response = await fetch(kitlabNoCacheUrl(url), { cache: "no-store" });
        if (!response.ok) return { folders: [], files: [] };
        const html = await response.text();
        const folders = [];
        const files = [];
        const hrefRegex = /href=["']([^"']+)["']/gi;
        let match;
        while ((match = hrefRegex.exec(html))) {
          let href = String(match[1] || "");
          if (!href || href === "../" || href === "./") continue;
          href = href.split("?")[0].split("#")[0];
          const decoded = decodeURIComponent(href.replace(/\/$/, "").split("/").pop() || "");
          if (!decoded || decoded.startsWith(".")) continue;
          if (/\.(png|webp|jpg|jpeg)$/i.test(decoded)) files.push(decoded);
          else if (href.endsWith("/") || !/\.[a-z0-9]+$/i.test(decoded)) folders.push(decoded);
        }
        return { folders: [...new Set(folders)].sort(byName), files: [...new Set(files)].sort(byName) };
      } catch (_) {
        return { folders: [], files: [] };
      }
    })();
    kitlabAssetListCache.set(key, readPromise);
    return readPromise;
  }

  let patternTeamThumbIndexPromise = null;

  async function loadPatternTeamThumbIndex() {
    if (patternTeamThumbIndexPromise) return patternTeamThumbIndexPromise;
    patternTeamThumbIndexPromise = (async () => {
      const map = new Map();
      const manifestKeys = new Set();
      const add = (name, url) => {
        const key = normalizeAssetMatchKey(cleanPatternName(name));
        if (key && url && !map.has(key)) map.set(key, url);
      };
      const addManifest = (name, url) => {
        const key = normalizeAssetMatchKey(cleanPatternName(name));
        if (!key || !url || manifestKeys.has(key)) return;
        // The live manifest must replace old embedded #Uxxxx filenames. Those
        // compatibility names describe the right team but are not physical web URLs.
        map.set(key, url);
        manifestKeys.add(key);
      };
      (INTERNAL_TEAMS || []).forEach((item) => {
        add(item.name || item.file, item.src);
        add(cleanBrandFileName(item.file || ""), item.src);
      });
      const root = await listKitlabAssetDirectory(["assets", "team"]);
      (root.files || []).forEach((file) => addManifest(file, encodePathParts(["assets", "team", file])));
      for (const folder of (root.folders || [])) {
        const listed = await listKitlabAssetDirectory(["assets", "team", folder]);
        (listed.files || []).forEach((file) => addManifest(file, encodePathParts(["assets", "team", folder, file])));
      }
      return map;
    })();
    return patternTeamThumbIndexPromise;
  }

  async function patternTeamShieldCandidates(folderName = "") {
    const original = String(folderName || "").trim();
    const clean = cleanPatternName(original);
    const candidates = [];
    if (original) {
      candidates.push(encodePathParts(["assets", "team", `${original}.png`]));
      candidates.push(encodePathParts(["assets", "team", `${original}.webp`]));
      candidates.push(encodePathParts(["assets", "team", `${original}.jpg`]));
    }
    if (clean && clean !== original) {
      candidates.push(encodePathParts(["assets", "team", `${clean}.png`]));
      candidates.push(encodePathParts(["assets", "team", `${clean}.webp`]));
      candidates.push(encodePathParts(["assets", "team", `${clean}.jpg`]));
    }
    const wanted = normalizeAssetMatchKey(clean || original);
    if (wanted) {
      // Prefer the live manifest. It contains the exact physical Unicode/casing used
      // by the server and also knows teams added after app.js was published.
      try {
        const index = await loadPatternTeamThumbIndex();
        const indexedExact = index.get(wanted);
        if (indexedExact) candidates.push(indexedExact);
        for (const [key, url] of index.entries()) {
          if (key && (key.includes(wanted) || wanted.includes(key))) {
            candidates.push(url);
            break;
          }
        }
      } catch (_) {}
      // The manifest can intentionally replace INTERNAL_TEAMS. Keep the
      // embedded catalog as a second, immutable source so an existing shield
      // never disappears merely because its filename was omitted or encoded
      // differently in a newly generated manifest.
      const embeddedExact = (PATTERN_TEAM_EMBEDDED_FALLBACKS || []).find((item) => normalizeAssetMatchKey(item.name || item.file || "") === wanted);
      if (embeddedExact?.src) candidates.push(embeddedExact.src);
      const embeddedLoose = (PATTERN_TEAM_EMBEDDED_FALLBACKS || []).find((item) => {
        const key = normalizeAssetMatchKey(item.name || item.file || "");
        return key && (key.includes(wanted) || wanted.includes(key));
      });
      if (embeddedLoose?.src) candidates.push(embeddedLoose.src);

      const exact = (INTERNAL_TEAMS || []).find((item) => normalizeAssetMatchKey(item.name || item.file || "") === wanted);
      if (exact?.src) candidates.push(exact.src);
      const loose = (INTERNAL_TEAMS || []).find((item) => {
        const key = normalizeAssetMatchKey(item.name || item.file || "");
        return key && (key.includes(wanted) || wanted.includes(key));
      });
      if (loose?.src) candidates.push(loose.src);
    }
    candidates.push(PATTERN_FOLDER_FALLBACK_THUMB);
    return uniquePatternUrls(candidates.map((url) => kitlabDynamicAssetUrl(url)));
  }

  function isPatternThumbFile(file = "") {
    const lower = String(file || "").toLowerCase();
    return /(^|[\s_-])(thumbnail|thumb|preview|miniatura)([\s_.-]|$)/i.test(lower) || /^(thumbnail|thumb|preview)\.(png|webp|jpg|jpeg)$/i.test(lower);
  }

  async function listAssetFolder(pathParts = []) {
    const parts = patternPathParts(pathParts);
    return listKitlabAssetDirectory(["assets", "pattern", ...parts]);
  }

  async function resolvePatternFolderItem(parts = [], folder = "") {
    const itemParts = [...patternPathParts(parts), String(folder || "")].filter(Boolean);
    const listed = await listAssetFolder(itemParts);
    const imageFiles = (listed.files || []).filter((file) => /\.(png|webp|jpg|jpeg)$/i.test(file));
    const thumbFile = imageFiles.find(isPatternThumbFile) || imageFiles.find((file) => /thumbnail/i.test(file));
    const realFile = imageFiles.find((file) => !isPatternThumbFile(file)) || imageFiles[0];
    const thumb = thumbFile ? patternAssetUrl([...itemParts, thumbFile]) : (realFile ? patternAssetUrl([...itemParts, realFile]) : PATTERN_FOLDER_FALLBACK_THUMB);
    const src = realFile ? patternAssetUrl([...itemParts, realFile]) : "";
    return {
      type: "file",
      isPatternFolderItem: true,
      name: cleanPatternName(folder),
      folder,
      pathParts: src ? [...itemParts, realFile] : itemParts,
      src,
      thumb,
      team: cleanPatternName(parts[0] || "Pattern"),
    };
  }

  async function refreshPatternGalleryFolder(pathStack = state.patternGalleryPath || []) {
    const parts = patternPathParts(pathStack);
    const listed = await listAssetFolder(parts);
    let folders = [];
    if (!parts.length) {
      folders = await Promise.all((listed.folders || []).map(async (folder) => {
        const shields = await patternTeamShieldCandidates(folder);
        return {
          type: "folder",
          name: cleanPatternName(folder),
          folder,
          pathParts: [folder],
          thumb: shields[0],
          thumbFallbacks: shields.slice(1),
        };
      }));
    } else {
      folders = await Promise.all((listed.folders || []).map((folder) => resolvePatternFolderItem(parts, folder)));
    }
    const files = (listed.files || [])
      .filter((file) => !isPatternThumbFile(file))
      .map((file) => ({
        type: "file",
        name: cleanPatternName(file),
        file,
        pathParts: [...parts, file],
        src: patternAssetUrl([...parts, file]),
        thumb: patternAssetUrl([...parts, file]),
        team: cleanPatternName(parts[0] || parts[parts.length - 1] || "Pattern"),
      }));
    state.patternGalleryItems = [...folders, ...files];
    return state.patternGalleryItems;
  }


  const OVERLAY_ASSET_ROOT = "assets/overlay";
  const OVERLAY_EMBEDDED_FILES = [
    'copa_america_24_1.png',
    'copa_america_24_2.png',
    'copa_america_24_3.png',
    'copa_america_24_argentina.png',
    'copa_america_24_bolivia.png',
    'copa_america_24_brasil.png',
    'copa_america_24_chile.png',
    'copa_america_24_colombia.png',
    'copa_america_24_paraguay.png',
    'copa_america_24_peru.png',
    'copa_america_24_uruguay.png',
    'copa_america_winner_2021_1.png',
    'copa_america_winner_2021_2.png',
    'euro_2024.png',
    'euro_2024_winner.png',
    'fifa_cwc_23.png',
    'fifa_cwc_25.png',
    'fifa_footall_unites_blue.png',
    'fifa_footall_unites_white.png',
    'fifa_intercontinental_24.png',
    'fifa_wc_winner_22_gold.png',
    'fifa_wc_winner_22_white.png',
    'ucl.png',
    'ucl_15.png',
    'ucl_4.png',
    'ucl_5.png',
    'ucl_6.png',
    'ucl_7.png',
    'ucl_europa_winners_25.png',
    'uefa_foundation.png',
    'uefa_foundation_10_yrs.png',
    'uefa_nations_23_1.png',
    'uefa_nations_23_2.png'
  ];

  function overlayEmbeddedFileList() {
    return [...new Set(OVERLAY_EMBEDDED_FILES || [])].filter((file) => /\.(png|webp|jpg|jpeg)$/i.test(String(file || "")));
  }
  const OVERLAY_LEFT_ANCHOR = { x: 653, y: 961 };
  const OVERLAY_RIGHT_ANCHOR = { x: 1393, y: 961 };
  const OVERLAY_LEFT_BOUNDS = { x: 389, y: 675, w: 384, h: 552 };
  const OVERLAY_RIGHT_BOUNDS = { x: 1275, y: 675, w: 384, h: 552 };

  function overlayAssetUrl(file = "") {
    return encodePathParts(["assets", "overlay", String(file || "")]);
  }

  function overlayDisplayName(name = "") {
    return cleanBrandFileName(decodeHashUnicode(String(name || "").replace(/\.[a-z0-9]+$/i, "").replace(/[_-]+/g, " ")));
  }

  async function listOverlayAssetFolder() {
    const byName = (a, b) => overlayDisplayName(a).localeCompare(overlayDisplayName(b), undefined, { sensitivity: "base" });
    const normalizeOverlayFileName = (value = "") => {
      let clean = String(value || "").split("?")[0].split("#")[0].replace(/\\/g, "/").replace(/\/$/, "");
      clean = clean.split("/").pop() || clean;
      try { clean = decodeURIComponent(clean); } catch (_) {}
      return clean;
    };
    const normalizeList = (list = []) => [...new Set((list || []).map(normalizeOverlayFileName).filter((f) => /\.(png|webp|jpg|jpeg)$/i.test(f)))].sort(byName);
    try {
      const apiUrl = `/kitlab-api/list-assets?dir=${encodeURIComponent("assets/overlay")}`;
      const response = await fetch(kitlabNoCacheUrl(apiUrl), { cache: "no-store" });
      if (response.ok) {
        const payload = await response.json();
        const files = normalizeList(Array.isArray(payload?.files) ? payload.files : []);
        if (files.length) return files;
      }
    } catch (error) {
      console.warn("Overlay API listing unavailable, trying directory fallback:", error);
    }
    try {
      const response = await fetch(kitlabNoCacheUrl(`${OVERLAY_ASSET_ROOT}/`), { cache: "no-store" });
      if (response.ok) {
        const html = await response.text();
        const files = [];
        const hrefRegex = /href=["']([^"']+)["']/gi;
        let match;
        while ((match = hrefRegex.exec(html))) {
          let href = String(match[1] || "");
          if (!href || href === "../" || href === "./") continue;
          href = href.split("?")[0].split("#")[0];
          files.push(href);
        }
        const parsed = normalizeList(files);
        if (parsed.length) return parsed;
      }
    } catch (error) {
      console.warn("Overlay folder listing unavailable, using embedded overlay manifest:", error);
    }
    return normalizeList(overlayEmbeddedFileList());
  }

  async function refreshOverlayGalleryFolder() {
    const files = await listOverlayAssetFolder();
    state.overlayGalleryItems = files.map((file) => ({
      type: "file",
      name: overlayDisplayName(file),
      file,
      src: overlayAssetUrl(file),
      thumb: overlayAssetUrl(file),
    }));
    return state.overlayGalleryItems;
  }

  function overlayBoundsForSide(side = state.overlay?.side || "left") {
    return String(side || "left").toLowerCase() === "right" ? OVERLAY_RIGHT_BOUNDS : OVERLAY_LEFT_BOUNDS;
  }

  function overlayAnchorForSide(side = state.overlay?.side || "left") {
    return String(side || "left").toLowerCase() === "right" ? OVERLAY_RIGHT_ANCHOR : OVERLAY_LEFT_ANCHOR;
  }

  function overlayDrawMetrics(overlay = state.overlay || {}) {
    const img = overlay.image;
    const srcW = img ? (img.naturalWidth || img.width || 0) : 0;
    const srcH = img ? (img.naturalHeight || img.height || 0) : 0;
    const scale = Math.max(0.01, Number(overlay.size || 100) / 100);
    const w = Math.max(1, srcW * scale);
    const h = Math.max(1, srcH * scale);
    // 90º rotation swaps the rendered bounding box.
    return { srcW, srcH, drawW: h, drawH: w, imageW: w, imageH: h };
  }

  function overlayMovementLimits(overlay = state.overlay || {}) {
    const side = String(overlay.side || "left").toLowerCase() === "right" ? "right" : "left";
    const bounds = overlayBoundsForSide(side);
    const anchor = overlayAnchorForSide(side);
    const m = overlayDrawMetrics(overlay);
    const halfW = m.drawW / 2;
    const halfH = m.drawH / 2;
    let minX = Math.ceil(bounds.x + halfW - anchor.x);
    let maxX = Math.floor(bounds.x + bounds.w - halfW - anchor.x);
    let minY = Math.ceil(bounds.y + halfH - anchor.y);
    let maxY = Math.floor(bounds.y + bounds.h - halfH - anchor.y);
    if (minX > maxX) { minX = maxX = 0; }
    if (minY > maxY) { minY = maxY = 0; }
    return { minX, maxX, minY, maxY };
  }

  function maxOverlaySizePercent(overlay = state.overlay || {}) {
    const img = overlay.image;
    if (!img) return 100;
    const srcW = img.naturalWidth || img.width || 1;
    const srcH = img.naturalHeight || img.height || 1;
    const bounds = overlayBoundsForSide(overlay.side || "left");
    // Rotation swaps the bounding dimensions.
    return Math.max(1, Math.floor(Math.min(bounds.w / srcH, bounds.h / srcW) * 100));
  }

  function clampOverlayState(showMessage = false) {
    if (!state.overlay) return;
    state.overlay.side = String(state.overlay.side || "left").toLowerCase() === "right" ? "right" : "left";
    const maxSize = maxOverlaySizePercent(state.overlay);
    const beforeSize = Number(state.overlay.size || 100);
    state.overlay.size = clamp(beforeSize, 1, maxSize || 100);
    if (showMessage && beforeSize !== state.overlay.size) setStatus("Size not accepted");
    const limits = overlayMovementLimits(state.overlay);
    state.overlay.x = clamp(Number(state.overlay.x || 0), limits.minX, limits.maxX);
    state.overlay.y = clamp(Number(state.overlay.y || 0), limits.minY, limits.maxY);
  }

  function overlayNameLabel() {
    const name = String(state.overlay?.name || "").trim();
    return name || "No overlay";
  }

  function updateOverlayUi() {
    const hasTemplate = !!state.templateStyle?.selected;
    if (els.overlaySettingsLine) els.overlaySettingsLine.hidden = !hasTemplate;
    const label = overlayNameLabel();
    if (els.selectedOverlayName) {
      const valueEl = els.selectedOverlayName.querySelector(".settings-value");
      if (valueEl) {
        valueEl.textContent = label;
      } else {
        els.selectedOverlayName.innerHTML = `<span class="settings-label">Overlay:</span><span class="settings-value">${escapeHtml(label)}</span>`;
      }
      els.selectedOverlayName.title = label;
    }
    if (els.overlayDeleteBtn) els.overlayDeleteBtn.disabled = !hasTemplate || !state.overlay?.image;
    if (els.overlayDuplicateBtn) els.overlayDuplicateBtn.disabled = !hasTemplate || !state.overlay?.image;
    if (els.overlayControls) {
      els.overlayControls.hidden = !hasTemplate || !(state.overlay?.controlsOpen && state.overlay?.image);
      if (!els.overlayControls.hidden) renderOverlayControls();
    }
  }

  function overlayControlRow(label, key, value, min, max, step = 1) {
    const safeValue = Number.isFinite(Number(value)) ? Number(value) : 0;
    return `<label class="overlay-control-row"><span>${escapeHtml(label)}</span><input class="overlay-range" type="range" min="${min}" max="${max}" step="${step}" value="${safeValue}" data-overlay-control="${escapeAttr(key)}"><input class="overlay-number" type="number" min="${min}" max="${max}" step="${step}" value="${safeValue}" data-overlay-control-num="${escapeAttr(key)}"></label>`;
  }

  function renderOverlayControls() {
    if (!els.overlayControls || !state.overlay?.image) return;
    clampOverlayState(false);
    const limits = overlayMovementLimits(state.overlay);
    const maxSize = maxOverlaySizePercent(state.overlay);
    els.overlayControls.innerHTML = `
      <div class="overlay-control-row overlay-side-row"><span>Side</span><select id="overlaySideSelect" class="overlay-side-select"><option value="left" ${state.overlay.side !== "right" ? "selected" : ""}>Left</option><option value="right" ${state.overlay.side === "right" ? "selected" : ""}>Right</option></select></div>
      ${overlayControlRow("Size", "size", Math.round(Number(state.overlay.size || 100)), 1, maxSize || 100, 1)}
      ${overlayControlRow("X", "x", Math.round(Number(state.overlay.x || 0)), limits.minX, limits.maxX, 1)}
      ${overlayControlRow("Y", "y", Math.round(Number(state.overlay.y || 0)), limits.minY, limits.maxY, 1)}
      <button type="button" class="overlay-export-btn" data-overlay-export="1">Export Overlay</button>
    `;
  }

  function setOverlayLayer(image, name = "Overlay", src = "") {
    state.overlay = {
      image,
      src: src || image?.src || "",
      name: name || "Overlay",
      side: "left",
      size: 100,
      x: 0,
      y: 0,
      // Keep the Settings row clean after loading. Controls open only when clicking "Overlay:".
      controlsOpen: false,
    };
    clampOverlayState(true);
    updateOverlayUi();
    render({ immediate: true });
    setStatus(`Overlay loaded: ${state.overlay.name}`);
  }

  function validateOverlayImageSize(image) {
    if (!image) return false;
    const w = image.naturalWidth || image.width || 0;
    const h = image.naturalHeight || image.height || 0;
    const maxW = Math.max(OVERLAY_LEFT_BOUNDS.w, OVERLAY_RIGHT_BOUNDS.w);
    const maxH = Math.max(OVERLAY_LEFT_BOUNDS.h, OVERLAY_RIGHT_BOUNDS.h);
    // Overlay PNGs are rotated 90º on the sleeve. Both orientations must fit inside the guide area.
    return (w <= maxW && h <= maxH) || (h <= maxW && w <= maxH);
  }

  function loadOverlayFromItem(item) {
    if (!item) return;
    const candidates = [];
    const add = (value) => {
      const raw = String(value || "").trim();
      if (raw && !candidates.includes(raw)) candidates.push(raw);
    };
    add(item.src);
    add(item.thumb);
    add(item.path);
    if (item.file) {
      add(overlayAssetUrl(item.file));
      add(`./${overlayAssetUrl(item.file)}`);
      try { add(`assets/overlay/${encodeURIComponent(String(item.file)).replace(/%2F/g, "/")}`); } catch (_) {}
      add(`assets/overlay/${String(item.file)}`);
    }
    const tryCandidate = (index = 0) => {
      const src = candidates[index];
      if (!src) {
        setStatus(`Could not load Overlay: ${item.name || item.file || "Overlay"}`);
        return;
      }
      loadImageFromSrc(src, (image) => {
        if (!validateOverlayImageSize(image)) {
          setStatus("Size not accepted");
          showToast("Size not accepted");
          return;
        }
        setOverlayLayer(image, item.name || overlayDisplayName(item.file || "Overlay"), src);
        closeGallery();
      }, () => tryCandidate(index + 1));
    };
    tryCandidate(0);
  }


  function overlayItemFromCard(card) {
    if (!card) return null;
    const index = Number(card.dataset.overlayIndex || 0);
    const listed = filteredInternalBrands()[index] || (state.overlayGalleryItems || [])[index] || {};
    const file = card.dataset.overlayFile || listed.file || "";
    const src = card.dataset.overlaySrc || listed.src || listed.thumb || listed.path || (file ? overlayAssetUrl(file) : "");
    const name = card.dataset.overlayName || listed.name || overlayDisplayName(file || src || "Overlay");
    return { ...listed, type: "file", file, src, thumb: listed.thumb || src, path: listed.path || src, name };
  }

  function loadOverlayFromCard(card) {
    const item = overlayItemFromCard(card);
    if (!item) return true;
    const name = item.name || overlayDisplayName(item.file || item.src || "Overlay");
    setStatus(`Loading Overlay: ${name}`);

    // Use the already-loaded gallery thumbnail when possible. This avoids any
    // path/index mismatch between the gallery card and the selected PNG.
    const imgEl = card.querySelector?.("img");
    if (imgEl && imgEl.complete && (imgEl.naturalWidth || imgEl.width) && (imgEl.naturalHeight || imgEl.height)) {
      if (!validateOverlayImageSize(imgEl)) {
        setStatus("Size not accepted");
        showToast("Size not accepted");
        return true;
      }
      setOverlayLayer(imgEl, name, imgEl.currentSrc || imgEl.src || item.src || "");
      closeGallery();
      return true;
    }

    loadOverlayFromItem(item);
    return true;
  }

  function handleOverlayGalleryClick(event) {
    if (state.gallerySource !== "overlay") return false;
    const overlayCard = event.target.closest?.("[data-overlay-index], [data-overlay-file], .overlay-png-card");
    if (!overlayCard) return false;
    event.preventDefault();
    event.stopPropagation();
    return loadOverlayFromCard(overlayCard);
  }

  function deleteOverlayLayer() {
    state.overlay = { image: null, src: "", name: "", side: "left", size: 100, x: 0, y: 0, controlsOpen: false };
    updateOverlayUi();
    render();
    setStatus("Overlay removed");
  }

  function duplicateOverlayLayer() {
    if (!state.overlay?.image) return;
    // Single Overlay module: duplicate keeps the same PNG/settings ready for immediate adjustment.
    state.overlay = { ...state.overlay, name: `${state.overlay.name || "Overlay"} Copy`, controlsOpen: true };
    updateOverlayUi();
    render();
    setStatus("Overlay duplicated");
  }

  function drawOverlayLayer(targetCtx = ctx) {
    const overlay = state.overlay || {};
    const img = overlay.image;
    if (!img) return;
    clampOverlayState(false);
    const side = overlay.side === "right" ? "right" : "left";
    const anchor = overlayAnchorForSide(side);
    const x = anchor.x + Number(overlay.x || 0);
    const y = anchor.y + Number(overlay.y || 0);
    const m = overlayDrawMetrics(overlay);
    if (!m.imageW || !m.imageH) return;
    targetCtx.save();
    targetCtx.globalAlpha = 1;
    targetCtx.globalCompositeOperation = "source-over";
    targetCtx.imageSmoothingEnabled = true;
    targetCtx.translate(x, y);
    // Left sleeve = 90º clockwise. Right sleeve = 90º counterclockwise.
    targetCtx.rotate(side === "right" ? -Math.PI / 2 : Math.PI / 2);
    targetCtx.drawImage(img, -m.imageW / 2, -m.imageH / 2, m.imageW, m.imageH);
    targetCtx.restore();
  }

  function safeDownloadName(name = "overlay") {
    return String(name || "overlay")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9._-]+/gi, "_")
      .replace(/^_+|_+$/g, "") || "overlay";
  }

  function downloadCanvasPng(sourceCanvas, fileName) {
    if (!sourceCanvas) return;
    const trigger = (href) => {
      const link = document.createElement("a");
      link.download = fileName;
      link.href = href;
      document.body.appendChild(link);
      link.click();
      link.remove();
    };
    if (sourceCanvas.toBlob) {
      sourceCanvas.toBlob((blob) => {
        if (!blob) {
          trigger(sourceCanvas.toDataURL("image/png"));
          return;
        }
        const url = URL.createObjectURL(blob);
        trigger(url);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      }, "image/png");
    } else {
      trigger(sourceCanvas.toDataURL("image/png"));
    }
  }

  function exportOverlayPng() {
    if (!state.overlay?.image) {
      setStatus("No overlay selected");
      return;
    }
    clampOverlayState(false);
    const overlayCanvas = document.createElement("canvas");
    overlayCanvas.width = CANVAS_SIZE;
    overlayCanvas.height = CANVAS_SIZE;
    const overlayCtx = overlayCanvas.getContext("2d");
    if (!overlayCtx) {
      setStatus("Overlay export failed");
      return;
    }
    overlayCtx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);
    drawOverlayLayer(overlayCtx);
    const side = state.overlay.side === "right" ? "Right" : "Left";
    const baseName = safeDownloadName(state.overlay.name || "Overlay");
    downloadCanvasPng(overlayCanvas, `kitlab6_overlay_${baseName}_${side}_${Date.now()}.png`);
    setStatus("Overlay exported");
  }

  async function applySavedOverlay(saved = {}) {
    const data = saved?.overlay || null;
    if (!data || !data.src) {
      state.overlay = { image: null, src: "", name: "", side: "left", size: 100, x: 0, y: 0, controlsOpen: false };
      updateOverlayUi();
      return;
    }
    await new Promise((resolve) => {
      loadImageFromSrc(data.src, (image) => {
        state.overlay = {
          image,
          src: data.src,
          name: data.name || overlayDisplayName(String(data.src).split("/").pop() || "Overlay"),
          side: data.side === "right" ? "right" : "left",
          size: Number(data.size || 100),
          x: Number(data.x || 0),
          y: Number(data.y || 0),
          controlsOpen: false,
        };
        clampOverlayState(false);
        updateOverlayUi();
        resolve();
      }, () => { updateOverlayUi(); resolve(); });
      setTimeout(resolve, 1200);
    });
  }

  function serializeOverlay() {
    if (!state.overlay?.src) return null;
    return {
      src: state.overlay.src,
      name: state.overlay.name || "Overlay",
      side: state.overlay.side === "right" ? "right" : "left",
      size: Number(state.overlay.size || 100),
      x: Number(state.overlay.x || 0),
      y: Number(state.overlay.y || 0),
    };
  }

  const BASE_DESIGN_ASSET_ROOT = "assets/base_design";

  function baseDesignPathParts(pathStack = state.baseDesignGalleryPath || []) {
    return Array.isArray(pathStack) ? pathStack.filter(Boolean).map((part) => String(part)) : [];
  }

  function baseDesignAssetUrl(parts = []) {
    return encodePathParts(["assets", "base_design", ...parts]);
  }

  function cleanPatternName(name = "") {
    return cleanBrandFileName(decodeHashUnicode(String(name || "").replace(/\.[a-z0-9]+$/i, "").replace(/[_-]+/g, " ")));
  }

  function findTeamThumbForPatternFolder(name = "") {
    const wanted = normalizeAssetMatchKey(cleanPatternName(name));
    if (!wanted) return PATTERN_FOLDER_FALLBACK_THUMB;
    const exact = INTERNAL_TEAMS.find((item) => normalizeAssetMatchKey(item.name || item.file || "") === wanted);
    if (exact?.src) return exact.src;
    const loose = INTERNAL_TEAMS.find((item) => {
      const key = normalizeAssetMatchKey(item.name || item.file || "");
      return key && (key.includes(wanted) || wanted.includes(key));
    });
    return loose?.src || PATTERN_FOLDER_FALLBACK_THUMB;
  }

  async function listAssetFolder(pathParts = []) {
    const parts = patternPathParts(pathParts);
    return listKitlabAssetDirectory(["assets", "pattern", ...parts]);
  }

  // v1.3.273: keep the manifest-aware Pattern gallery implementation active.
  // An older duplicate of this function used only the embedded INTERNAL_TEAMS list,
  // so newly added teams and filenames containing accents/Unicode fell back to the
  // generic folder icon. Root Pattern folders now resolve their shield through the
  // live Team manifest and keep a fallback chain for legacy encoded filenames.
  async function refreshPatternGalleryFolder(pathStack = state.patternGalleryPath || []) {
    const parts = patternPathParts(pathStack);
    const listed = await listAssetFolder(parts);
    let folders = [];
    if (!parts.length) {
      folders = await Promise.all((listed.folders || []).map(async (folder) => {
        const shields = await patternTeamShieldCandidates(folder);
        return {
          type: "folder",
          name: cleanPatternName(folder),
          folder,
          pathParts: [folder],
          thumb: shields[0],
          thumbFallbacks: shields.slice(1),
        };
      }));
    } else {
      folders = await Promise.all((listed.folders || []).map((folder) => resolvePatternFolderItem(parts, folder)));
    }
    const files = (listed.files || [])
      .filter((file) => !isPatternThumbFile(file))
      .map((file) => ({
        type: "file",
        name: cleanPatternName(file),
        file,
        pathParts: [...parts, file],
        src: patternAssetUrl([...parts, file]),
        thumb: patternAssetUrl([...parts, file]),
        team: cleanPatternName(parts[0] || parts[parts.length - 1] || "Pattern"),
      }));
    state.patternGalleryItems = [...folders, ...files];
    return state.patternGalleryItems;
  }

  async function listBaseDesignAssetFolder(pathParts = []) {
    const parts = baseDesignPathParts(pathParts);
    return listKitlabAssetDirectory(["assets", "base_design", ...parts]);
  }

  async function refreshBaseDesignGalleryFolder(pathStack = state.baseDesignGalleryPath || []) {
    const parts = baseDesignPathParts(pathStack);
    const listed = await listBaseDesignAssetFolder(parts);
    const folders = listed.folders.map((folder) => ({
      type: "folder",
      name: cleanPatternName(folder),
      folder,
      pathParts: [...parts, folder],
      thumb: PATTERN_FOLDER_FALLBACK_THUMB,
    }));
    const files = listed.files.map((file) => ({
      type: "file",
      name: cleanPatternName(file),
      file,
      pathParts: [...parts, file],
      src: baseDesignAssetUrl([...parts, file]),
      thumb: baseDesignAssetUrl([...parts, file]),
      team: cleanPatternName(parts[parts.length - 1] || "Base Design"),
    }));
    state.baseDesignGalleryItems = [...folders, ...files];
    return state.baseDesignGalleryItems;
  }

  function patternGuideRole(meta = {}) {
    const explicit = String(meta.role || "").toLowerCase().trim();
    if (explicit === "front" || explicit === "shirt_front" || explicit === "shirtfront") return "front";
    if (explicit === "back" || explicit === "shirt_back" || explicit === "shirtback") return "back";
    if (explicit === "sleeve" || explicit === "sleeve_short" || explicit === "short_sleeves") return "sleeve";
    if (explicit === "short" || explicit === "pattern_short" || explicit === "short_pattern") return "short";
    const text = `${meta.name || ""} ${meta.path || ""}`.replace(/[_-]+/g, " ").toLowerCase();
    if (/short\s*hem/.test(text)) return "";
    if (/shirt\s*front|front\s*shirt/.test(text)) return "front";
    if (/shirt\s*back|back\s*shirt/.test(text)) return "back";
    if (/short\s*sleeves?|sleeve\s*short/.test(text)) return "sleeve";
    if (/pattern\s*short|short\s*pattern/.test(text)) return "short";
    if (/short/.test(text)) return "short";
    return "";
  }

  const PATTERN_FRONT_COLOR_GUIDE_SRC = "assets/ui/pattern_shirt_front_color_guide.png";
  const PATTERN_BACK_COLOR_GUIDE_SRC = "assets/ui/pattern_shirt_back_color_guide.png";
  const PATTERN_SLEEVE_COLOR_GUIDE_SRC = "assets/ui/pattern_sleeve_short_color_guide.png";
  const PATTERN_SHORT_COLOR_GUIDE_SRC = "assets/ui/pattern_short_color_guide.png";
  const PATTERN_SHORT_VISIBILITY_GUIDE_SRC = "assets/ui/pattern_short_visibility_guide.png";

  async function loadOnePatternPlacementGuide(role, placementGuideSrc) {
    let placementImage = null;
    let placementSrc = placementGuideSrc;
    try {
      const result = await loadImagePromise(placementGuideSrc);
      if (result?.image) {
        placementImage = result.image;
        placementSrc = result.src || placementGuideSrc;
      }
    } catch (error) {
      console.warn(`Pattern ${role} color guide unavailable:`, error);
    }
    if (!placementImage) return null;

    let visibilityImage = null;
    let visibilitySrc = "";
    try {
      if (role === "short") {
        const templateShortGuideMeta = (state.templateStyle?.selected?.guides || []).find((meta) => patternGuideRole(meta) === "short");
        if (templateShortGuideMeta?.path) {
          const visible = await loadImagePromise(templateShortGuideMeta.path);
          if (visible?.image) {
            visibilityImage = visible.image;
            visibilitySrc = visible.src || templateShortGuideMeta.path;
          }
        }
        if (!visibilityImage) {
          const visible = await loadImagePromise(PATTERN_SHORT_VISIBILITY_GUIDE_SRC);
          if (visible?.image) {
            visibilityImage = visible.image;
            visibilitySrc = visible.src || PATTERN_SHORT_VISIBILITY_GUIDE_SRC;
          }
        }
      } else {
        const guideMeta = (state.templateStyle?.selected?.guides || []).find((meta) => patternGuideRole(meta) === role);
        if (guideMeta?.path) {
          const visible = await loadImagePromise(guideMeta.path);
          if (visible?.image) {
            visibilityImage = visible.image;
            visibilitySrc = visible.src || guideMeta.path;
          }
        }
      }
    } catch (error) {
      console.warn(`Pattern ${role} visibility guide unavailable:`, error);
    }

    return {
      role,
      image: placementImage,
      src: placementSrc,
      isColorPlacementGuide: true,
      visibilityImage,
      visibilitySrc,
    };
  }

  async function loadPatternGuidesForLayer(layer) {
    const section = normalizePatternTargetSection(layer?.section || "shirt");
    const loaded = [];
    if (section === "short") {
      // Short Pattern law: yellow/right = 90º counterclockwise; green/left = 90º clockwise.
      // The pattern is auto-scaled to the color-guide boxes, then cropped by pattern short.png.
      const shortGuide = await loadOnePatternPlacementGuide("short", PATTERN_SHORT_COLOR_GUIDE_SRC);
      if (shortGuide) loaded.push(shortGuide);
    } else {
      // v1.0.48: Pattern placement is built step by step by zone.
      // Shirt Front: red = original native pattern; yellow/green = flip H+V.
      // Shirt Back: red = flip H+V; yellow/green = original native pattern.
      // Sleeve Short: cyan/right = rotate 90º counterclockwise; blue/left = rotate 90º clockwise.
      // Each role is then cropped by the matching template guide PNG.
      const front = await loadOnePatternPlacementGuide("front", PATTERN_FRONT_COLOR_GUIDE_SRC);
      if (front) loaded.push(front);
      const back = await loadOnePatternPlacementGuide("back", PATTERN_BACK_COLOR_GUIDE_SRC);
      if (back) loaded.push(back);
      const sleeve = await loadOnePatternPlacementGuide("sleeve", PATTERN_SLEEVE_COLOR_GUIDE_SRC);
      if (sleeve) loaded.push(sleeve);
    }
    layer.patternGuides = loaded;
    return loaded;
  }

  function createUserPatternLayer(item, image) {
    const patternSource = "#000000";
    const patternTarget = normalizeHexColor(item.color || item.targetColor || "#ffffff");
    const layer = {
      id: uid(),
      name: item.name || cleanPatternName(item.file || "Pattern"),
      displayName: item.name || cleanPatternName(item.file || "Pattern"),
      section: normalizePatternTargetSection(item.section || "shirt"),
      folder: item.folder || "Pattern",
      order: Number(item.order ?? 860),
      enabled: true,
      image,
      src: item.src,
      path: item.src,
      loaded: true,
      isUserPattern: item.isUserPattern !== false,
      isUserBaseDesign: item.isUserBaseDesign === true,
      // User Patterns/Base Designs are editable like normal details: eye / color / name / arrows / delete.
      // They are painted through guide masks, so we recolor their ink separately in drawUserPatternLayer().
      noColor: false,
      palette: [patternSource],
      sourceColor: patternSource,
      _detectedColor: patternSource,
      _templateChipColor: patternTarget,
      colorMap: { [patternSource]: patternTarget },
      blend: false,
      opacityCtl: false,
      blendMode: "source-over",
      opacity: 1,
      patternTeam: item.team || "",
      patternFolderPath: Array.isArray(item.pathParts) ? item.pathParts.slice(0, -1) : [],
      baseDesignFolderPath: Array.isArray(item.pathParts) ? item.pathParts.slice(0, -1) : [],
      patternZones: { shirtFront: true, shirtBack: false, sleeveShort: false },
      patternMenuOpen: false,
      patternGuides: [],
    };
    if (baseDesignUsesNativeFullCanvas(layer)) {
      // Full-canvas Base Design PNGs are already centered in Photoshop/KIT texture space.
      // Enable every shirt zone by default so the guide files only crop visibility.
      layer.patternZones = { shirtFront: true, shirtBack: true, sleeveShort: true };
    }
    return layer;
  }

  async function loadFirstPatternImage(candidates = []) {
    const list = uniquePatternUrls(candidates).filter(Boolean).slice(0, 12);
    for (const src of list) {
      const loaded = await loadImagePromise(src);
      if (loaded?.image) return loaded;
    }
    return null;
  }

  async function resolvePatternGalleryItemSource(item) {
    if (!item) return item;
    if (item.src) return item;
    if (item.isPatternFolderItem && Array.isArray(item.pathParts)) {
      const maybeFile = String(item.pathParts[item.pathParts.length - 1] || "");
      if (/\.(png|webp|jpg|jpeg)$/i.test(maybeFile)) {
        return { ...item, src: patternAssetUrl(item.pathParts) };
      }
      const resolved = await resolvePatternFolderItem(item.pathParts.slice(0, -1), maybeFile);
      return { ...item, ...resolved };
    }
    return item;
  }

  async function addUserPatternLayerFromItem(item, options = {}) {
    if (!state.templateStyle?.selected) {
      setStatus("Load a template before adding a Pattern");
      return;
    }
    if (!item) return;
    const targetSection = normalizePatternTargetSection(options?.section || item?.section || state.patternGalleryTargetSection || "shirt");
    const resolvedItem = await resolvePatternGalleryItemSource(item);
    const candidates = uniquePatternUrls([resolvedItem?.src, ...(Array.isArray(resolvedItem?.srcCandidates) ? resolvedItem.srcCandidates : [])]);
    if (!candidates.length) return;
    setStatus(`Loading ${targetSection === "short" ? "short pattern" : "pattern"}: ${resolvedItem.name}`);
    const loaded = await loadFirstPatternImage(candidates);
    if (!loaded?.image) {
      setStatus(`Could not load pattern: ${resolvedItem.name}`);
      return;
    }
    const layer = createUserPatternLayer({ ...resolvedItem, section: targetSection, src: loaded.src || resolvedItem.src || candidates[0], folder: "Pattern", order: 860, isUserPattern: true, isUserBaseDesign: false }, loaded.image);
    await loadPatternGuidesForLayer(layer);
    if (!layer.patternGuides.length) setStatus(`${templatePatternSectionLabel(targetSection)} added without color placement guide`);
    state.templateStyle.details[targetSection].push(layer);
    normalizeAllPatternBelowFabric();
    renderTemplateDetailPanels();
    render();
    closeGallery();
    setStatus(`${targetSection === "short" ? "Short Pattern" : "Pattern"} added: ${layer.name}`);
  }

  async function addUserBaseDesignLayerFromItem(item) {
    if (!state.templateStyle?.selected) {
      setStatus("Load a template before adding a Base Design");
      return;
    }
    if (!item?.src) return;
    setStatus(`Loading base design: ${item.name}`);
    const loaded = await loadImagePromise(item.src);
    if (!loaded?.image) {
      setStatus(`Could not load base design: ${item.name}`);
      return;
    }
    const layer = createUserPatternLayer({
      ...item,
      src: loaded.src || item.src,
      folder: "Base Design",
      order: 850,
      isUserPattern: false,
      isUserBaseDesign: true,
      team: item.team || "Base Design",
    }, loaded.image);
    await loadPatternGuidesForLayer(layer);
    if (!layer.patternGuides.length) setStatus("Base Design added without color placement guide");
    state.templateStyle.details.shirt.push(layer);
    normalizeAllPatternBelowFabric();
    renderTemplateDetailPanels();
    render();
    closeGallery();
    setStatus(`Base Design added: ${layer.name}`);
  }


  function clearSavedSocksStripeLayersForExactProjectRestore(saved = {}) {
    const exactProjectRestore = saved?._loadedFromKitlabProject === true || saved?._savedInsideKitlabProject === true;
    if (!exactProjectRestore || !state.templateStyle?.details) return;
    const list = Array.isArray(state.templateStyle.details.socks) ? state.templateStyle.details.socks : [];
    state.templateStyle.details.socks = list.filter((layer) => !(isGeneratedStripeLayer(layer) && (layer.stripeType || "socks") === "socks"));
  }

  async function ensureSavedGeneratedStripeLayers(savedLayers = []) {
    const savedStripes = (Array.isArray(savedLayers) ? savedLayers : []).filter((layer) => layer && (layer.isGeneratedStripe === true || /^generated:\/+stripe\//i.test(String(layer.src || layer.path || layer.key || ""))));
    if (!savedStripes.length) return [];
    const existingKeys = new Set(allTemplateEditableLayers().map(templateLayerStateKey).map(normalizeLayerSettingsMatchKey));
    const pendingSocksLoads = [];
    for (const saved of savedStripes) {
      const key = saved.key || saved.path || saved.src || `generated://stripe/${saved.stripeType || "socks"}/${saved.name || Date.now()}`;
      const normalizedKey = normalizeLayerSettingsMatchKey(key);
      if (normalizedKey && existingKeys.has(normalizedKey)) continue;
      const type = saved.stripeType === "sleeve_cuffs" ? "sleeve_cuffs" : (saved.stripeType === "short_hem" ? "short_hem" : "socks");
      const layer = createGeneratedStripeLayer(type, {
        key,
        path: key,
        name: saved.displayName || saved.name || stripeLayerDisplayBaseName(type),
        displayName: saved.displayName || saved.name || stripeLayerDisplayBaseName(type),
        enabled: saved.enabled !== false,
        colorMap: saved.colorMap || {},
        color: saved.appliedChipColor || saved.colorMap?.[generatedStripeLayerSourceColor()] || generatedStripeLayerSourceColor(),
        stripeThickness: saved.stripeThickness || saved.thickness,
        stripePosition: saved.stripePosition,
        stripePositionMode: saved.stripePositionMode || "offset",
        stripePositionAuto: saved.stripePositionAuto !== false,
        stripeGuideSrc: saved.stripeGuideSrc || "",
        stripeControlsOpen: saved.stripeControlsOpen === true,
        blendMode: saved.blendMode || "source-over",
        opacity: Number(saved.opacity ?? 1),
        order: Number(saved.orderIndex ?? 875),
      });
      const section = layer.section || (type === "sleeve_cuffs" ? "shirt" : (type === "short_hem" ? "short" : "socks"));
      state.templateStyle.details[section].push(layer);
      if (normalizedKey) existingKeys.add(normalizedKey);
      const hydration = hydrateGeneratedStripeLayerGuide(layer).then((info) => {
        if (!info) console.warn("Saved generated stripe restored without guide:", layer.stripeGuideSrc || layer.name || key);
        renderTemplateDetailPanels();
        render({ immediate: true });
        return info;
      }).catch((error) => {
        console.warn("Generated stripe guide ignored:", error);
        return null;
      });
      // Only Socks Stripes is part of this fix. It must finish before the Project
      // kit is copied into the live runtime cache; the other generated tools keep
      // the exact v1.3.268 background behavior.
      if (type === "socks") pendingSocksLoads.push(hydration);
    }
    if (pendingSocksLoads.length) await Promise.all(pendingSocksLoads);
    return pendingSocksLoads;
  }

  async function ensureSavedUserPatternLayers(savedLayers = []) {
    const savedPatterns = savedLayers.filter((layer) => layer && layer.isUserPattern === true && (layer.src || layer.key));
    if (!savedPatterns.length) return [];
    const existingKeys = new Set(allTemplateEditableLayers().map(templateLayerStateKey));
    const pendingLoads = [];
    for (const saved of savedPatterns) {
      const src = saved.src || saved.key;
      if (!src || existingKeys.has(String(src))) continue;
      const targetSection = normalizePatternTargetSection(saved.section || "shirt");
      const item = {
        name: saved.displayName || saved.name || cleanPatternName(String(src).split("/").pop() || "Pattern"),
        src,
        section: targetSection,
        team: saved.patternTeam || "",
        pathParts: Array.isArray(saved.patternFolderPath) ? [...saved.patternFolderPath, String(src).split("/").pop()] : [],
      };
      const layer = createUserPatternLayer(item, null);
      layer.loaded = false;
      layer.enabled = saved.enabled !== false;
      layer.opacity = Number(saved.opacity ?? 1);
      layer.blendMode = saved.blendMode || "source-over";
      if (targetSection === "shirt" && saved.patternZones && typeof saved.patternZones === "object") {
        layer.patternZones = {
          shirtFront: saved.patternZones.shirtFront !== false,
          shirtBack: saved.patternZones.shirtBack === true,
          sleeveShort: saved.patternZones.sleeveShort === true,
        };
      }
      layer.colorMap = sanitizeTemplateColorMap(layer, saved.colorMap || layer.colorMap || {});
      layer._detectedColor = normalizeHexColor(saved.detectedColor || saved.sourceColor || layer._detectedColor || "#000000");
      layer.sourceColor = normalizeHexColor(saved.sourceColor || layer.sourceColor || layer._detectedColor || "#000000");
      layer.palette = [layer.sourceColor || "#000000"];
      const restoredPatternColor = normalizeHexColor(saved.appliedChipColor || layer.colorMap?.[layer.palette[0]] || layer._templateChipColor || "#ffffff");
      layer._templateChipColor = restoredPatternColor;
      state.templateStyle.details[targetSection].push(layer);
      existingKeys.add(String(src));
      pendingLoads.push((async () => {
        const loaded = await loadImagePromise(src);
        if (!loaded?.image) {
          console.warn("Saved Pattern ignored because its PNG could not load:", src);
          return false;
        }
        layer.image = loaded.image;
        layer.src = loaded.src || src;
        layer.path = layer.src;
        layer.loaded = true;
        await loadPatternGuidesForLayer(layer);
        return true;
      })());
    }
    const restored = await Promise.all(pendingLoads);
    if (pendingLoads.length) {
      normalizeAllPatternBelowFabric();
      renderTemplateDetailPanels();
      render({ immediate: true });
    }
    return restored;
  }

  async function ensureSavedUserBaseDesignLayers(savedLayers = []) {
    const savedDesigns = savedLayers.filter((layer) => layer && layer.isUserBaseDesign === true && (layer.src || layer.key));
    if (!savedDesigns.length) return [];
    const existingKeys = new Set(allTemplateEditableLayers().map(templateLayerStateKey));
    const pendingLoads = [];
    for (const saved of savedDesigns) {
      const src = saved.src || saved.key;
      if (!src || existingKeys.has(String(src))) continue;
      const item = {
        name: saved.displayName || saved.name || cleanPatternName(String(src).split("/").pop() || "Base Design"),
        src,
        team: saved.patternTeam || "Base Design",
        pathParts: Array.isArray(saved.baseDesignFolderPath) ? [...saved.baseDesignFolderPath, String(src).split("/").pop()] : (Array.isArray(saved.patternFolderPath) ? [...saved.patternFolderPath, String(src).split("/").pop()] : []),
      };
      const layer = createUserPatternLayer({ ...item, folder: "Base Design", order: 850, isUserPattern: false, isUserBaseDesign: true }, null);
      layer.loaded = false;
      layer.enabled = saved.enabled !== false;
      layer.opacity = Number(saved.opacity ?? 1);
      layer.blendMode = saved.blendMode || "source-over";
      if (saved.patternZones && typeof saved.patternZones === "object") {
        layer.patternZones = {
          shirtFront: saved.patternZones.shirtFront !== false,
          shirtBack: saved.patternZones.shirtBack === true,
          sleeveShort: saved.patternZones.sleeveShort === true,
        };
      }
      layer.colorMap = sanitizeTemplateColorMap(layer, saved.colorMap || layer.colorMap || {});
      layer._detectedColor = normalizeHexColor(saved.detectedColor || saved.sourceColor || layer._detectedColor || "#000000");
      layer.sourceColor = normalizeHexColor(saved.sourceColor || layer.sourceColor || layer._detectedColor || "#000000");
      layer.palette = [layer.sourceColor || "#000000"];
      const restoredDesignColor = normalizeHexColor(saved.appliedChipColor || layer.colorMap?.[layer.palette[0]] || layer._templateChipColor || "#ffffff");
      layer._templateChipColor = restoredDesignColor;
      state.templateStyle.details.shirt.push(layer);
      existingKeys.add(String(src));
      pendingLoads.push((async () => {
        const loaded = await loadImagePromise(src);
        if (!loaded?.image) {
          console.warn("Saved Base Design ignored because its PNG could not load:", src);
          return false;
        }
        layer.image = loaded.image;
        layer.src = loaded.src || src;
        layer.path = layer.src;
        layer.loaded = true;
        await loadPatternGuidesForLayer(layer);
        return true;
      })());
    }
    const restored = await Promise.all(pendingLoads);
    if (pendingLoads.length) {
      normalizeAllPatternBelowFabric();
      renderTemplateDetailPanels();
      render({ immediate: true });
    }
    return restored;
  }

  function guideImageInfo(guide) {
    if (guide._patternInfo) return guide._patternInfo;
    const canvas = makeCanvas();
    const gx = canvas.getContext("2d", { willReadFrequently: true });
    drawFullSize(gx, guide.image);
    let imageData;
    try { imageData = gx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE); }
    catch { return null; }
    const data = imageData.data;
    const makeMask = () => ({ canvas: makeCanvas(), minX: CANVAS_SIZE, minY: CANVAS_SIZE, maxX: -1, maxY: -1 });
    const masks = { red: makeMask(), yellow: makeMask(), green: makeMask(), cyan: makeMask(), blue: makeMask() };
    const outData = {
      red: masks.red.canvas.getContext("2d").createImageData(CANVAS_SIZE, CANVAS_SIZE),
      yellow: masks.yellow.canvas.getContext("2d").createImageData(CANVAS_SIZE, CANVAS_SIZE),
      green: masks.green.canvas.getContext("2d").createImageData(CANVAS_SIZE, CANVAS_SIZE),
      cyan: masks.cyan.canvas.getContext("2d").createImageData(CANVAS_SIZE, CANVAS_SIZE),
      blue: masks.blue.canvas.getContext("2d").createImageData(CANVAS_SIZE, CANVAS_SIZE),
    };
    const alphaMask = makeMask();
    const alphaData = alphaMask.canvas.getContext("2d").createImageData(CANVAS_SIZE, CANVAS_SIZE);
    const mark = (key, x, y, i) => {
      const m = masks[key];
      const od = outData[key].data;
      od[i] = od[i + 1] = od[i + 2] = 255;
      od[i + 3] = 255;
      if (x < m.minX) m.minX = x;
      if (y < m.minY) m.minY = y;
      if (x > m.maxX) m.maxX = x;
      if (y > m.maxY) m.maxY = y;
    };
    const markAlpha = (x, y, i, a) => {
      const od = alphaData.data;
      od[i] = od[i + 1] = od[i + 2] = 255;
      od[i + 3] = clamp(Number(a) || 0, 0, 255);
      if (x < alphaMask.minX) alphaMask.minX = x;
      if (y < alphaMask.minY) alphaMask.minY = y;
      if (x > alphaMask.maxX) alphaMask.maxX = x;
      if (y > alphaMask.maxY) alphaMask.maxY = y;
    };
    for (let y = 0; y < CANVAS_SIZE; y += 1) {
      for (let x = 0; x < CANVAS_SIZE; x += 1) {
        const i = (y * CANVAS_SIZE + x) * 4;
        const a = data[i + 3];
        if (a < 8) continue;
        const r = data[i], g = data[i + 1], b = data[i + 2];
        // Color guide law: red = main zone; yellow/green = connected zones.
        // Black UV guide lines are ignored by these thresholds.
        if (r > 180 && g < 120 && b < 120) mark("red", x, y, i);
        else if (r > 180 && g > 180 && b < 150) mark("yellow", x, y, i);
        else if (g > 160 && r < 150 && b < 150) mark("green", x, y, i);
        else if (g > 150 && b > 150 && r < 140) mark("cyan", x, y, i);
        else if (b > 160 && r < 130 && g < 130) mark("blue", x, y, i);
        // Backwards compatibility: some existing templates still have white alpha-only guide PNGs.
        // Keep those usable by treating the alpha/white shape as the main red pattern zone.
        const lum = (r + g + b) / 3;
        if (lum > 25) markAlpha(x, y, i, a);
      }
    }
    let hasColorZones = false;
    for (const key of Object.keys(masks)) {
      const ctxMask = masks[key].canvas.getContext("2d");
      ctxMask.putImageData(outData[key], 0, 0);
      const m = masks[key];
      if (m.maxX < 0) {
        m.bbox = null;
      } else {
        hasColorZones = true;
        m.bbox = { x: m.minX, y: m.minY, w: m.maxX - m.minX + 1, h: m.maxY - m.minY + 1 };
      }
    }
    if (!hasColorZones && alphaMask.maxX >= 0) {
      const ctxMask = alphaMask.canvas.getContext("2d");
      ctxMask.putImageData(alphaData, 0, 0);
      masks.red.canvas = alphaMask.canvas;
      masks.red.minX = alphaMask.minX;
      masks.red.minY = alphaMask.minY;
      masks.red.maxX = alphaMask.maxX;
      masks.red.maxY = alphaMask.maxY;
      masks.red.bbox = { x: alphaMask.minX, y: alphaMask.minY, w: alphaMask.maxX - alphaMask.minX + 1, h: alphaMask.maxY - alphaMask.minY + 1 };
      masks.yellow.bbox = null;
      masks.green.bbox = null;
    }
    guide._patternInfo = masks;
    return masks;
  }

  function userPatternTintCanvas(layer) {
    if (!layer?.image) return null;
    const source = templatePaletteSource(layer) || "#000000";
    const target = templateVisibleChipColor(layer, source) || "#ffffff";
    const key = `${layer.src || layer.path || layer.id}|${source}|${target}`;
    if (layer._patternTintCanvas && layer._patternTintKey === key) return layer._patternTintCanvas;

    const srcW = layer.image.naturalWidth || layer.image.width || 1;
    const srcH = layer.image.naturalHeight || layer.image.height || 1;
    const temp = document.createElement("canvas");
    temp.width = srcW;
    temp.height = srcH;
    const tx = temp.getContext("2d", { willReadFrequently: true });
    tx.drawImage(layer.image, 0, 0, srcW, srcH);
    let imageData;
    try { imageData = tx.getImageData(0, 0, srcW, srcH); }
    catch { return layer.image; }
    const data = imageData.data;
    const [tr, tg, tb] = hexToRgbLocal(target);
    let hasTransparency = false;
    for (let i = 3; i < data.length; i += 4) {
      if (data[i] < 250) { hasTransparency = true; break; }
    }
    for (let i = 0; i < data.length; i += 4) {
      const a = data[i + 3];
      if (a <= 0) continue;
      let outA = a;
      if (!hasTransparency) {
        // Opaque JPG-like/white-background PNG fallback: derive an ink mask from darkness.
        const lum = 0.2126 * data[i] + 0.7152 * data[i + 1] + 0.0722 * data[i + 2];
        outA = Math.round(clamp((255 - lum) / 255, 0, 1) * a);
      }
      data[i] = tr;
      data[i + 1] = tg;
      data[i + 2] = tb;
      data[i + 3] = outA;
    }
    tx.putImageData(imageData, 0, 0);
    layer._patternTintCanvas = temp;
    layer._patternTintKey = key;
    return temp;
  }

  function patternPlacementMaskCanvas(guide, role = "front") {
    if (!guide?.image) return null;
    const key = String(role || "front").toLowerCase();
    guide._placementMaskCanvas = guide._placementMaskCanvas || {};
    if (guide._placementMaskCanvas[key]) return guide._placementMaskCanvas[key];
    const info = guideImageInfo(guide);
    if (!info) return null;
    const out = makeCanvas();
    const ox = out.getContext("2d");
    const drawMask = (mask) => {
      if (mask?.canvas && mask?.bbox) ox.drawImage(mask.canvas, 0, 0);
    };
    if (key === "sleeve") {
      drawMask(info.cyan);
      drawMask(info.blue);
    } else if (key === "short") {
      drawMask(info.yellow);
      drawMask(info.green);
    } else {
      drawMask(info.red);
      drawMask(info.yellow);
      drawMask(info.green);
    }
    guide._placementMaskCanvas[key] = out;
    return out;
  }

  function drawFullCanvasBaseDesignLayer(layer, targetCtx = ctx) {
    if (!layer?.image || !baseDesignUsesNativeFullCanvas(layer)) return false;
    const guides = Array.isArray(layer.patternGuides) ? layer.patternGuides : [];
    if (!guides.length) return false;
    const sourceCanvas = userPatternTintCanvas(layer) || layer.image;
    const out = makeCanvas();
    const ox = out.getContext("2d");
    const section = normalizePatternTargetSection(layer?.section || "shirt");
    for (const guide of guides) {
      const role = patternGuideRole(guide);
      if (section === "short") {
        if (role !== "short") continue;
      } else {
        if (role === "short") continue;
        if (role === "front" && !patternZoneEnabled(layer, "shirtFront")) continue;
        if (role === "back" && !patternZoneEnabled(layer, "shirtBack")) continue;
        if (role === "sleeve" && !patternZoneEnabled(layer, "sleeveShort")) continue;
      }
      const placed = makeCanvas();
      const px = placed.getContext("2d");
      // v1.3.161: Full-canvas Base Design PNGs are already centered on the 2048 kit canvas.
      // Pattern stamps are still placed at color-guide bbox origins below; this path only prevents
      // Base Design maps from being shifted when they are already full Photoshop/KIT texture size.
      drawFullSize(px, sourceCanvas);
      const placementMask = patternPlacementMaskCanvas(guide, role);
      if (placementMask) {
        px.save();
        px.globalCompositeOperation = "destination-in";
        px.drawImage(placementMask, 0, 0);
        px.restore();
      }
      const visibilityMask = patternVisibilityMaskCanvas(guide);
      if (visibilityMask) {
        px.save();
        px.globalCompositeOperation = "destination-in";
        px.drawImage(visibilityMask, 0, 0);
        px.restore();
      }
      ox.drawImage(placed, 0, 0);
    }
    targetCtx.save();
    targetCtx.globalAlpha = clamp(Number(layer.opacity ?? 1), 0, 1);
    targetCtx.globalCompositeOperation = layer.blendMode || "source-over";
    targetCtx.drawImage(out, 0, 0);
    targetCtx.restore();
    return true;
  }

  function patternVisibilityMaskCanvas(guide) {
    if (!guide?.visibilityImage) return null;
    if (guide._visibilityMaskCanvas) return guide._visibilityMaskCanvas;
    const source = makeCanvas();
    const sx = source.getContext("2d", { willReadFrequently: true });
    drawFullSize(sx, guide.visibilityImage);
    let imageData;
    try { imageData = sx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE); }
    catch { return null; }
    const data = imageData.data;
    const mask = makeCanvas();
    const mx = mask.getContext("2d");
    const out = mx.createImageData(CANVAS_SIZE, CANVAS_SIZE);
    const od = out.data;
    let visiblePixels = 0;
    let alphaPixels = 0;
    const writeMaskPixel = (i, a) => {
      od[i] = od[i + 1] = od[i + 2] = 255;
      od[i + 3] = a;
    };
    for (let i = 0; i < data.length; i += 4) {
      const a = data[i + 3];
      if (a < 4) continue;
      alphaPixels += 1;
      // The guide file decides visibility. White/color masks are accepted directly.
      // Some KitLab guide PNGs are black silhouettes with alpha, so those need an alpha fallback below.
      const lum = (data[i] + data[i + 1] + data[i + 2]) / 3;
      if (lum < 4) continue;
      writeMaskPixel(i, a);
      visiblePixels += 1;
    }
    // v1.3.74: black alpha guide silhouettes must also work as Pattern visibility masks.
    // If the first pass found no light/color pixels but the guide has alpha, use alpha as the mask.
    if (!visiblePixels && alphaPixels) {
      for (let i = 0; i < data.length; i += 4) {
        const a = data[i + 3];
        if (a < 4) continue;
        writeMaskPixel(i, a);
      }
    }
    mx.putImageData(out, 0, 0);
    guide._visibilityMaskCanvas = mask;
    return mask;
  }

  function drawPatternIntoGuideMask(outCtx, patternImage, maskInfo, flipHV = false) {
    if (!patternImage || !maskInfo?.bbox) return;
    const { x, y } = maskInfo.bbox;
    const srcW = patternImage.naturalWidth || patternImage.width || 1;
    const srcH = patternImage.naturalHeight || patternImage.height || 1;
    const temp = makeCanvas();
    const tx = temp.getContext("2d");
    tx.save();
    // Pattern source PNGs are already the exact size of the color rectangles.
    // Never scale: place native size at the colored guide bbox origin.
    if (flipHV) {
      tx.translate(x + srcW, y + srcH);
      tx.scale(-1, -1);
      tx.drawImage(patternImage, 0, 0, srcW, srcH);
    } else {
      tx.drawImage(patternImage, x, y, srcW, srcH);
    }
    tx.restore();
    outCtx.drawImage(temp, 0, 0);
  }

  function drawRotatedPatternIntoGuideMask(outCtx, patternImage, maskInfo, direction = "cw") {
    if (!patternImage || !maskInfo?.bbox) return;
    const { x, y } = maskInfo.bbox;
    const srcW = patternImage.naturalWidth || patternImage.width || 1;
    const srcH = patternImage.naturalHeight || patternImage.height || 1;
    const temp = makeCanvas();
    const tx = temp.getContext("2d");
    tx.save();
    // Sleeve Short law: no scaling. Right/cyan = 90º counterclockwise; left/blue = 90º clockwise.
    if (direction === "ccw") {
      tx.translate(x, y + srcW);
      tx.rotate(-Math.PI / 2);
    } else {
      tx.translate(x + srcH, y);
      tx.rotate(Math.PI / 2);
    }
    tx.drawImage(patternImage, 0, 0, srcW, srcH);
    tx.restore();
    outCtx.drawImage(temp, 0, 0);
  }

  function drawRotatedScaledPatternIntoGuideMask(outCtx, patternImage, maskInfo, direction = "cw") {
    if (!patternImage || !maskInfo?.bbox) return;
    const { x, y, w, h } = maskInfo.bbox;
    const srcW = patternImage.naturalWidth || patternImage.width || 1;
    const srcH = patternImage.naturalHeight || patternImage.height || 1;
    const scale = Math.max((Number(w) || 1) / Math.max(1, srcH), (Number(h) || 1) / Math.max(1, srcW));
    const drawW = Math.max(1, srcW * scale);
    const drawH = Math.max(1, srcH * scale);
    const temp = makeCanvas();
    const tx = temp.getContext("2d");
    tx.save();
    tx.beginPath();
    tx.rect(x, y, Math.max(1, w), Math.max(1, h));
    tx.clip();
    tx.translate(x + (Math.max(1, w) / 2), y + (Math.max(1, h) / 2));
    tx.rotate(direction === "ccw" ? -Math.PI / 2 : Math.PI / 2);
    tx.drawImage(patternImage, -drawW / 2, -drawH / 2, drawW, drawH);
    tx.restore();
    outCtx.drawImage(temp, 0, 0);
  }

  function drawUserPatternLayer(layer, targetCtx = ctx) {
    if (!layer?.image) return;
    if (drawFullCanvasBaseDesignLayer(layer, targetCtx)) return;
    const guides = Array.isArray(layer.patternGuides) ? layer.patternGuides : [];
    if (!guides.length) {
      // Fallback: keep it non-destructive and visible only if there are no template guides.
      const patternCanvas = userPatternTintCanvas(layer) || layer.image;
      targetCtx.save();
      targetCtx.globalAlpha = clamp(Number(layer.opacity ?? 1), 0, 1);
      targetCtx.globalCompositeOperation = layer.blendMode || "source-over";
      targetCtx.drawImage(patternCanvas, 0, 0, patternCanvas.width || layer.image.naturalWidth || layer.image.width, patternCanvas.height || layer.image.naturalHeight || layer.image.height);
      targetCtx.restore();
      return;
    }
    const patternCanvas = userPatternTintCanvas(layer) || layer.image;
    const out = makeCanvas();
    const ox = out.getContext("2d");
    const section = normalizePatternTargetSection(layer?.section || "shirt");
    for (const guide of guides) {
      const role = patternGuideRole(guide);
      if (section === "short") {
        if (role !== "short") continue;
      } else {
        if (role === "short") continue;
        if (role === "front" && !patternZoneEnabled(layer, "shirtFront")) continue;
        if (role === "back" && !patternZoneEnabled(layer, "shirtBack")) continue;
        if (role === "sleeve" && !patternZoneEnabled(layer, "sleeveShort")) continue;
      }
      const info = guideImageInfo(guide);
      if (!info) continue;
      const placed = makeCanvas();
      const px = placed.getContext("2d");
      // Step 1: draw the full placement from the color guide.
      // Shirt keeps the existing laws.
      // Short: yellow/right = 90º counterclockwise; green/left = 90º clockwise; both auto-scale to the guide boxes.
      const isBackGuide = role === "back";
      if (role === "sleeve") {
        drawRotatedPatternIntoGuideMask(px, patternCanvas, info.cyan, "ccw");
        drawRotatedPatternIntoGuideMask(px, patternCanvas, info.blue, "cw");
      } else if (role === "short") {
        drawRotatedScaledPatternIntoGuideMask(px, patternCanvas, info.yellow, "ccw");
        drawRotatedScaledPatternIntoGuideMask(px, patternCanvas, info.green, "cw");
      } else {
        drawPatternIntoGuideMask(px, patternCanvas, info.red, isBackGuide);
        drawPatternIntoGuideMask(px, patternCanvas, info.yellow, !isBackGuide);
        drawPatternIntoGuideMask(px, patternCanvas, info.green, !isBackGuide);
      }

      // Step 2: crop visibility with the matching template guide PNG.
      const visibilityMask = patternVisibilityMaskCanvas(guide);
      if (visibilityMask) {
        px.save();
        px.globalCompositeOperation = "destination-in";
        px.drawImage(visibilityMask, 0, 0);
        px.restore();
      }
      ox.drawImage(placed, 0, 0);
    }
    targetCtx.save();
    targetCtx.globalAlpha = clamp(Number(layer.opacity ?? 1), 0, 1);
    targetCtx.globalCompositeOperation = layer.blendMode || "source-over";
    targetCtx.drawImage(out, 0, 0);
    targetCtx.restore();
  }


  function generatedStripeLayerSourceColor() {
    return "#ffffff";
  }

  function isGeneratedStripeLayer(layer = {}) {
    return layer?.isGeneratedStripe === true || /^generated:\/\/stripe\//i.test(String(layer?.src || layer?.path || layer?.key || ""));
  }

  function stripeLayerDisplayBaseName(type = "socks") {
    if (type === "sleeve_cuffs") return "Sleeve Cuff";
    if (type === "short_hem") return "Short Hem";
    return "Socks Stripe";
  }

  function stripeLayerUiLabel(type = "socks") {
    if (type === "sleeve_cuffs") return "Sleeve Cuffs";
    if (type === "short_hem") return "Short Hem";
    return "Socks Stripes";
  }

  function generatedStripeIsVertical(layerOrType = "socks") {
    const type = typeof layerOrType === "string" ? layerOrType : (layerOrType?.stripeType || "socks");
    const direction = typeof layerOrType === "string" ? "" : String(layerOrType?.stripeDirection || "");
    return type === "sleeve_cuffs" || type === "short_hem" || direction === "vertical";
  }

  function stripeGuideSleeveComponents(info = null) {
    const comps = Array.isArray(info?.components) ? info.components.slice() : [];
    const usable = comps.filter((comp) => comp && comp.maxX >= comp.minX && comp.maxY >= comp.minY)
      .sort((a, b) => (a.centerX || 0) - (b.centerX || 0));
    if (usable.length >= 2) return [usable[0], usable[usable.length - 1]];
    if (usable.length === 1) return [usable[0]];
    if (info && info.maxX >= info.minX && info.maxY >= info.minY) {
      return [{
        minX: info.minX,
        minY: info.minY,
        maxX: info.maxX,
        maxY: info.maxY,
        centerX: info.centerX,
        centerY: info.centerY,
        width: info.maxX - info.minX + 1,
        height: info.maxY - info.minY + 1,
        count: 0,
      }];
    }
    return [];
  }

  function stripeGuideVerticalComponents(info = null) {
    const comps = Array.isArray(info?.components) ? info.components.slice() : [];
    const usable = comps.filter((comp) => comp && comp.maxX >= comp.minX && comp.maxY >= comp.minY)
      .sort((a, b) => ((a.centerX || 0) - (b.centerX || 0)) || ((a.centerY || 0) - (b.centerY || 0)));
    if (usable.length) return usable;
    if (info && info.maxX >= info.minX && info.maxY >= info.minY) {
      return [{
        minX: info.minX,
        minY: info.minY,
        maxX: info.maxX,
        maxY: info.maxY,
        centerX: info.centerX,
        centerY: info.centerY,
        width: info.maxX - info.minX + 1,
        height: info.maxY - info.minY + 1,
        count: 0,
      }];
    }
    return [];
  }

  function sleeveCuffSymmetricGeometry(info = null) {
    const comps = stripeGuideSleeveComponents(info);
    if (comps.length < 2) return null;
    const left = comps[0];
    const right = comps[1];
    const leftCenter = Math.round((left.minX + left.maxX) / 2);
    // Do not trust the detected right component center for generated Sleeve Cuffs.
    // A single antialiased pixel in the guide/right component can move the detected
    // bounding box by 1px. The right stripe must be the exact mirror distance from
    // the kit/canvas center, using the left side as the anchor.
    const rightCenter = clamp((CANVAS_SIZE - 1) - leftCenter, 0, CANVAS_SIZE - 1);
    const width = Math.max(1, Math.round(Math.max(left.width || (left.maxX - left.minX + 1), right.width || (right.maxX - right.minX + 1))));
    const minY = clamp(Math.min(left.minY, right.minY), 0, CANVAS_SIZE - 1);
    const maxY = clamp(Math.max(left.maxY, right.maxY), 0, CANVAS_SIZE - 1);
    const before = Math.floor((width - 1) / 2);
    const after = (width - 1) - before;
    const makeBox = (centerX) => ({
      centerX,
      minX: clamp(centerX - before, 0, CANVAS_SIZE - 1),
      maxX: clamp(centerX + after, 0, CANVAS_SIZE - 1),
      minY,
      maxY,
      width,
      height: Math.max(1, maxY - minY + 1),
    });
    return { left: makeBox(leftCenter), right: makeBox(rightCenter), width, minY, maxY };
  }

  function sleeveCuffSymmetricMask(info = null) {
    if (!info) return null;
    if (info._sleeveCuffSymmetricMask) return info._sleeveCuffSymmetricMask;
    const geom = sleeveCuffSymmetricGeometry(info);
    if (!geom) return null;
    const mask = makeCanvas();
    const mx = mask.getContext("2d");
    mx.fillStyle = "#fff";
    for (const box of [geom.left, geom.right]) {
      const x = Math.round(box.minX);
      const y = Math.round(box.minY);
      const w = Math.max(1, Math.round(box.maxX - box.minX + 1));
      const h = Math.max(1, Math.round(box.maxY - box.minY + 1));
      mx.fillRect(x, y, w, h);
    }
    info._sleeveCuffSymmetricMask = mask;
    return mask;
  }

  function shortHemSymmetricPairs(info = null) {
    if (!info) return [];
    if (Array.isArray(info._shortHemSymmetricPairs)) return info._shortHemSymmetricPairs;
    const comps = stripeGuideVerticalComponents(info)
      .filter((comp) => comp && comp.maxX >= comp.minX && comp.maxY >= comp.minY);
    const canvasCenter = (CANVAS_SIZE - 1) / 2;
    const left = comps.filter((comp) => ((comp.minX + comp.maxX) / 2) < canvasCenter)
      .sort((a, b) => (((a.minY + a.maxY) / 2) - ((b.minY + b.maxY) / 2)) || (((a.minX + a.maxX) / 2) - ((b.minX + b.maxX) / 2)));
    const right = comps.filter((comp) => ((comp.minX + comp.maxX) / 2) >= canvasCenter)
      .sort((a, b) => (((a.minY + a.maxY) / 2) - ((b.minY + b.maxY) / 2)) || (((a.minX + a.maxX) / 2) - ((b.minX + b.maxX) / 2)));
    const usedRight = new Set();
    const pairs = [];
    for (const l of left) {
      const lCenterY = (l.minY + l.maxY) / 2;
      let bestIndex = -1;
      let bestScore = Infinity;
      for (let i = 0; i < right.length; i += 1) {
        if (usedRight.has(i)) continue;
        const r = right[i];
        const rCenterY = (r.minY + r.maxY) / 2;
        const score = Math.abs(rCenterY - lCenterY);
        if (score < bestScore) {
          bestScore = score;
          bestIndex = i;
        }
      }
      if (bestIndex >= 0) {
        usedRight.add(bestIndex);
        pairs.push({ left: l, right: right[bestIndex] });
      }
    }
    info._shortHemSymmetricPairs = pairs;
    return pairs;
  }

  function shortHemPrimaryComponents(info = null) {
    const pairs = shortHemSymmetricPairs(info);
    if (pairs.length) return pairs.flatMap((pair) => [pair.left, pair.right]);
    return stripeGuideVerticalComponents(info);
  }

  function mirroredStripeStart(centerX, thickness, side = "left") {
    const t = Math.max(1, Math.round(thickness || 1));
    const before = Math.floor((t - 1) / 2);
    const after = (t - 1) - before;
    return Math.round(centerX - (side === "right" ? after : before));
  }

  function generatedStripeMaxThickness(type = "socks", layer = null, info = null) {
    if (type === "sleeve_cuffs") {
      const guideInfo = info || (layer ? computeStripeGuideInfo(layer) : null);
      const geom = sleeveCuffSymmetricGeometry(guideInfo);
      if (geom?.width) return Math.max(1, Math.round(geom.width));
      const component = stripeGuideSleeveComponents(guideInfo)[0];
      const detected = component ? Math.round(component.maxX - component.minX + 1) : 0;
      return Math.max(1, detected || 50);
    }
    if (type === "short_hem") {
      const guideInfo = info || (layer ? computeStripeGuideInfo(layer) : null);
      const widths = shortHemPrimaryComponents(guideInfo).map((comp) => Math.round(comp.maxX - comp.minX + 1)).filter((value) => value > 0);
      return Math.max(1, widths.length ? Math.min(...widths) : 50);
    }
    // Socks stripes need wider bands for real kit sock hoops.
    return 100;
  }

  function stripeGuideCenterForLayer(layer = {}, info = null) {
    if (!info) return Math.round(CANVAS_SIZE / 2);
    const isVertical = generatedStripeIsVertical(layer);
    return isVertical ? info.centerX : info.centerY;
  }

  function stripePositionOffsetRange(layer = {}, info = null) {
    const type = layer.stripeType || "socks";
    const isSleeve = type === "sleeve_cuffs";
    const isShortHem = type === "short_hem";
    const isVertical = isSleeve || isShortHem || layer.stripeDirection === "vertical";
    if (!info) return { min: -Math.round(CANVAS_SIZE / 2), max: Math.round(CANVAS_SIZE / 2), center: Math.round(CANVAS_SIZE / 2) };
    const center = stripeGuideCenterForLayer(layer, info);
    if (isVertical) {
      if (isSleeve) {
        const geom = sleeveCuffSymmetricGeometry(info);
        const components = stripeGuideSleeveComponents(info);
        if (geom?.left && components.length >= 2) {
          const left = components[0];
          const right = components[components.length - 1];
          const c = Math.round(geom.left.centerX);
          const thickness = Math.max(1, Math.round(Number(layer.stripeThickness || 1)));
          const before = Math.floor((thickness - 1) / 2);
          const after = (thickness - 1) - before;
          // The right cuff stripe is painted as a real mirror of the left one around
          // the 2048 texture center. The position range must therefore be the shared
          // legal range where BOTH the left stripe and its mirrored right stripe stay
          // inside their original guide components. Otherwise at max/min one side can
          // be pushed one pixel outside its guide and disappear/clamp differently.
          const leftMin = Math.ceil(left.minX - c + before);
          const leftMax = Math.floor(left.maxX - c - after);
          const rightMin = Math.ceil((CANVAS_SIZE - 1) - right.maxX - c + before);
          const rightMax = Math.floor((CANVAS_SIZE - 1) - right.minX - c - after);
          const min = Math.max(leftMin, rightMin);
          const max = Math.min(leftMax, rightMax);
          if (Number.isFinite(min) && Number.isFinite(max) && min <= max) return { min, max, center: c };
          return { min: 0, max: 0, center: c };
        }
        if (geom?.left) {
          const c = Math.round(geom.left.centerX);
          return { min: Math.round(geom.left.minX - c), max: Math.round(geom.left.maxX - c), center: c };
        }
        const component = components[0];
        if (component) {
          const c = Math.round((component.minX + component.maxX) / 2);
          return { min: Math.round(component.minX - c), max: Math.round(component.maxX - c), center: c };
        }
        return { min: Math.round(info.minX - center), max: Math.round(info.maxX - center), center };
      }
      if (isShortHem) {
        const pairs = shortHemSymmetricPairs(info);
        const components = stripeGuideVerticalComponents(info);
        const thickness = Math.max(1, Math.round(Number(layer.stripeThickness || 1)));
        const before = Math.floor((thickness - 1) / 2);
        const after = (thickness - 1) - before;
        const mins = [];
        const maxs = [];
        if (pairs.length) {
          for (const pair of pairs) {
            const left = pair.left;
            const right = pair.right;
            const c = Math.round((left.minX + left.maxX) / 2);
            mins.push(Math.ceil(left.minX - c + before));
            maxs.push(Math.floor(left.maxX - c - after));
            mins.push(Math.ceil((CANVAS_SIZE - 1) - right.maxX - c + before));
            maxs.push(Math.floor((CANVAS_SIZE - 1) - right.minX - c - after));
          }
        } else {
          for (const comp of components) {
            const c = Math.round((comp.minX + comp.maxX) / 2);
            mins.push(Math.ceil(comp.minX - c + before));
            maxs.push(Math.floor(comp.maxX - c - after));
          }
        }
        const min = mins.length ? Math.max(...mins) : Math.round(info.minX - center);
        const max = maxs.length ? Math.min(...maxs) : Math.round(info.maxX - center);
        if (Number.isFinite(min) && Number.isFinite(max) && min <= max) return { min, max, center: 0 };
        return { min: 0, max: 0, center: 0 };
      }
      return { min: Math.round(info.minX - center), max: Math.round(info.maxX - center), center };
    }
    // Socks: positive Position moves the stripe upward, so absolute Y = center - offset.
    return { min: Math.round(center - info.maxY), max: Math.round(center - info.minY), center };
  }

  function normalizeGeneratedStripePositionToOffset(layer = {}, info = null) {
    if (!isGeneratedStripeLayer(layer)) return;
    const isVertical = generatedStripeIsVertical(layer);
    if (layer.stripePositionMode === "offset") {
      if (!Number.isFinite(Number(layer.stripePosition))) layer.stripePosition = 0;
      return;
    }
    const center = stripeGuideCenterForLayer(layer, info);
    const oldValue = Number(layer.stripePosition);
    if (Number.isFinite(oldValue) && info && oldValue >= (isVertical ? info.minX : info.minY) && oldValue <= (isVertical ? info.maxX : info.maxY)) {
      layer.stripePosition = isVertical ? Math.round(oldValue - center) : Math.round(center - oldValue);
    } else {
      layer.stripePosition = 0;
    }
    layer.stripePositionMode = "offset";
  }

