  function drawUv() {
    if (state.showUv && uvImage.complete) {
      ctx.save();
      ctx.globalAlpha = clamp(Number(state.uvOpacity ?? 1), 0, 1);
      ctx.drawImage(uvImage, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
      ctx.restore();
    }
  }

  function drawGuide() {
    if (state.showGuide && guideImage.complete) {
      ctx.save();
      ctx.globalAlpha = clamp(Number(state.guideOpacity ?? 1), 0, 1);
      ctx.drawImage(guideImage, 0, 0, CANVAS_SIZE, CANVAS_SIZE);
      ctx.restore();
    }
  }

  function drawSlotBoxes() {
    if (!state.showSlotBoxes) return;
    ctx.save();
    ctx.font = "700 24px Arial";
    ctx.textBaseline = "top";
    for (const [part, info] of Object.entries(BRAND_PARTS)) {
      for (const targetId of getBrandTargetsForPart(part)) {
        const slot = SLOT_BY_ID[targetId];
        if (!slot) continue;
        const box = slot.box;
        ctx.fillStyle = "rgba(101,163,255,0.10)";
        ctx.strokeStyle = state.expandedParts[part] ? "#65a3ff" : "rgba(34,197,94,0.9)";
        ctx.lineWidth = state.expandedParts[part] ? 5 : 3;
        ctx.fillRect(box.x, box.y, box.w, box.h);
        ctx.strokeRect(box.x, box.y, box.w, box.h);
        ctx.beginPath();
        ctx.moveTo(box.x + box.w / 2, box.y);
        ctx.lineTo(box.x + box.w / 2, box.y + box.h);
        ctx.moveTo(box.x, box.y + box.h / 2);
        ctx.lineTo(box.x + box.w, box.y + box.h / 2);
        ctx.stroke();

        ctx.lineWidth = 7;
        ctx.strokeStyle = "rgba(0,0,0,0.75)";
        ctx.strokeText(targetId, box.x, Math.max(8, box.y - 30));
        ctx.fillStyle = "#dbeafe";
        ctx.fillText(targetId, box.x, Math.max(8, box.y - 30));
      }
    }
    ctx.restore();
  }

  function fastRender() { scheduleRender({ fastPreview: true }); }

